EMBEDDED_SOURCES = {'_shared_test_resources/code/EdgeTAM/gradio_app.py': '# Copyright (c) Meta Platforms, Inc. and affiliates.\n# All rights reserved.\n\n# This source code is licensed under the license found in the\n# LICENSE file in the root directory of this source tree.\n\nimport copy\nimport os\nfrom datetime import datetime\n\nimport gradio as gr\n\nos.environ["TORCH_CUDNN_SDPA_ENABLED"] = "0,1,2,3,4,5,6,7"\nimport tempfile\n\nimport cv2\nimport matplotlib.pyplot as plt\nimport numpy as np\nimport torch\nfrom moviepy.editor import ImageSequenceClip\nfrom PIL import Image\nfrom sam2.build_sam import build_sam2_video_predictor\n\n# Description\ntitle = "<center><strong><font size=\'8\'>EdgeTAM<font></strong> <a href=\'https://github.com/facebookresearch/EdgeTAM\'><font size=\'6\'>[GitHub]</font></a> </center>"\n\ndescription_p = """# Instructions\n                <ol>\n                <li> Upload one video or click one example video</li>\n                <li> Click \'include\' point type, select the object to segment and track</li>\n                <li> Click \'exclude\' point type (optional), select the area you want to avoid segmenting and tracking</li>\n                <li> Click the \'Track\' button to obtain the masked video </li>\n                </ol>\n              """\n\n# examples\nexamples = [\n    ["examples/01_dog.mp4"],\n    ["examples/02_cups.mp4"],\n    ["examples/03_blocks.mp4"],\n    ["examples/04_coffee.mp4"],\n    ["examples/05_default_juggle.mp4"],\n    ["examples/01_breakdancer.mp4"],\n    ["examples/02_hummingbird.mp4"],\n    ["examples/03_skateboarder.mp4"],\n    ["examples/04_octopus.mp4"],\n    ["examples/05_landing_dog_soccer.mp4"],\n    ["examples/06_pingpong.mp4"],\n    ["examples/07_snowboarder.mp4"],\n    ["examples/08_driving.mp4"],\n    ["examples/09_birdcartoon.mp4"],\n    ["examples/10_cloth_magic.mp4"],\n    ["examples/11_polevault.mp4"],\n    ["examples/12_hideandseek.mp4"],\n    ["examples/13_butterfly.mp4"],\n    ["examples/14_social_dog_training.mp4"],\n    ["examples/15_cricket.mp4"],\n    ["examples/16_robotarm.mp4"],\n    ["examples/17_childrendancing.mp4"],\n    ["examples/18_threedogs.mp4"],\n    ["examples/19_cyclist.mp4"],\n    ["examples/20_doughkneading.mp4"],\n    ["examples/21_biker.mp4"],\n    ["examples/22_dogskateboarder.mp4"],\n    ["examples/23_racecar.mp4"],\n    ["examples/24_clownfish.mp4"],\n]\n\nOBJ_ID = 0\n\nif torch.backends.mps.is_available():\n    DEVICE = "mps"\nelif torch.cuda.is_available():\n    DEVICE = "cuda"\nelse:\n    DEVICE = "cpu"\nsam2_checkpoint = "checkpoints/edgetam.pt"\nmodel_cfg = "edgetam.yaml"\npredictor = build_sam2_video_predictor(model_cfg, sam2_checkpoint, device=DEVICE)\nprint("PREDICTOR LOADED")\n\n# use bfloat16 for the entire notebook\nif torch.cuda.is_available():\n    torch.autocast(device_type=DEVICE, dtype=torch.bfloat16).__enter__()\n    if torch.cuda.get_device_properties(0).major >= 8:\n        # turn on tfloat32 for Ampere GPUs (https://pytorch.org/docs/stable/notes/cuda.html#tensorfloat-32-tf32-on-ampere-devices)\n        torch.backends.cuda.matmul.allow_tf32 = True\n        torch.backends.cudnn.allow_tf32 = True\n\n\ndef get_video_fps(video_path):\n    # Open the video file\n    cap = cv2.VideoCapture(video_path)\n\n    if not cap.isOpened():\n        print("Error: Could not open video.")\n        return None\n\n    # Get the FPS of the video\n    fps = cap.get(cv2.CAP_PROP_FPS)\n\n    return fps\n\n\ndef reset(session_state):\n    session_state["input_points"] = []\n    session_state["input_labels"] = []\n    if session_state["inference_state"] is not None:\n        predictor.reset_state(session_state["inference_state"])\n    session_state["first_frame"] = None\n    session_state["all_frames"] = None\n    session_state["inference_state"] = None\n    return (\n        None,\n        gr.update(open=True),\n        None,\n        None,\n        gr.update(value=None, visible=False),\n        session_state,\n    )\n\n\ndef clear_points(session_state):\n    session_state["input_points"] = []\n    session_state["input_labels"] = []\n    if session_state["inference_state"]["tracking_has_started"]:\n        predictor.reset_state(session_state["inference_state"])\n    return (\n        session_state["first_frame"],\n        None,\n        gr.update(value=None, visible=False),\n        session_state,\n    )\n\n\ndef preprocess_video_in(video_path, session_state):\n    if video_path is None:\n        return (\n            gr.update(open=True),  # video_in_drawer\n            None,  # points_map\n            None,  # output_image\n            gr.update(value=None, visible=False),  # output_video\n            session_state,\n        )\n\n    # Read the first frame\n    cap = cv2.VideoCapture(video_path)\n    if not cap.isOpened():\n        print("Error: Could not open video.")\n        return (\n            gr.update(open=True),  # video_in_drawer\n            None,  # points_map\n            None,  # output_image\n            gr.update(value=None, visible=False),  # output_video\n            session_state,\n        )\n\n    frame_number = 0\n    first_frame = None\n    all_frames = []\n\n    while True:\n        ret, frame = cap.read()\n        if not ret:\n            break\n\n        frame = cv2.cvtColor(frame, cv2.COLOR_BGR2RGB)\n        frame = np.array(frame)\n\n        # Store the first frame\n        if frame_number == 0:\n            first_frame = frame\n        all_frames.append(frame)\n\n        frame_number += 1\n\n    cap.release()\n    session_state["first_frame"] = copy.deepcopy(first_frame)\n    session_state["all_frames"] = all_frames\n\n    session_state["inference_state"] = predictor.init_state(video_path=video_path)\n    session_state["input_points"] = []\n    session_state["input_labels"] = []\n\n    return [\n        gr.update(open=False),  # video_in_drawer\n        first_frame,  # points_map\n        None,  # output_image\n        gr.update(value=None, visible=False),  # output_video\n        session_state,\n    ]\n\n\ndef segment_with_points(\n    point_type,\n    session_state,\n    evt: gr.SelectData,\n):\n    session_state["input_points"].append(evt.index)\n    print(f"TRACKING INPUT POINT: {session_state[\'input_points\']}")\n\n    if point_type == "include":\n        session_state["input_labels"].append(1)\n    elif point_type == "exclude":\n        session_state["input_labels"].append(0)\n    print(f"TRACKING INPUT LABEL: {session_state[\'input_labels\']}")\n\n    # Open the image and get its dimensions\n    transparent_background = Image.fromarray(session_state["first_frame"]).convert(\n        "RGBA"\n    )\n    w, h = transparent_background.size\n\n    # Define the circle radius as a fraction of the smaller dimension\n    fraction = 0.01  # You can adjust this value as needed\n    radius = int(fraction * min(w, h))\n\n    # Create a transparent layer to draw on\n    transparent_layer = np.zeros((h, w, 4), dtype=np.uint8)\n\n    for index, track in enumerate(session_state["input_points"]):\n        if session_state["input_labels"][index] == 1:\n            cv2.circle(transparent_layer, track, radius, (0, 255, 0, 255), -1)\n        else:\n            cv2.circle(transparent_layer, track, radius, (255, 0, 0, 255), -1)\n\n    # Convert the transparent layer back to an image\n    transparent_layer = Image.fromarray(transparent_layer, "RGBA")\n    selected_point_map = Image.alpha_composite(\n        transparent_background, transparent_layer\n    )\n\n    # Let\'s add a positive click at (x, y) = (210, 350) to get started\n    points = np.array(session_state["input_points"], dtype=np.float32)\n    # for labels, `1` means positive click and `0` means negative click\n    labels = np.array(session_state["input_labels"], np.int32)\n    _, _, out_mask_logits = predictor.add_new_points(\n        inference_state=session_state["inference_state"],\n        frame_idx=0,\n        obj_id=OBJ_ID,\n        points=points,\n        labels=labels,\n    )\n\n    mask_image = show_mask((out_mask_logits[0] > 0.0).cpu().numpy())\n    first_frame_output = Image.alpha_composite(transparent_background, mask_image)\n\n    torch.cuda.empty_cache()\n    return selected_point_map, first_frame_output, session_state\n\n\ndef show_mask(mask, obj_id=None, random_color=False, convert_to_image=True):\n    if random_color:\n        color = np.concatenate([np.random.random(3), np.array([0.6])], axis=0)\n    else:\n        cmap = plt.get_cmap("tab10")\n        cmap_idx = 0 if obj_id is None else obj_id\n        color = np.array([*cmap(cmap_idx)[:3], 0.6])\n    h, w = mask.shape[-2:]\n    mask = mask.reshape(h, w, 1) * color.reshape(1, 1, -1)\n    mask = (mask * 255).astype(np.uint8)\n    if convert_to_image:\n        mask = Image.fromarray(mask, "RGBA")\n    return mask\n\n\ndef propagate_to_all(\n    video_in,\n    session_state,\n):\n    if (\n        len(session_state["input_points"]) == 0\n        or video_in is None\n        or session_state["inference_state"] is None\n    ):\n        return (\n            None,\n            session_state,\n        )\n\n    # run propagation throughout the video and collect the results in a dict\n    video_segments = {}  # video_segments contains the per-frame segmentation results\n    print("starting propagate_in_video")\n    for out_frame_idx, out_obj_ids, out_mask_logits in predictor.propagate_in_video(\n        session_state["inference_state"]\n    ):\n        video_segments[out_frame_idx] = {\n            out_obj_id: (out_mask_logits[i] > 0.0).cpu().numpy()\n            for i, out_obj_id in enumerate(out_obj_ids)\n        }\n\n    # obtain the segmentation results every few frames\n    vis_frame_stride = 1\n\n    output_frames = []\n    for out_frame_idx in range(0, len(video_segments), vis_frame_stride):\n        transparent_background = Image.fromarray(\n            session_state["all_frames"][out_frame_idx]\n        ).convert("RGBA")\n        out_mask = video_segments[out_frame_idx][OBJ_ID]\n        mask_image = show_mask(out_mask)\n        output_frame = Image.alpha_composite(transparent_background, mask_image)\n        output_frame = np.array(output_frame)\n        output_frames.append(output_frame)\n\n    torch.cuda.empty_cache()\n\n    # Create a video clip from the image sequence\n    original_fps = get_video_fps(video_in)\n    fps = original_fps  # Frames per second\n    clip = ImageSequenceClip(output_frames, fps=fps)\n    # Write the result to a file\n    unique_id = datetime.now().strftime("%Y%m%d%H%M%S")\n    final_vid_output_path = f"output_video_{unique_id}.mp4"\n    final_vid_output_path = os.path.join(tempfile.gettempdir(), final_vid_output_path)\n\n    # Write the result to a file\n    clip.write_videofile(final_vid_output_path, codec="libx264")\n\n    return (\n        gr.update(value=final_vid_output_path),\n        session_state,\n    )\n\n\ndef update_ui():\n    return gr.update(visible=True)\n\n\nwith gr.Blocks() as demo:\n    session_state = gr.State(\n        {\n            "first_frame": None,\n            "all_frames": None,\n            "input_points": [],\n            "input_labels": [],\n            "inference_state": None,\n        }\n    )\n\n    with gr.Column():\n        # Title\n        gr.Markdown(title)\n        with gr.Row():\n\n            with gr.Column():\n                # Instructions\n                gr.Markdown(description_p)\n\n                with gr.Accordion("Input Video", open=True) as video_in_drawer:\n                    video_in = gr.Video(label="Input Video", format="mp4")\n\n                with gr.Row():\n                    point_type = gr.Radio(\n                        label="point type",\n                        choices=["include", "exclude"],\n                        value="include",\n                        scale=2,\n                    )\n                    propagate_btn = gr.Button("Track", scale=1, variant="primary")\n                    clear_points_btn = gr.Button("Clear Points", scale=1)\n                    reset_btn = gr.Button("Reset", scale=1)\n\n                points_map = gr.Image(\n                    label="Frame with Point Prompt", type="numpy", interactive=False\n                )\n\n            with gr.Column():\n                gr.Markdown("# Try some of the examples below ⬇️")\n                gr.Examples(\n                    examples=examples,\n                    inputs=[\n                        video_in,\n                    ],\n                    examples_per_page=8,\n                )\n                gr.Markdown("\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n")\n                gr.Markdown("\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n")\n                gr.Markdown("\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n\\n")\n                output_image = gr.Image(label="Reference Mask")\n\n                output_video = gr.Video(visible=False)\n\n    # When new video is uploaded\n    video_in.upload(\n        fn=preprocess_video_in,\n        inputs=[\n            video_in,\n            session_state,\n        ],\n        outputs=[\n            video_in_drawer,  # Accordion to hide uploaded video player\n            points_map,  # Image component where we add new tracking points\n            output_image,\n            output_video,\n            session_state,\n        ],\n        queue=False,\n    )\n\n    video_in.change(\n        fn=preprocess_video_in,\n        inputs=[\n            video_in,\n            session_state,\n        ],\n        outputs=[\n            video_in_drawer,  # Accordion to hide uploaded video player\n            points_map,  # Image component where we add new tracking points\n            output_image,\n            output_video,\n            session_state,\n        ],\n        queue=False,\n    )\n\n    # triggered when we click on image to add new points\n    points_map.select(\n        fn=segment_with_points,\n        inputs=[\n            point_type,  # "include" or "exclude"\n            session_state,\n        ],\n        outputs=[\n            points_map,  # updated image with points\n            output_image,\n            session_state,\n        ],\n        queue=False,\n    )\n\n    # Clear every points clicked and added to the map\n    clear_points_btn.click(\n        fn=clear_points,\n        inputs=session_state,\n        outputs=[\n            points_map,\n            output_image,\n            output_video,\n            session_state,\n        ],\n        queue=False,\n    )\n\n    reset_btn.click(\n        fn=reset,\n        inputs=session_state,\n        outputs=[\n            video_in,\n            video_in_drawer,\n            points_map,\n            output_image,\n            output_video,\n            session_state,\n        ],\n        queue=False,\n    )\n\n    propagate_btn.click(\n        fn=update_ui,\n        inputs=[],\n        outputs=output_video,\n        queue=False,\n    ).then(\n        fn=propagate_to_all,\n        inputs=[\n            video_in,\n            session_state,\n        ],\n        outputs=[\n            output_video,\n            session_state,\n        ],\n        concurrency_limit=10,\n        queue=False,\n    )\n\ndemo.queue()\ndemo.launch()\n', '_shared_test_resources/code/EdgeTAM/setup.py': '# Copyright (c) Meta Platforms, Inc. and affiliates.\n# All rights reserved.\n\n# This source code is licensed under the license found in the\n# LICENSE file in the root directory of this source tree.\nimport os\n\nfrom setuptools import find_packages, setup\n\n# Package metadata\nNAME = "EdgeTAM"\nVERSION = "1.0"\nDESCRIPTION = "EdgeTAM: On-Device Track Anything Model"\nURL = "https://github.com/facebookresearch/EdgeTAM"\nAUTHOR = "Meta AI"\nAUTHOR_EMAIL = "chongzhou1024@gmail.com"\nLICENSE = "Apache 2.0"\n\n# Read the contents of README file\nwith open("README.md", "r", encoding="utf-8") as f:\n    LONG_DESCRIPTION = f.read()\n\n# Required dependencies\nREQUIRED_PACKAGES = [\n    "torch>=2.3.1",\n    "torchvision>=0.18.1",\n    "numpy>=1.24.4",\n    "tqdm>=4.66.1",\n    "hydra-core>=1.3.2",\n    "iopath>=0.1.10",\n    "pillow>=9.4.0",\n]\n\nEXTRA_PACKAGES = {\n    "notebooks": [\n        "matplotlib>=3.9.1",\n        "jupyter>=1.0.0",\n        "opencv-python>=4.7.0",\n        "eva-decord>=0.6.1",\n    ],\n    "dev": [\n        "black==24.2.0",\n        "usort==1.0.2",\n        "ufmt==2.0.0b2",\n        "fvcore>=0.1.5.post20221221",\n        "pandas>=2.2.2",\n        "scikit-image>=0.24.0",\n        "tensorboard>=2.17.0",\n        "pycocotools>=2.0.8",\n        "tensordict>=0.5.0",\n        "opencv-python>=4.7.0",\n        "submitit>=1.5.1",\n    ],\n    "gradio": [\n        "gradio==4.44.0",\n        "gradio_client==1.3.0",\n        "gradio_image_prompter==0.1.0",\n        "opencv-python==4.10.0.84",\n        "moviepy==1.0.3",\n        "pydantic==2.10.6",\n        "timm==1.0.15",\n        "eva-decord==0.6.1",\n    ],\n    "coreml": [\n        "coremltools>=8.0.0",\n        "pillow>=9.4.0",\n        "timm==1.0.15",  # Required for EdgeTAM model with RepViT backbone\n    ],\n}\n\n# By default, we also build the SAM 2 CUDA extension.\n# You may turn off CUDA build with `export SAM2_BUILD_CUDA=0`.\nBUILD_CUDA = os.getenv("SAM2_BUILD_CUDA", "1") == "1"\n# By default, we allow SAM 2 installation to proceed even with build errors.\n# You may force stopping on errors with `export SAM2_BUILD_ALLOW_ERRORS=0`.\nBUILD_ALLOW_ERRORS = os.getenv("SAM2_BUILD_ALLOW_ERRORS", "1") == "1"\n\n# Catch and skip errors during extension building and print a warning message\n# (note that this message only shows up under verbose build mode\n# "pip install -v -e ." or "python setup.py build_ext -v")\nCUDA_ERROR_MSG = (\n    "{}\\n\\n"\n    "Failed to build the SAM 2 CUDA extension due to the error above. "\n    "You can still use SAM 2 and it\'s OK to ignore the error above, although some "\n    "post-processing functionality may be limited (which doesn\'t affect the results in most cases; "\n    "(see https://github.com/facebookresearch/sam2/blob/main/INSTALL.md).\\n"\n)\n\n\ndef get_extensions():\n    if not BUILD_CUDA:\n        return []\n\n    try:\n        from torch.utils.cpp_extension import CUDAExtension\n\n        srcs = ["sam2/csrc/connected_components.cu"]\n        compile_args = {\n            "cxx": [],\n            "nvcc": [\n                "-DCUDA_HAS_FP16=1",\n                "-D__CUDA_NO_HALF_OPERATORS__",\n                "-D__CUDA_NO_HALF_CONVERSIONS__",\n                "-D__CUDA_NO_HALF2_OPERATORS__",\n            ],\n        }\n        ext_modules = [CUDAExtension("sam2._C", srcs, extra_compile_args=compile_args)]\n    except Exception as e:\n        if BUILD_ALLOW_ERRORS:\n            print(CUDA_ERROR_MSG.format(e))\n            ext_modules = []\n        else:\n            raise e\n\n    return ext_modules\n\n\ntry:\n    from torch.utils.cpp_extension import BuildExtension\n\n    class BuildExtensionIgnoreErrors(BuildExtension):\n\n        def finalize_options(self):\n            try:\n                super().finalize_options()\n            except Exception as e:\n                print(CUDA_ERROR_MSG.format(e))\n                self.extensions = []\n\n        def build_extensions(self):\n            try:\n                super().build_extensions()\n            except Exception as e:\n                print(CUDA_ERROR_MSG.format(e))\n                self.extensions = []\n\n        def get_ext_filename(self, ext_name):\n            try:\n                return super().get_ext_filename(ext_name)\n            except Exception as e:\n                print(CUDA_ERROR_MSG.format(e))\n                self.extensions = []\n                return "_C.so"\n\n    cmdclass = {\n        "build_ext": (\n            BuildExtensionIgnoreErrors.with_options(no_python_abi_suffix=True)\n            if BUILD_ALLOW_ERRORS\n            else BuildExtension.with_options(no_python_abi_suffix=True)\n        )\n    }\nexcept Exception as e:\n    cmdclass = {}\n    if BUILD_ALLOW_ERRORS:\n        print(CUDA_ERROR_MSG.format(e))\n    else:\n        raise e\n\n\n# Setup configuration\nsetup(\n    name=NAME,\n    version=VERSION,\n    description=DESCRIPTION,\n    long_description=LONG_DESCRIPTION,\n    long_description_content_type="text/markdown",\n    url=URL,\n    author=AUTHOR,\n    author_email=AUTHOR_EMAIL,\n    license=LICENSE,\n    packages=find_packages(exclude="notebooks"),\n    include_package_data=True,\n    install_requires=REQUIRED_PACKAGES,\n    extras_require=EXTRA_PACKAGES,\n    python_requires=">=3.10.0",\n    ext_modules=get_extensions(),\n    cmdclass=cmdclass,\n)\n', '_shared_test_resources/code/EdgeTAM/convert_weights.py': '# Copyright (c) Meta Platforms, Inc. and affiliates.\n# All rights reserved.\n\n# This source code is licensed under the license found in the\n# LICENSE file in the root directory of this source tree.\n\nimport argparse\n\nimport torch\n\n\ndef main(args):\n    sd = torch.load(args.src, map_location="cpu")["model"]\n    sd = {k: v for k, v in sd.items() if "teacher" not in k}\n    sd = {\n        k.replace("backbone.vision_backbone", "image_encoder"): v for k, v in sd.items()\n    }\n    sd = {k.replace("mlp.fc1", "mlp.layers.0"): v for k, v in sd.items()}\n    sd = {k.replace("mlp.fc2", "mlp.layers.1"): v for k, v in sd.items()}\n    sd = {k.replace("convs", "neck.convs"): v for k, v in sd.items()}\n    sd = {\n        k.replace("transformer.encoder", "memory_attention"): v for k, v in sd.items()\n    }\n    sd = {k.replace("maskmem_backbone", "memory_encoder"): v for k, v in sd.items()}\n    sd = {k.replace("maskmem_backbone", "memory_encoder"): v for k, v in sd.items()}\n    sd = {k.replace("mlp.lin1", "mlp.layers.0"): v for k, v in sd.items()}\n    sd = {k.replace("mlp.lin2", "mlp.layers.1"): v for k, v in sd.items()}\n    torch.save({"model": sd}, args.src.replace(".pt", "_converted.pt"))\n\n\nif __name__ == "__main__":\n    parser = argparse.ArgumentParser()\n    parser.add_argument("--src", type=str, required=True)\n    args = parser.parse_args()\n\n    main(args)\n', '_shared_test_resources/code/EdgeTAM/sam2/sam2_image_predictor.py': '# Copyright (c) Meta Platforms, Inc. and affiliates.\n# All rights reserved.\n\n# This source code is licensed under the license found in the\n# LICENSE file in the root directory of this source tree.\n\nimport logging\n\nfrom typing import List, Optional, Tuple, Union\n\nimport numpy as np\nimport torch\nfrom PIL.Image import Image\n\nfrom sam2.modeling.sam2_base import SAM2Base\n\nfrom sam2.utils.transforms import SAM2Transforms\n\n\nclass SAM2ImagePredictor:\n    def __init__(\n        self,\n        sam_model: SAM2Base,\n        mask_threshold=0.0,\n        max_hole_area=0.0,\n        max_sprinkle_area=0.0,\n        **kwargs,\n    ) -> None:\n        """\n        Uses SAM-2 to calculate the image embedding for an image, and then\n        allow repeated, efficient mask prediction given prompts.\n\n        Arguments:\n          sam_model (Sam-2): The model to use for mask prediction.\n          mask_threshold (float): The threshold to use when converting mask logits\n            to binary masks. Masks are thresholded at 0 by default.\n          max_hole_area (int): If max_hole_area > 0, we fill small holes in up to\n            the maximum area of max_hole_area in low_res_masks.\n          max_sprinkle_area (int): If max_sprinkle_area > 0, we remove small sprinkles up to\n            the maximum area of max_sprinkle_area in low_res_masks.\n        """\n        super().__init__()\n        self.model = sam_model\n        self._transforms = SAM2Transforms(\n            resolution=self.model.image_size,\n            mask_threshold=mask_threshold,\n            max_hole_area=max_hole_area,\n            max_sprinkle_area=max_sprinkle_area,\n        )\n\n        # Predictor state\n        self._is_image_set = False\n        self._features = None\n        self._orig_hw = None\n        # Whether the predictor is set for single image or a batch of images\n        self._is_batch = False\n\n        # Predictor config\n        self.mask_threshold = mask_threshold\n\n        # Spatial dim for backbone feature maps\n        self._bb_feat_sizes = [\n            (256, 256),\n            (128, 128),\n            (64, 64),\n        ]\n\n    @classmethod\n    def from_pretrained(cls, model_id: str, **kwargs) -> "SAM2ImagePredictor":\n        """\n        Load a pretrained model from the Hugging Face hub.\n\n        Arguments:\n          model_id (str): The Hugging Face repository ID.\n          **kwargs: Additional arguments to pass to the model constructor.\n\n        Returns:\n          (SAM2ImagePredictor): The loaded model.\n        """\n        from sam2.build_sam import build_sam2_hf\n\n        sam_model = build_sam2_hf(model_id, **kwargs)\n        return cls(sam_model, **kwargs)\n\n    @torch.no_grad()\n    def set_image(\n        self,\n        image: Union[np.ndarray, Image],\n    ) -> None:\n        """\n        Calculates the image embeddings for the provided image, allowing\n        masks to be predicted with the \'predict\' method.\n\n        Arguments:\n          image (np.ndarray or PIL Image): The input image to embed in RGB format. The image should be in HWC format if np.ndarray, or WHC format if PIL Image\n          with pixel values in [0, 255].\n          image_format (str): The color format of the image, in [\'RGB\', \'BGR\'].\n        """\n        self.reset_predictor()\n        # Transform the image to the form expected by the model\n        if isinstance(image, np.ndarray):\n            logging.info("For numpy array image, we assume (HxWxC) format")\n            self._orig_hw = [image.shape[:2]]\n        elif isinstance(image, Image):\n            w, h = image.size\n            self._orig_hw = [(h, w)]\n        else:\n            raise NotImplementedError("Image format not supported")\n\n        input_image = self._transforms(image)\n        input_image = input_image[None, ...].to(self.device)\n\n        assert (\n            len(input_image.shape) == 4 and input_image.shape[1] == 3\n        ), f"input_image must be of size 1x3xHxW, got {input_image.shape}"\n        logging.info("Computing image embeddings for the provided image...")\n        backbone_out = self.model.forward_image(input_image)\n        _, vision_feats, _, _ = self.model._prepare_backbone_features(backbone_out)\n        # Add no_mem_embed, which is added to the lowest rest feat. map during training on videos\n        if self.model.directly_add_no_mem_embed:\n            vision_feats[-1] = vision_feats[-1] + self.model.no_mem_embed\n\n        feats = [\n            feat.permute(1, 2, 0).view(1, -1, *feat_size)\n            for feat, feat_size in zip(vision_feats[::-1], self._bb_feat_sizes[::-1])\n        ][::-1]\n        self._features = {"image_embed": feats[-1], "high_res_feats": feats[:-1]}\n        self._is_image_set = True\n        logging.info("Image embeddings computed.")\n\n    @torch.no_grad()\n    def set_image_batch(\n        self,\n        image_list: List[Union[np.ndarray]],\n    ) -> None:\n        """\n        Calculates the image embeddings for the provided image batch, allowing\n        masks to be predicted with the \'predict_batch\' method.\n\n        Arguments:\n          image_list (List[np.ndarray]): The input images to embed in RGB format. The image should be in HWC format if np.ndarray\n          with pixel values in [0, 255].\n        """\n        self.reset_predictor()\n        assert isinstance(image_list, list)\n        self._orig_hw = []\n        for image in image_list:\n            assert isinstance(\n                image, np.ndarray\n            ), "Images are expected to be an np.ndarray in RGB format, and of shape  HWC"\n            self._orig_hw.append(image.shape[:2])\n        # Transform the image to the form expected by the model\n        img_batch = self._transforms.forward_batch(image_list)\n        img_batch = img_batch.to(self.device)\n        batch_size = img_batch.shape[0]\n        assert (\n            len(img_batch.shape) == 4 and img_batch.shape[1] == 3\n        ), f"img_batch must be of size Bx3xHxW, got {img_batch.shape}"\n        logging.info("Computing image embeddings for the provided images...")\n        backbone_out = self.model.forward_image(img_batch)\n        _, vision_feats, _, _ = self.model._prepare_backbone_features(backbone_out)\n        # Add no_mem_embed, which is added to the lowest rest feat. map during training on videos\n        if self.model.directly_add_no_mem_embed:\n            vision_feats[-1] = vision_feats[-1] + self.model.no_mem_embed\n\n        feats = [\n            feat.permute(1, 2, 0).view(batch_size, -1, *feat_size)\n            for feat, feat_size in zip(vision_feats[::-1], self._bb_feat_sizes[::-1])\n        ][::-1]\n        self._features = {"image_embed": feats[-1], "high_res_feats": feats[:-1]}\n        self._is_image_set = True\n        self._is_batch = True\n        logging.info("Image embeddings computed.")\n\n    def predict_batch(\n        self,\n        point_coords_batch: List[np.ndarray] = None,\n        point_labels_batch: List[np.ndarray] = None,\n        box_batch: List[np.ndarray] = None,\n        mask_input_batch: List[np.ndarray] = None,\n        multimask_output: bool = True,\n        return_logits: bool = False,\n        normalize_coords=True,\n    ) -> Tuple[List[np.ndarray], List[np.ndarray], List[np.ndarray]]:\n        """This function is very similar to predict(...), however it is used for batched mode, when the model is expected to generate predictions on multiple images.\n        It returns a tuple of lists of masks, ious, and low_res_masks_logits.\n        """\n        assert self._is_batch, "This function should only be used when in batched mode"\n        if not self._is_image_set:\n            raise RuntimeError(\n                "An image must be set with .set_image_batch(...) before mask prediction."\n            )\n        num_images = len(self._features["image_embed"])\n        all_masks = []\n        all_ious = []\n        all_low_res_masks = []\n        for img_idx in range(num_images):\n            # Transform input prompts\n            point_coords = (\n                point_coords_batch[img_idx] if point_coords_batch is not None else None\n            )\n            point_labels = (\n                point_labels_batch[img_idx] if point_labels_batch is not None else None\n            )\n            box = box_batch[img_idx] if box_batch is not None else None\n            mask_input = (\n                mask_input_batch[img_idx] if mask_input_batch is not None else None\n            )\n            mask_input, unnorm_coords, labels, unnorm_box = self._prep_prompts(\n                point_coords,\n                point_labels,\n                box,\n                mask_input,\n                normalize_coords,\n                img_idx=img_idx,\n            )\n            masks, iou_predictions, low_res_masks = self._predict(\n                unnorm_coords,\n                labels,\n                unnorm_box,\n                mask_input,\n                multimask_output,\n                return_logits=return_logits,\n                img_idx=img_idx,\n            )\n            masks_np = masks.squeeze(0).float().detach().cpu().numpy()\n            iou_predictions_np = (\n                iou_predictions.squeeze(0).float().detach().cpu().numpy()\n            )\n            low_res_masks_np = low_res_masks.squeeze(0).float().detach().cpu().numpy()\n            all_masks.append(masks_np)\n            all_ious.append(iou_predictions_np)\n            all_low_res_masks.append(low_res_masks_np)\n\n        return all_masks, all_ious, all_low_res_masks\n\n    def predict(\n        self,\n        point_coords: Optional[np.ndarray] = None,\n        point_labels: Optional[np.ndarray] = None,\n        box: Optional[np.ndarray] = None,\n        mask_input: Optional[np.ndarray] = None,\n        multimask_output: bool = True,\n        return_logits: bool = False,\n        normalize_coords=True,\n    ) -> Tuple[np.ndarray, np.ndarray, np.ndarray]:\n        """\n        Predict masks for the given input prompts, using the currently set image.\n\n        Arguments:\n          point_coords (np.ndarray or None): A Nx2 array of point prompts to the\n            model. Each point is in (X,Y) in pixels.\n          point_labels (np.ndarray or None): A length N array of labels for the\n            point prompts. 1 indicates a foreground point and 0 indicates a\n            background point.\n          box (np.ndarray or None): A length 4 array given a box prompt to the\n            model, in XYXY format.\n          mask_input (np.ndarray): A low resolution mask input to the model, typically\n            coming from a previous prediction iteration. Has form 1xHxW, where\n            for SAM, H=W=256.\n          multimask_output (bool): If true, the model will return three masks.\n            For ambiguous input prompts (such as a single click), this will often\n            produce better masks than a single prediction. If only a single\n            mask is needed, the model\'s predicted quality score can be used\n            to select the best mask. For non-ambiguous prompts, such as multiple\n            input prompts, multimask_output=False can give better results.\n          return_logits (bool): If true, returns un-thresholded masks logits\n            instead of a binary mask.\n          normalize_coords (bool): If true, the point coordinates will be normalized to the range [0,1] and point_coords is expected to be wrt. image dimensions.\n\n        Returns:\n          (np.ndarray): The output masks in CxHxW format, where C is the\n            number of masks, and (H, W) is the original image size.\n          (np.ndarray): An array of length C containing the model\'s\n            predictions for the quality of each mask.\n          (np.ndarray): An array of shape CxHxW, where C is the number\n            of masks and H=W=256. These low resolution logits can be passed to\n            a subsequent iteration as mask input.\n        """\n        if not self._is_image_set:\n            raise RuntimeError(\n                "An image must be set with .set_image(...) before mask prediction."\n            )\n\n        # Transform input prompts\n\n        mask_input, unnorm_coords, labels, unnorm_box = self._prep_prompts(\n            point_coords, point_labels, box, mask_input, normalize_coords\n        )\n\n        masks, iou_predictions, low_res_masks = self._predict(\n            unnorm_coords,\n            labels,\n            unnorm_box,\n            mask_input,\n            multimask_output,\n            return_logits=return_logits,\n        )\n\n        masks_np = masks.squeeze(0).float().detach().cpu().numpy()\n        iou_predictions_np = iou_predictions.squeeze(0).float().detach().cpu().numpy()\n        low_res_masks_np = low_res_masks.squeeze(0).float().detach().cpu().numpy()\n        return masks_np, iou_predictions_np, low_res_masks_np\n\n    def _prep_prompts(\n        self, point_coords, point_labels, box, mask_logits, normalize_coords, img_idx=-1\n    ):\n\n        unnorm_coords, labels, unnorm_box, mask_input = None, None, None, None\n        if point_coords is not None:\n            assert (\n                point_labels is not None\n            ), "point_labels must be supplied if point_coords is supplied."\n            point_coords = torch.as_tensor(\n                point_coords, dtype=torch.float, device=self.device\n            )\n            unnorm_coords = self._transforms.transform_coords(\n                point_coords, normalize=normalize_coords, orig_hw=self._orig_hw[img_idx]\n            )\n            labels = torch.as_tensor(point_labels, dtype=torch.int, device=self.device)\n            if len(unnorm_coords.shape) == 2:\n                unnorm_coords, labels = unnorm_coords[None, ...], labels[None, ...]\n        if box is not None:\n            box = torch.as_tensor(box, dtype=torch.float, device=self.device)\n            unnorm_box = self._transforms.transform_boxes(\n                box, normalize=normalize_coords, orig_hw=self._orig_hw[img_idx]\n            )  # Bx2x2\n        if mask_logits is not None:\n            mask_input = torch.as_tensor(\n                mask_logits, dtype=torch.float, device=self.device\n            )\n            if len(mask_input.shape) == 3:\n                mask_input = mask_input[None, :, :, :]\n        return mask_input, unnorm_coords, labels, unnorm_box\n\n    @torch.no_grad()\n    def _predict(\n        self,\n        point_coords: Optional[torch.Tensor],\n        point_labels: Optional[torch.Tensor],\n        boxes: Optional[torch.Tensor] = None,\n        mask_input: Optional[torch.Tensor] = None,\n        multimask_output: bool = True,\n        return_logits: bool = False,\n        img_idx: int = -1,\n    ) -> Tuple[torch.Tensor, torch.Tensor, torch.Tensor]:\n        """\n        Predict masks for the given input prompts, using the currently set image.\n        Input prompts are batched torch tensors and are expected to already be\n        transformed to the input frame using SAM2Transforms.\n\n        Arguments:\n          point_coords (torch.Tensor or None): A BxNx2 array of point prompts to the\n            model. Each point is in (X,Y) in pixels.\n          point_labels (torch.Tensor or None): A BxN array of labels for the\n            point prompts. 1 indicates a foreground point and 0 indicates a\n            background point.\n          boxes (np.ndarray or None): A Bx4 array given a box prompt to the\n            model, in XYXY format.\n          mask_input (np.ndarray): A low resolution mask input to the model, typically\n            coming from a previous prediction iteration. Has form Bx1xHxW, where\n            for SAM, H=W=256. Masks returned by a previous iteration of the\n            predict method do not need further transformation.\n          multimask_output (bool): If true, the model will return three masks.\n            For ambiguous input prompts (such as a single click), this will often\n            produce better masks than a single prediction. If only a single\n            mask is needed, the model\'s predicted quality score can be used\n            to select the best mask. For non-ambiguous prompts, such as multiple\n            input prompts, multimask_output=False can give better results.\n          return_logits (bool): If true, returns un-thresholded masks logits\n            instead of a binary mask.\n\n        Returns:\n          (torch.Tensor): The output masks in BxCxHxW format, where C is the\n            number of masks, and (H, W) is the original image size.\n          (torch.Tensor): An array of shape BxC containing the model\'s\n            predictions for the quality of each mask.\n          (torch.Tensor): An array of shape BxCxHxW, where C is the number\n            of masks and H=W=256. These low res logits can be passed to\n            a subsequent iteration as mask input.\n        """\n        if not self._is_image_set:\n            raise RuntimeError(\n                "An image must be set with .set_image(...) before mask prediction."\n            )\n\n        if point_coords is not None:\n            concat_points = (point_coords, point_labels)\n        else:\n            concat_points = None\n\n        # Embed prompts\n        if boxes is not None:\n            box_coords = boxes.reshape(-1, 2, 2)\n            box_labels = torch.tensor([[2, 3]], dtype=torch.int, device=boxes.device)\n            box_labels = box_labels.repeat(boxes.size(0), 1)\n            # we merge "boxes" and "points" into a single "concat_points" input (where\n            # boxes are added at the beginning) to sam_prompt_encoder\n            if concat_points is not None:\n                concat_coords = torch.cat([box_coords, concat_points[0]], dim=1)\n                concat_labels = torch.cat([box_labels, concat_points[1]], dim=1)\n                concat_points = (concat_coords, concat_labels)\n            else:\n                concat_points = (box_coords, box_labels)\n\n        sparse_embeddings, dense_embeddings = self.model.sam_prompt_encoder(\n            points=concat_points,\n            boxes=None,\n            masks=mask_input,\n        )\n\n        # Predict masks\n        batched_mode = (\n            concat_points is not None and concat_points[0].shape[0] > 1\n        )  # multi object prediction\n        high_res_features = [\n            feat_level[img_idx].unsqueeze(0)\n            for feat_level in self._features["high_res_feats"]\n        ]\n        low_res_masks, iou_predictions, _, _ = self.model.sam_mask_decoder(\n            image_embeddings=self._features["image_embed"][img_idx].unsqueeze(0),\n            image_pe=self.model.sam_prompt_encoder.get_dense_pe(),\n            sparse_prompt_embeddings=sparse_embeddings,\n            dense_prompt_embeddings=dense_embeddings,\n            multimask_output=multimask_output,\n            repeat_image=batched_mode,\n            high_res_features=high_res_features,\n        )\n\n        # Upscale the masks to the original image resolution\n        masks = self._transforms.postprocess_masks(\n            low_res_masks, self._orig_hw[img_idx]\n        )\n        low_res_masks = torch.clamp(low_res_masks, -32.0, 32.0)\n        if not return_logits:\n            masks = masks > self.mask_threshold\n\n        return masks, iou_predictions, low_res_masks\n\n    def get_image_embedding(self) -> torch.Tensor:\n        """\n        Returns the image embeddings for the currently set image, with\n        shape 1xCxHxW, where C is the embedding dimension and (H,W) are\n        the embedding spatial dimension of SAM (typically C=256, H=W=64).\n        """\n        if not self._is_image_set:\n            raise RuntimeError(\n                "An image must be set with .set_image(...) to generate an embedding."\n            )\n        assert (\n            self._features is not None\n        ), "Features must exist if an image has been set."\n        return self._features["image_embed"]\n\n    @property\n    def device(self) -> torch.device:\n        return self.model.device\n\n    def reset_predictor(self) -> None:\n        """\n        Resets the image embeddings and other state variables.\n        """\n        self._is_image_set = False\n        self._features = None\n        self._orig_hw = None\n        self._is_batch = False\n', '_shared_test_resources/code/EdgeTAM/sam2/automatic_mask_generator.py': '# Copyright (c) Meta Platforms, Inc. and affiliates.\n# All rights reserved.\n\n# This source code is licensed under the license found in the\n# LICENSE file in the root directory of this source tree.\n\n# Adapted from https://github.com/facebookresearch/segment-anything/blob/main/segment_anything/automatic_mask_generator.py\nfrom typing import Any, Dict, List, Optional, Tuple\n\nimport numpy as np\nimport torch\nfrom torchvision.ops.boxes import batched_nms, box_area  # type: ignore\n\nfrom sam2.modeling.sam2_base import SAM2Base\nfrom sam2.sam2_image_predictor import SAM2ImagePredictor\nfrom sam2.utils.amg import (\n    area_from_rle,\n    batch_iterator,\n    batched_mask_to_box,\n    box_xyxy_to_xywh,\n    build_all_layer_point_grids,\n    calculate_stability_score,\n    coco_encode_rle,\n    generate_crop_boxes,\n    is_box_near_crop_edge,\n    mask_to_rle_pytorch,\n    MaskData,\n    remove_small_regions,\n    rle_to_mask,\n    uncrop_boxes_xyxy,\n    uncrop_masks,\n    uncrop_points,\n)\n\n\nclass SAM2AutomaticMaskGenerator:\n    def __init__(\n        self,\n        model: SAM2Base,\n        points_per_side: Optional[int] = 32,\n        points_per_batch: int = 64,\n        pred_iou_thresh: float = 0.8,\n        stability_score_thresh: float = 0.95,\n        stability_score_offset: float = 1.0,\n        mask_threshold: float = 0.0,\n        box_nms_thresh: float = 0.7,\n        crop_n_layers: int = 0,\n        crop_nms_thresh: float = 0.7,\n        crop_overlap_ratio: float = 512 / 1500,\n        crop_n_points_downscale_factor: int = 1,\n        point_grids: Optional[List[np.ndarray]] = None,\n        min_mask_region_area: int = 0,\n        output_mode: str = "binary_mask",\n        use_m2m: bool = False,\n        multimask_output: bool = True,\n        **kwargs,\n    ) -> None:\n        """\n        Using a SAM 2 model, generates masks for the entire image.\n        Generates a grid of point prompts over the image, then filters\n        low quality and duplicate masks. The default settings are chosen\n        for SAM 2 with a HieraL backbone.\n\n        Arguments:\n          model (Sam): The SAM 2 model to use for mask prediction.\n          points_per_side (int or None): The number of points to be sampled\n            along one side of the image. The total number of points is\n            points_per_side**2. If None, \'point_grids\' must provide explicit\n            point sampling.\n          points_per_batch (int): Sets the number of points run simultaneously\n            by the model. Higher numbers may be faster but use more GPU memory.\n          pred_iou_thresh (float): A filtering threshold in [0,1], using the\n            model\'s predicted mask quality.\n          stability_score_thresh (float): A filtering threshold in [0,1], using\n            the stability of the mask under changes to the cutoff used to binarize\n            the model\'s mask predictions.\n          stability_score_offset (float): The amount to shift the cutoff when\n            calculated the stability score.\n          mask_threshold (float): Threshold for binarizing the mask logits\n          box_nms_thresh (float): The box IoU cutoff used by non-maximal\n            suppression to filter duplicate masks.\n          crop_n_layers (int): If >0, mask prediction will be run again on\n            crops of the image. Sets the number of layers to run, where each\n            layer has 2**i_layer number of image crops.\n          crop_nms_thresh (float): The box IoU cutoff used by non-maximal\n            suppression to filter duplicate masks between different crops.\n          crop_overlap_ratio (float): Sets the degree to which crops overlap.\n            In the first crop layer, crops will overlap by this fraction of\n            the image length. Later layers with more crops scale down this overlap.\n          crop_n_points_downscale_factor (int): The number of points-per-side\n            sampled in layer n is scaled down by crop_n_points_downscale_factor**n.\n          point_grids (list(np.ndarray) or None): A list over explicit grids\n            of points used for sampling, normalized to [0,1]. The nth grid in the\n            list is used in the nth crop layer. Exclusive with points_per_side.\n          min_mask_region_area (int): If >0, postprocessing will be applied\n            to remove disconnected regions and holes in masks with area smaller\n            than min_mask_region_area. Requires opencv.\n          output_mode (str): The form masks are returned in. Can be \'binary_mask\',\n            \'uncompressed_rle\', or \'coco_rle\'. \'coco_rle\' requires pycocotools.\n            For large resolutions, \'binary_mask\' may consume large amounts of\n            memory.\n          use_m2m (bool): Whether to add a one step refinement using previous mask predictions.\n          multimask_output (bool): Whether to output multimask at each point of the grid.\n        """\n\n        assert (points_per_side is None) != (\n            point_grids is None\n        ), "Exactly one of points_per_side or point_grid must be provided."\n        if points_per_side is not None:\n            self.point_grids = build_all_layer_point_grids(\n                points_per_side,\n                crop_n_layers,\n                crop_n_points_downscale_factor,\n            )\n        elif point_grids is not None:\n            self.point_grids = point_grids\n        else:\n            raise ValueError("Can\'t have both points_per_side and point_grid be None.")\n\n        assert output_mode in [\n            "binary_mask",\n            "uncompressed_rle",\n            "coco_rle",\n        ], f"Unknown output_mode {output_mode}."\n        if output_mode == "coco_rle":\n            try:\n                from pycocotools import mask as mask_utils  # type: ignore  # noqa: F401\n            except ImportError as e:\n                print("Please install pycocotools")\n                raise e\n\n        self.predictor = SAM2ImagePredictor(\n            model,\n            max_hole_area=min_mask_region_area,\n            max_sprinkle_area=min_mask_region_area,\n        )\n        self.points_per_batch = points_per_batch\n        self.pred_iou_thresh = pred_iou_thresh\n        self.stability_score_thresh = stability_score_thresh\n        self.stability_score_offset = stability_score_offset\n        self.mask_threshold = mask_threshold\n        self.box_nms_thresh = box_nms_thresh\n        self.crop_n_layers = crop_n_layers\n        self.crop_nms_thresh = crop_nms_thresh\n        self.crop_overlap_ratio = crop_overlap_ratio\n        self.crop_n_points_downscale_factor = crop_n_points_downscale_factor\n        self.min_mask_region_area = min_mask_region_area\n        self.output_mode = output_mode\n        self.use_m2m = use_m2m\n        self.multimask_output = multimask_output\n\n    @classmethod\n    def from_pretrained(cls, model_id: str, **kwargs) -> "SAM2AutomaticMaskGenerator":\n        """\n        Load a pretrained model from the Hugging Face hub.\n\n        Arguments:\n          model_id (str): The Hugging Face repository ID.\n          **kwargs: Additional arguments to pass to the model constructor.\n\n        Returns:\n          (SAM2AutomaticMaskGenerator): The loaded model.\n        """\n        from sam2.build_sam import build_sam2_hf\n\n        sam_model = build_sam2_hf(model_id, **kwargs)\n        return cls(sam_model, **kwargs)\n\n    @torch.no_grad()\n    def generate(self, image: np.ndarray) -> List[Dict[str, Any]]:\n        """\n        Generates masks for the given image.\n\n        Arguments:\n          image (np.ndarray): The image to generate masks for, in HWC uint8 format.\n\n        Returns:\n           list(dict(str, any)): A list over records for masks. Each record is\n             a dict containing the following keys:\n               segmentation (dict(str, any) or np.ndarray): The mask. If\n                 output_mode=\'binary_mask\', is an array of shape HW. Otherwise,\n                 is a dictionary containing the RLE.\n               bbox (list(float)): The box around the mask, in XYWH format.\n               area (int): The area in pixels of the mask.\n               predicted_iou (float): The model\'s own prediction of the mask\'s\n                 quality. This is filtered by the pred_iou_thresh parameter.\n               point_coords (list(list(float))): The point coordinates input\n                 to the model to generate this mask.\n               stability_score (float): A measure of the mask\'s quality. This\n                 is filtered on using the stability_score_thresh parameter.\n               crop_box (list(float)): The crop of the image used to generate\n                 the mask, given in XYWH format.\n        """\n\n        # Generate masks\n        mask_data = self._generate_masks(image)\n\n        # Encode masks\n        if self.output_mode == "coco_rle":\n            mask_data["segmentations"] = [\n                coco_encode_rle(rle) for rle in mask_data["rles"]\n            ]\n        elif self.output_mode == "binary_mask":\n            mask_data["segmentations"] = [rle_to_mask(rle) for rle in mask_data["rles"]]\n        else:\n            mask_data["segmentations"] = mask_data["rles"]\n\n        # Write mask records\n        curr_anns = []\n        for idx in range(len(mask_data["segmentations"])):\n            ann = {\n                "segmentation": mask_data["segmentations"][idx],\n                "area": area_from_rle(mask_data["rles"][idx]),\n                "bbox": box_xyxy_to_xywh(mask_data["boxes"][idx]).tolist(),\n                "predicted_iou": mask_data["iou_preds"][idx].item(),\n                "point_coords": [mask_data["points"][idx].tolist()],\n                "stability_score": mask_data["stability_score"][idx].item(),\n                "crop_box": box_xyxy_to_xywh(mask_data["crop_boxes"][idx]).tolist(),\n            }\n            curr_anns.append(ann)\n\n        return curr_anns\n\n    def _generate_masks(self, image: np.ndarray) -> MaskData:\n        orig_size = image.shape[:2]\n        crop_boxes, layer_idxs = generate_crop_boxes(\n            orig_size, self.crop_n_layers, self.crop_overlap_ratio\n        )\n\n        # Iterate over image crops\n        data = MaskData()\n        for crop_box, layer_idx in zip(crop_boxes, layer_idxs):\n            crop_data = self._process_crop(image, crop_box, layer_idx, orig_size)\n            data.cat(crop_data)\n\n        # Remove duplicate masks between crops\n        if len(crop_boxes) > 1:\n            # Prefer masks from smaller crops\n            scores = 1 / box_area(data["crop_boxes"])\n            scores = scores.to(data["boxes"].device)\n            keep_by_nms = batched_nms(\n                data["boxes"].float(),\n                scores,\n                torch.zeros_like(data["boxes"][:, 0]),  # categories\n                iou_threshold=self.crop_nms_thresh,\n            )\n            data.filter(keep_by_nms)\n        data.to_numpy()\n        return data\n\n    def _process_crop(\n        self,\n        image: np.ndarray,\n        crop_box: List[int],\n        crop_layer_idx: int,\n        orig_size: Tuple[int, ...],\n    ) -> MaskData:\n        # Crop the image and calculate embeddings\n        x0, y0, x1, y1 = crop_box\n        cropped_im = image[y0:y1, x0:x1, :]\n        cropped_im_size = cropped_im.shape[:2]\n        self.predictor.set_image(cropped_im)\n\n        # Get points for this crop\n        points_scale = np.array(cropped_im_size)[None, ::-1]\n        points_for_image = self.point_grids[crop_layer_idx] * points_scale\n\n        # Generate masks for this crop in batches\n        data = MaskData()\n        for (points,) in batch_iterator(self.points_per_batch, points_for_image):\n            batch_data = self._process_batch(\n                points, cropped_im_size, crop_box, orig_size, normalize=True\n            )\n            data.cat(batch_data)\n            del batch_data\n        self.predictor.reset_predictor()\n\n        # Remove duplicates within this crop.\n        keep_by_nms = batched_nms(\n            data["boxes"].float(),\n            data["iou_preds"],\n            torch.zeros_like(data["boxes"][:, 0]),  # categories\n            iou_threshold=self.box_nms_thresh,\n        )\n        data.filter(keep_by_nms)\n\n        # Return to the original image frame\n        data["boxes"] = uncrop_boxes_xyxy(data["boxes"], crop_box)\n        data["points"] = uncrop_points(data["points"], crop_box)\n        data["crop_boxes"] = torch.tensor([crop_box for _ in range(len(data["rles"]))])\n\n        return data\n\n    def _process_batch(\n        self,\n        points: np.ndarray,\n        im_size: Tuple[int, ...],\n        crop_box: List[int],\n        orig_size: Tuple[int, ...],\n        normalize=False,\n    ) -> MaskData:\n        orig_h, orig_w = orig_size\n\n        # Run model on this batch\n        points = torch.as_tensor(\n            points, dtype=torch.float32, device=self.predictor.device\n        )\n        in_points = self.predictor._transforms.transform_coords(\n            points, normalize=normalize, orig_hw=im_size\n        )\n        in_labels = torch.ones(\n            in_points.shape[0], dtype=torch.int, device=in_points.device\n        )\n        masks, iou_preds, low_res_masks = self.predictor._predict(\n            in_points[:, None, :],\n            in_labels[:, None],\n            multimask_output=self.multimask_output,\n            return_logits=True,\n        )\n\n        # Serialize predictions and store in MaskData\n        data = MaskData(\n            masks=masks.flatten(0, 1),\n            iou_preds=iou_preds.flatten(0, 1),\n            points=points.repeat_interleave(masks.shape[1], dim=0),\n            low_res_masks=low_res_masks.flatten(0, 1),\n        )\n        del masks\n\n        if not self.use_m2m:\n            # Filter by predicted IoU\n            if self.pred_iou_thresh > 0.0:\n                keep_mask = data["iou_preds"] > self.pred_iou_thresh\n                data.filter(keep_mask)\n\n            # Calculate and filter by stability score\n            data["stability_score"] = calculate_stability_score(\n                data["masks"], self.mask_threshold, self.stability_score_offset\n            )\n            if self.stability_score_thresh > 0.0:\n                keep_mask = data["stability_score"] >= self.stability_score_thresh\n                data.filter(keep_mask)\n        else:\n            # One step refinement using previous mask predictions\n            in_points = self.predictor._transforms.transform_coords(\n                data["points"], normalize=normalize, orig_hw=im_size\n            )\n            labels = torch.ones(\n                in_points.shape[0], dtype=torch.int, device=in_points.device\n            )\n            masks, ious = self.refine_with_m2m(\n                in_points, labels, data["low_res_masks"], self.points_per_batch\n            )\n            data["masks"] = masks.squeeze(1)\n            data["iou_preds"] = ious.squeeze(1)\n\n            if self.pred_iou_thresh > 0.0:\n                keep_mask = data["iou_preds"] > self.pred_iou_thresh\n                data.filter(keep_mask)\n\n            data["stability_score"] = calculate_stability_score(\n                data["masks"], self.mask_threshold, self.stability_score_offset\n            )\n            if self.stability_score_thresh > 0.0:\n                keep_mask = data["stability_score"] >= self.stability_score_thresh\n                data.filter(keep_mask)\n\n        # Threshold masks and calculate boxes\n        data["masks"] = data["masks"] > self.mask_threshold\n        data["boxes"] = batched_mask_to_box(data["masks"])\n\n        # Filter boxes that touch crop boundaries\n        keep_mask = ~is_box_near_crop_edge(\n            data["boxes"], crop_box, [0, 0, orig_w, orig_h]\n        )\n        if not torch.all(keep_mask):\n            data.filter(keep_mask)\n\n        # Compress to RLE\n        data["masks"] = uncrop_masks(data["masks"], crop_box, orig_h, orig_w)\n        data["rles"] = mask_to_rle_pytorch(data["masks"])\n        del data["masks"]\n\n        return data\n\n    @staticmethod\n    def postprocess_small_regions(\n        mask_data: MaskData, min_area: int, nms_thresh: float\n    ) -> MaskData:\n        """\n        Removes small disconnected regions and holes in masks, then reruns\n        box NMS to remove any new duplicates.\n\n        Edits mask_data in place.\n\n        Requires open-cv as a dependency.\n        """\n        if len(mask_data["rles"]) == 0:\n            return mask_data\n\n        # Filter small disconnected regions and holes\n        new_masks = []\n        scores = []\n        for rle in mask_data["rles"]:\n            mask = rle_to_mask(rle)\n\n            mask, changed = remove_small_regions(mask, min_area, mode="holes")\n            unchanged = not changed\n            mask, changed = remove_small_regions(mask, min_area, mode="islands")\n            unchanged = unchanged and not changed\n\n            new_masks.append(torch.as_tensor(mask).unsqueeze(0))\n            # Give score=0 to changed masks and score=1 to unchanged masks\n            # so NMS will prefer ones that didn\'t need postprocessing\n            scores.append(float(unchanged))\n\n        # Recalculate boxes and remove any new duplicates\n        masks = torch.cat(new_masks, dim=0)\n        boxes = batched_mask_to_box(masks)\n        keep_by_nms = batched_nms(\n            boxes.float(),\n            torch.as_tensor(scores),\n            torch.zeros_like(boxes[:, 0]),  # categories\n            iou_threshold=nms_thresh,\n        )\n\n        # Only recalculate RLEs for masks that have changed\n        for i_mask in keep_by_nms:\n            if scores[i_mask] == 0.0:\n                mask_torch = masks[i_mask].unsqueeze(0)\n                mask_data["rles"][i_mask] = mask_to_rle_pytorch(mask_torch)[0]\n                mask_data["boxes"][i_mask] = boxes[i_mask]  # update res directly\n        mask_data.filter(keep_by_nms)\n\n        return mask_data\n\n    def refine_with_m2m(self, points, point_labels, low_res_masks, points_per_batch):\n        new_masks = []\n        new_iou_preds = []\n\n        for cur_points, cur_point_labels, low_res_mask in batch_iterator(\n            points_per_batch, points, point_labels, low_res_masks\n        ):\n            best_masks, best_iou_preds, _ = self.predictor._predict(\n                cur_points[:, None, :],\n                cur_point_labels[:, None],\n                mask_input=low_res_mask[:, None, :],\n                multimask_output=False,\n                return_logits=True,\n            )\n            new_masks.append(best_masks)\n            new_iou_preds.append(best_iou_preds)\n        masks = torch.cat(new_masks, dim=0)\n        return masks, torch.cat(new_iou_preds, dim=0)\n', '_shared_test_resources/code/EdgeTAM/sam2/sam2_video_predictor.py': '# Copyright (c) Meta Platforms, Inc. and affiliates.\n# All rights reserved.\n\n# This source code is licensed under the license found in the\n# LICENSE file in the root directory of this source tree.\n\nimport warnings\nfrom collections import OrderedDict\n\nimport torch\n\nfrom sam2.modeling.sam2_base import NO_OBJ_SCORE, SAM2Base\nfrom sam2.utils.misc import concat_points, fill_holes_in_mask_scores, load_video_frames\n\nfrom tqdm import tqdm\n\n\nclass SAM2VideoPredictor(SAM2Base):\n    """The predictor class to handle user interactions and manage inference states."""\n\n    def __init__(\n        self,\n        fill_hole_area=0,\n        # whether to apply non-overlapping constraints on the output object masks\n        non_overlap_masks=False,\n        # whether to clear non-conditioning memory of the surrounding frames (which may contain outdated information) after adding correction clicks;\n        # note that this would only apply to *single-object tracking* unless `clear_non_cond_mem_for_multi_obj` is also set to True)\n        clear_non_cond_mem_around_input=False,\n        # whether to also clear non-conditioning memory of the surrounding frames (only effective when `clear_non_cond_mem_around_input` is True).\n        clear_non_cond_mem_for_multi_obj=False,\n        # if `add_all_frames_to_correct_as_cond` is True, we also append to the conditioning frame list any frame that receives a later correction click\n        # if `add_all_frames_to_correct_as_cond` is False, we conditioning frame list to only use those initial conditioning frames\n        add_all_frames_to_correct_as_cond=False,\n        **kwargs,\n    ):\n        super().__init__(**kwargs)\n        self.fill_hole_area = fill_hole_area\n        self.non_overlap_masks = non_overlap_masks\n        self.clear_non_cond_mem_around_input = clear_non_cond_mem_around_input\n        self.clear_non_cond_mem_for_multi_obj = clear_non_cond_mem_for_multi_obj\n        self.add_all_frames_to_correct_as_cond = add_all_frames_to_correct_as_cond\n\n    @torch.inference_mode()\n    def init_state(\n        self,\n        video_path,\n        offload_video_to_cpu=False,\n        offload_state_to_cpu=False,\n        async_loading_frames=False,\n    ):\n        """Initialize an inference state."""\n        compute_device = self.device  # device of the model\n        images, video_height, video_width = load_video_frames(\n            video_path=video_path,\n            image_size=self.image_size,\n            offload_video_to_cpu=offload_video_to_cpu,\n            async_loading_frames=async_loading_frames,\n            compute_device=compute_device,\n        )\n        inference_state = {}\n        inference_state["images"] = images\n        inference_state["num_frames"] = len(images)\n        # whether to offload the video frames to CPU memory\n        # turning on this option saves the GPU memory with only a very small overhead\n        inference_state["offload_video_to_cpu"] = offload_video_to_cpu\n        # whether to offload the inference state to CPU memory\n        # turning on this option saves the GPU memory at the cost of a lower tracking fps\n        # (e.g. in a test case of 768x768 model, fps dropped from 27 to 24 when tracking one object\n        # and from 24 to 21 when tracking two objects)\n        inference_state["offload_state_to_cpu"] = offload_state_to_cpu\n        # the original video height and width, used for resizing final output scores\n        inference_state["video_height"] = video_height\n        inference_state["video_width"] = video_width\n        inference_state["device"] = compute_device\n        if offload_state_to_cpu:\n            inference_state["storage_device"] = torch.device("cpu")\n        else:\n            inference_state["storage_device"] = compute_device\n        # inputs on each frame\n        inference_state["point_inputs_per_obj"] = {}\n        inference_state["mask_inputs_per_obj"] = {}\n        # visual features on a small number of recently visited frames for quick interactions\n        inference_state["cached_features"] = {}\n        # values that don\'t change across frames (so we only need to hold one copy of them)\n        inference_state["constants"] = {}\n        # mapping between client-side object id and model-side object index\n        inference_state["obj_id_to_idx"] = OrderedDict()\n        inference_state["obj_idx_to_id"] = OrderedDict()\n        inference_state["obj_ids"] = []\n        # A storage to hold the model\'s tracking results and states on each frame\n        inference_state["output_dict"] = {\n            "cond_frame_outputs": {},  # dict containing {frame_idx: <out>}\n            "non_cond_frame_outputs": {},  # dict containing {frame_idx: <out>}\n        }\n        # Slice (view) of each object tracking results, sharing the same memory with "output_dict"\n        inference_state["output_dict_per_obj"] = {}\n        # A temporary storage to hold new outputs when user interact with a frame\n        # to add clicks or mask (it\'s merged into "output_dict" before propagation starts)\n        inference_state["temp_output_dict_per_obj"] = {}\n        # Frames that already holds consolidated outputs from click or mask inputs\n        # (we directly use their consolidated outputs during tracking)\n        inference_state["consolidated_frame_inds"] = {\n            "cond_frame_outputs": set(),  # set containing frame indices\n            "non_cond_frame_outputs": set(),  # set containing frame indices\n        }\n        # metadata for each tracking frame (e.g. which direction it\'s tracked)\n        inference_state["tracking_has_started"] = False\n        inference_state["frames_already_tracked"] = {}\n        # Warm up the visual backbone and cache the image feature on frame 0\n        self._get_image_feature(inference_state, frame_idx=0, batch_size=1)\n        return inference_state\n\n    @classmethod\n    def from_pretrained(cls, model_id: str, **kwargs) -> "SAM2VideoPredictor":\n        """\n        Load a pretrained model from the Hugging Face hub.\n\n        Arguments:\n          model_id (str): The Hugging Face repository ID.\n          **kwargs: Additional arguments to pass to the model constructor.\n\n        Returns:\n          (SAM2VideoPredictor): The loaded model.\n        """\n        from sam2.build_sam import build_sam2_video_predictor_hf\n\n        sam_model = build_sam2_video_predictor_hf(model_id, **kwargs)\n        return sam_model\n\n    def _obj_id_to_idx(self, inference_state, obj_id):\n        """Map client-side object id to model-side object index."""\n        obj_idx = inference_state["obj_id_to_idx"].get(obj_id, None)\n        if obj_idx is not None:\n            return obj_idx\n\n        # This is a new object id not sent to the server before. We only allow adding\n        # new objects *before* the tracking starts.\n        allow_new_object = not inference_state["tracking_has_started"]\n        if allow_new_object:\n            # get the next object slot\n            obj_idx = len(inference_state["obj_id_to_idx"])\n            inference_state["obj_id_to_idx"][obj_id] = obj_idx\n            inference_state["obj_idx_to_id"][obj_idx] = obj_id\n            inference_state["obj_ids"] = list(inference_state["obj_id_to_idx"])\n            # set up input and output structures for this object\n            inference_state["point_inputs_per_obj"][obj_idx] = {}\n            inference_state["mask_inputs_per_obj"][obj_idx] = {}\n            inference_state["output_dict_per_obj"][obj_idx] = {\n                "cond_frame_outputs": {},  # dict containing {frame_idx: <out>}\n                "non_cond_frame_outputs": {},  # dict containing {frame_idx: <out>}\n            }\n            inference_state["temp_output_dict_per_obj"][obj_idx] = {\n                "cond_frame_outputs": {},  # dict containing {frame_idx: <out>}\n                "non_cond_frame_outputs": {},  # dict containing {frame_idx: <out>}\n            }\n            return obj_idx\n        else:\n            raise RuntimeError(\n                f"Cannot add new object id {obj_id} after tracking starts. "\n                f"All existing object ids: {inference_state[\'obj_ids\']}. "\n                f"Please call \'reset_state\' to restart from scratch."\n            )\n\n    def _obj_idx_to_id(self, inference_state, obj_idx):\n        """Map model-side object index to client-side object id."""\n        return inference_state["obj_idx_to_id"][obj_idx]\n\n    def _get_obj_num(self, inference_state):\n        """Get the total number of unique object ids received so far in this session."""\n        return len(inference_state["obj_idx_to_id"])\n\n    @torch.inference_mode()\n    def add_new_points_or_box(\n        self,\n        inference_state,\n        frame_idx,\n        obj_id,\n        points=None,\n        labels=None,\n        clear_old_points=True,\n        normalize_coords=True,\n        box=None,\n    ):\n        """Add new points to a frame."""\n        obj_idx = self._obj_id_to_idx(inference_state, obj_id)\n        point_inputs_per_frame = inference_state["point_inputs_per_obj"][obj_idx]\n        mask_inputs_per_frame = inference_state["mask_inputs_per_obj"][obj_idx]\n\n        if (points is not None) != (labels is not None):\n            raise ValueError("points and labels must be provided together")\n        if points is None and box is None:\n            raise ValueError("at least one of points or box must be provided as input")\n\n        if points is None:\n            points = torch.zeros(0, 2, dtype=torch.float32)\n        elif not isinstance(points, torch.Tensor):\n            points = torch.tensor(points, dtype=torch.float32)\n        if labels is None:\n            labels = torch.zeros(0, dtype=torch.int32)\n        elif not isinstance(labels, torch.Tensor):\n            labels = torch.tensor(labels, dtype=torch.int32)\n        if points.dim() == 2:\n            points = points.unsqueeze(0)  # add batch dimension\n        if labels.dim() == 1:\n            labels = labels.unsqueeze(0)  # add batch dimension\n\n        # If `box` is provided, we add it as the first two points with labels 2 and 3\n        # along with the user-provided points (consistent with how SAM 2 is trained).\n        if box is not None:\n            if not clear_old_points:\n                raise ValueError(\n                    "cannot add box without clearing old points, since "\n                    "box prompt must be provided before any point prompt "\n                    "(please use clear_old_points=True instead)"\n                )\n            if inference_state["tracking_has_started"]:\n                warnings.warn(\n                    "You are adding a box after tracking starts. SAM 2 may not always be "\n                    "able to incorporate a box prompt for *refinement*. If you intend to "\n                    "use box prompt as an *initial* input before tracking, please call "\n                    "\'reset_state\' on the inference state to restart from scratch.",\n                    category=UserWarning,\n                    stacklevel=2,\n                )\n            if not isinstance(box, torch.Tensor):\n                box = torch.tensor(box, dtype=torch.float32, device=points.device)\n            box_coords = box.reshape(1, 2, 2)\n            box_labels = torch.tensor([2, 3], dtype=torch.int32, device=labels.device)\n            box_labels = box_labels.reshape(1, 2)\n            points = torch.cat([box_coords, points], dim=1)\n            labels = torch.cat([box_labels, labels], dim=1)\n\n        if normalize_coords:\n            video_H = inference_state["video_height"]\n            video_W = inference_state["video_width"]\n            points = points / torch.tensor([video_W, video_H]).to(points.device)\n        # scale the (normalized) coordinates by the model\'s internal image size\n        points = points * self.image_size\n        points = points.to(inference_state["device"])\n        labels = labels.to(inference_state["device"])\n\n        if not clear_old_points:\n            point_inputs = point_inputs_per_frame.get(frame_idx, None)\n        else:\n            point_inputs = None\n        point_inputs = concat_points(point_inputs, points, labels)\n\n        point_inputs_per_frame[frame_idx] = point_inputs\n        mask_inputs_per_frame.pop(frame_idx, None)\n        # If this frame hasn\'t been tracked before, we treat it as an initial conditioning\n        # frame, meaning that the inputs points are to generate segments on this frame without\n        # using any memory from other frames, like in SAM. Otherwise (if it has been tracked),\n        # the input points will be used to correct the already tracked masks.\n        is_init_cond_frame = frame_idx not in inference_state["frames_already_tracked"]\n        # whether to track in reverse time order\n        if is_init_cond_frame:\n            reverse = False\n        else:\n            reverse = inference_state["frames_already_tracked"][frame_idx]["reverse"]\n        obj_output_dict = inference_state["output_dict_per_obj"][obj_idx]\n        obj_temp_output_dict = inference_state["temp_output_dict_per_obj"][obj_idx]\n        # Add a frame to conditioning output if it\'s an initial conditioning frame or\n        # if the model sees all frames receiving clicks/mask as conditioning frames.\n        is_cond = is_init_cond_frame or self.add_all_frames_to_correct_as_cond\n        storage_key = "cond_frame_outputs" if is_cond else "non_cond_frame_outputs"\n\n        # Get any previously predicted mask logits on this object and feed it along with\n        # the new clicks into the SAM mask decoder.\n        prev_sam_mask_logits = None\n        # lookup temporary output dict first, which contains the most recent output\n        # (if not found, then lookup conditioning and non-conditioning frame output)\n        prev_out = obj_temp_output_dict[storage_key].get(frame_idx)\n        if prev_out is None:\n            prev_out = obj_output_dict["cond_frame_outputs"].get(frame_idx)\n            if prev_out is None:\n                prev_out = obj_output_dict["non_cond_frame_outputs"].get(frame_idx)\n\n        if prev_out is not None and prev_out["pred_masks"] is not None:\n            device = inference_state["device"]\n            prev_sam_mask_logits = prev_out["pred_masks"].to(device, non_blocking=True)\n            # Clamp the scale of prev_sam_mask_logits to avoid rare numerical issues.\n            prev_sam_mask_logits = torch.clamp(prev_sam_mask_logits, -32.0, 32.0)\n        current_out, _ = self._run_single_frame_inference(\n            inference_state=inference_state,\n            output_dict=obj_output_dict,  # run on the slice of a single object\n            frame_idx=frame_idx,\n            batch_size=1,  # run on the slice of a single object\n            is_init_cond_frame=is_init_cond_frame,\n            point_inputs=point_inputs,\n            mask_inputs=None,\n            reverse=reverse,\n            # Skip the memory encoder when adding clicks or mask. We execute the memory encoder\n            # at the beginning of `propagate_in_video` (after user finalize their clicks). This\n            # allows us to enforce non-overlapping constraints on all objects before encoding\n            # them into memory.\n            run_mem_encoder=False,\n            prev_sam_mask_logits=prev_sam_mask_logits,\n        )\n        # Add the output to the output dict (to be used as future memory)\n        obj_temp_output_dict[storage_key][frame_idx] = current_out\n\n        # Resize the output mask to the original video resolution\n        obj_ids = inference_state["obj_ids"]\n        consolidated_out = self._consolidate_temp_output_across_obj(\n            inference_state,\n            frame_idx,\n            is_cond=is_cond,\n            run_mem_encoder=False,\n            consolidate_at_video_res=True,\n        )\n        _, video_res_masks = self._get_orig_video_res_output(\n            inference_state, consolidated_out["pred_masks_video_res"]\n        )\n        return frame_idx, obj_ids, video_res_masks\n\n    def add_new_points(self, *args, **kwargs):\n        """Deprecated method. Please use `add_new_points_or_box` instead."""\n        return self.add_new_points_or_box(*args, **kwargs)\n\n    @torch.inference_mode()\n    def add_new_mask(\n        self,\n        inference_state,\n        frame_idx,\n        obj_id,\n        mask,\n    ):\n        """Add new mask to a frame."""\n        obj_idx = self._obj_id_to_idx(inference_state, obj_id)\n        point_inputs_per_frame = inference_state["point_inputs_per_obj"][obj_idx]\n        mask_inputs_per_frame = inference_state["mask_inputs_per_obj"][obj_idx]\n\n        if not isinstance(mask, torch.Tensor):\n            mask = torch.tensor(mask, dtype=torch.bool)\n        assert mask.dim() == 2\n        mask_H, mask_W = mask.shape\n        mask_inputs_orig = mask[None, None]  # add batch and channel dimension\n        mask_inputs_orig = mask_inputs_orig.float().to(inference_state["device"])\n\n        # resize the mask if it doesn\'t match the model\'s image size\n        if mask_H != self.image_size or mask_W != self.image_size:\n            mask_inputs = torch.nn.functional.interpolate(\n                mask_inputs_orig,\n                size=(self.image_size, self.image_size),\n                align_corners=False,\n                mode="bilinear",\n                antialias=True,  # use antialias for downsampling\n            )\n            mask_inputs = (mask_inputs >= 0.5).float()\n        else:\n            mask_inputs = mask_inputs_orig\n\n        mask_inputs_per_frame[frame_idx] = mask_inputs\n        point_inputs_per_frame.pop(frame_idx, None)\n        # If this frame hasn\'t been tracked before, we treat it as an initial conditioning\n        # frame, meaning that the inputs points are to generate segments on this frame without\n        # using any memory from other frames, like in SAM. Otherwise (if it has been tracked),\n        # the input points will be used to correct the already tracked masks.\n        is_init_cond_frame = frame_idx not in inference_state["frames_already_tracked"]\n        # whether to track in reverse time order\n        if is_init_cond_frame:\n            reverse = False\n        else:\n            reverse = inference_state["frames_already_tracked"][frame_idx]["reverse"]\n        obj_output_dict = inference_state["output_dict_per_obj"][obj_idx]\n        obj_temp_output_dict = inference_state["temp_output_dict_per_obj"][obj_idx]\n        # Add a frame to conditioning output if it\'s an initial conditioning frame or\n        # if the model sees all frames receiving clicks/mask as conditioning frames.\n        is_cond = is_init_cond_frame or self.add_all_frames_to_correct_as_cond\n        storage_key = "cond_frame_outputs" if is_cond else "non_cond_frame_outputs"\n\n        current_out, _ = self._run_single_frame_inference(\n            inference_state=inference_state,\n            output_dict=obj_output_dict,  # run on the slice of a single object\n            frame_idx=frame_idx,\n            batch_size=1,  # run on the slice of a single object\n            is_init_cond_frame=is_init_cond_frame,\n            point_inputs=None,\n            mask_inputs=mask_inputs,\n            reverse=reverse,\n            # Skip the memory encoder when adding clicks or mask. We execute the memory encoder\n            # at the beginning of `propagate_in_video` (after user finalize their clicks). This\n            # allows us to enforce non-overlapping constraints on all objects before encoding\n            # them into memory.\n            run_mem_encoder=False,\n        )\n        # Add the output to the output dict (to be used as future memory)\n        obj_temp_output_dict[storage_key][frame_idx] = current_out\n\n        # Resize the output mask to the original video resolution\n        obj_ids = inference_state["obj_ids"]\n        consolidated_out = self._consolidate_temp_output_across_obj(\n            inference_state,\n            frame_idx,\n            is_cond=is_cond,\n            run_mem_encoder=False,\n            consolidate_at_video_res=True,\n        )\n        _, video_res_masks = self._get_orig_video_res_output(\n            inference_state, consolidated_out["pred_masks_video_res"]\n        )\n        return frame_idx, obj_ids, video_res_masks\n\n    def _get_orig_video_res_output(self, inference_state, any_res_masks):\n        """\n        Resize the object scores to the original video resolution (video_res_masks)\n        and apply non-overlapping constraints for final output.\n        """\n        device = inference_state["device"]\n        video_H = inference_state["video_height"]\n        video_W = inference_state["video_width"]\n        any_res_masks = any_res_masks.to(device, non_blocking=True)\n        if any_res_masks.shape[-2:] == (video_H, video_W):\n            video_res_masks = any_res_masks\n        else:\n            video_res_masks = torch.nn.functional.interpolate(\n                any_res_masks,\n                size=(video_H, video_W),\n                mode="bilinear",\n                align_corners=False,\n            )\n        if self.non_overlap_masks:\n            video_res_masks = self._apply_non_overlapping_constraints(video_res_masks)\n        return any_res_masks, video_res_masks\n\n    def _consolidate_temp_output_across_obj(\n        self,\n        inference_state,\n        frame_idx,\n        is_cond,\n        run_mem_encoder,\n        consolidate_at_video_res=False,\n    ):\n        """\n        Consolidate the per-object temporary outputs in `temp_output_dict_per_obj` on\n        a frame into a single output for all objects, including\n        1) fill any missing objects either from `output_dict_per_obj` (if they exist in\n           `output_dict_per_obj` for this frame) or leave them as placeholder values\n           (if they don\'t exist in `output_dict_per_obj` for this frame);\n        2) if specified, rerun memory encoder after apply non-overlapping constraints\n           on the object scores.\n        """\n        batch_size = self._get_obj_num(inference_state)\n        storage_key = "cond_frame_outputs" if is_cond else "non_cond_frame_outputs"\n        # Optionally, we allow consolidating the temporary outputs at the original\n        # video resolution (to provide a better editing experience for mask prompts).\n        if consolidate_at_video_res:\n            assert not run_mem_encoder, "memory encoder cannot run at video resolution"\n            consolidated_H = inference_state["video_height"]\n            consolidated_W = inference_state["video_width"]\n            consolidated_mask_key = "pred_masks_video_res"\n        else:\n            consolidated_H = consolidated_W = self.image_size // 4\n            consolidated_mask_key = "pred_masks"\n\n        # Initialize `consolidated_out`. Its "maskmem_features" and "maskmem_pos_enc"\n        # will be added when rerunning the memory encoder after applying non-overlapping\n        # constraints to object scores. Its "pred_masks" are prefilled with a large\n        # negative value (NO_OBJ_SCORE) to represent missing objects.\n        consolidated_out = {\n            "maskmem_features": None,\n            "maskmem_pos_enc": None,\n            consolidated_mask_key: torch.full(\n                size=(batch_size, 1, consolidated_H, consolidated_W),\n                fill_value=NO_OBJ_SCORE,\n                dtype=torch.float32,\n                device=inference_state["storage_device"],\n            ),\n            "obj_ptr": torch.full(\n                size=(batch_size, self.hidden_dim),\n                fill_value=NO_OBJ_SCORE,\n                dtype=torch.float32,\n                device=inference_state["device"],\n            ),\n            "object_score_logits": torch.full(\n                size=(batch_size, 1),\n                # default to 10.0 for object_score_logits, i.e. assuming the object is\n                # present as sigmoid(10)=1, same as in `predict_masks` of `MaskDecoder`\n                fill_value=10.0,\n                dtype=torch.float32,\n                device=inference_state["device"],\n            ),\n        }\n        empty_mask_ptr = None\n        for obj_idx in range(batch_size):\n            obj_temp_output_dict = inference_state["temp_output_dict_per_obj"][obj_idx]\n            obj_output_dict = inference_state["output_dict_per_obj"][obj_idx]\n            out = obj_temp_output_dict[storage_key].get(frame_idx, None)\n            # If the object doesn\'t appear in "temp_output_dict_per_obj" on this frame,\n            # we fall back and look up its previous output in "output_dict_per_obj".\n            # We look up both "cond_frame_outputs" and "non_cond_frame_outputs" in\n            # "output_dict_per_obj" to find a previous output for this object.\n            if out is None:\n                out = obj_output_dict["cond_frame_outputs"].get(frame_idx, None)\n            if out is None:\n                out = obj_output_dict["non_cond_frame_outputs"].get(frame_idx, None)\n            # If the object doesn\'t appear in "output_dict_per_obj" either, we skip it\n            # and leave its mask scores to the default scores (i.e. the NO_OBJ_SCORE\n            # placeholder above) and set its object pointer to be a dummy pointer.\n            if out is None:\n                # Fill in dummy object pointers for those objects without any inputs or\n                # tracking outcomes on this frame (only do it under `run_mem_encoder=True`,\n                # i.e. when we need to build the memory for tracking).\n                if run_mem_encoder:\n                    if empty_mask_ptr is None:\n                        empty_mask_ptr = self._get_empty_mask_ptr(\n                            inference_state, frame_idx\n                        )\n                    # fill object pointer with a dummy pointer (based on an empty mask)\n                    consolidated_out["obj_ptr"][obj_idx : obj_idx + 1] = empty_mask_ptr\n                continue\n            # Add the temporary object output mask to consolidated output mask\n            obj_mask = out["pred_masks"]\n            consolidated_pred_masks = consolidated_out[consolidated_mask_key]\n            if obj_mask.shape[-2:] == consolidated_pred_masks.shape[-2:]:\n                consolidated_pred_masks[obj_idx : obj_idx + 1] = obj_mask\n            else:\n                # Resize first if temporary object mask has a different resolution\n                resized_obj_mask = torch.nn.functional.interpolate(\n                    obj_mask,\n                    size=consolidated_pred_masks.shape[-2:],\n                    mode="bilinear",\n                    align_corners=False,\n                )\n                consolidated_pred_masks[obj_idx : obj_idx + 1] = resized_obj_mask\n            consolidated_out["obj_ptr"][obj_idx : obj_idx + 1] = out["obj_ptr"]\n            consolidated_out["object_score_logits"][obj_idx : obj_idx + 1] = out[\n                "object_score_logits"\n            ]\n\n        # Optionally, apply non-overlapping constraints on the consolidated scores\n        # and rerun the memory encoder\n        if run_mem_encoder:\n            device = inference_state["device"]\n            high_res_masks = torch.nn.functional.interpolate(\n                consolidated_out["pred_masks"].to(device, non_blocking=True),\n                size=(self.image_size, self.image_size),\n                mode="bilinear",\n                align_corners=False,\n            )\n            if self.non_overlap_masks_for_mem_enc:\n                high_res_masks = self._apply_non_overlapping_constraints(high_res_masks)\n            maskmem_features, maskmem_pos_enc = self._run_memory_encoder(\n                inference_state=inference_state,\n                frame_idx=frame_idx,\n                batch_size=batch_size,\n                high_res_masks=high_res_masks,\n                object_score_logits=consolidated_out["object_score_logits"],\n                is_mask_from_pts=True,  # these frames are what the user interacted with\n            )\n            consolidated_out["maskmem_features"] = maskmem_features\n            consolidated_out["maskmem_pos_enc"] = maskmem_pos_enc\n\n        return consolidated_out\n\n    def _get_empty_mask_ptr(self, inference_state, frame_idx):\n        """Get a dummy object pointer based on an empty mask on the current frame."""\n        # A dummy (empty) mask with a single object\n        batch_size = 1\n        mask_inputs = torch.zeros(\n            (batch_size, 1, self.image_size, self.image_size),\n            dtype=torch.float32,\n            device=inference_state["device"],\n        )\n\n        # Retrieve correct image features\n        (\n            _,\n            _,\n            current_vision_feats,\n            current_vision_pos_embeds,\n            feat_sizes,\n        ) = self._get_image_feature(inference_state, frame_idx, batch_size)\n\n        # Feed the empty mask and image feature above to get a dummy object pointer\n        current_out = self.track_step(\n            frame_idx=frame_idx,\n            is_init_cond_frame=True,\n            current_vision_feats=current_vision_feats,\n            current_vision_pos_embeds=current_vision_pos_embeds,\n            feat_sizes=feat_sizes,\n            point_inputs=None,\n            mask_inputs=mask_inputs,\n            output_dict={},\n            num_frames=inference_state["num_frames"],\n            track_in_reverse=False,\n            run_mem_encoder=False,\n            prev_sam_mask_logits=None,\n        )\n        return current_out["obj_ptr"]\n\n    @torch.inference_mode()\n    def propagate_in_video_preflight(self, inference_state):\n        """Prepare inference_state and consolidate temporary outputs before tracking."""\n        # Tracking has started and we don\'t allow adding new objects until session is reset.\n        inference_state["tracking_has_started"] = True\n        batch_size = self._get_obj_num(inference_state)\n\n        # Consolidate per-object temporary outputs in "temp_output_dict_per_obj" and\n        # add them into "output_dict".\n        temp_output_dict_per_obj = inference_state["temp_output_dict_per_obj"]\n        output_dict = inference_state["output_dict"]\n        # "consolidated_frame_inds" contains indices of those frames where consolidated\n        # temporary outputs have been added (either in this call or any previous calls\n        # to `propagate_in_video_preflight`).\n        consolidated_frame_inds = inference_state["consolidated_frame_inds"]\n        for is_cond in [False, True]:\n            # Separately consolidate conditioning and non-conditioning temp outputs\n            storage_key = "cond_frame_outputs" if is_cond else "non_cond_frame_outputs"\n            # Find all the frames that contain temporary outputs for any objects\n            # (these should be the frames that have just received clicks for mask inputs\n            # via `add_new_points_or_box` or `add_new_mask`)\n            temp_frame_inds = set()\n            for obj_temp_output_dict in temp_output_dict_per_obj.values():\n                temp_frame_inds.update(obj_temp_output_dict[storage_key].keys())\n            consolidated_frame_inds[storage_key].update(temp_frame_inds)\n            # consolidate the temporary output across all objects on this frame\n            for frame_idx in temp_frame_inds:\n                consolidated_out = self._consolidate_temp_output_across_obj(\n                    inference_state, frame_idx, is_cond=is_cond, run_mem_encoder=True\n                )\n                # merge them into "output_dict" and also create per-object slices\n                output_dict[storage_key][frame_idx] = consolidated_out\n                self._add_output_per_object(\n                    inference_state, frame_idx, consolidated_out, storage_key\n                )\n                clear_non_cond_mem = self.clear_non_cond_mem_around_input and (\n                    self.clear_non_cond_mem_for_multi_obj or batch_size <= 1\n                )\n                if clear_non_cond_mem:\n                    # clear non-conditioning memory of the surrounding frames\n                    self._clear_non_cond_mem_around_input(inference_state, frame_idx)\n\n            # clear temporary outputs in `temp_output_dict_per_obj`\n            for obj_temp_output_dict in temp_output_dict_per_obj.values():\n                obj_temp_output_dict[storage_key].clear()\n\n        # edge case: if an output is added to "cond_frame_outputs", we remove any prior\n        # output on the same frame in "non_cond_frame_outputs"\n        for frame_idx in output_dict["cond_frame_outputs"]:\n            output_dict["non_cond_frame_outputs"].pop(frame_idx, None)\n        for obj_output_dict in inference_state["output_dict_per_obj"].values():\n            for frame_idx in obj_output_dict["cond_frame_outputs"]:\n                obj_output_dict["non_cond_frame_outputs"].pop(frame_idx, None)\n        for frame_idx in consolidated_frame_inds["cond_frame_outputs"]:\n            assert frame_idx in output_dict["cond_frame_outputs"]\n            consolidated_frame_inds["non_cond_frame_outputs"].discard(frame_idx)\n\n        # Make sure that the frame indices in "consolidated_frame_inds" are exactly those frames\n        # with either points or mask inputs (which should be true under a correct workflow).\n        all_consolidated_frame_inds = (\n            consolidated_frame_inds["cond_frame_outputs"]\n            | consolidated_frame_inds["non_cond_frame_outputs"]\n        )\n        input_frames_inds = set()\n        for point_inputs_per_frame in inference_state["point_inputs_per_obj"].values():\n            input_frames_inds.update(point_inputs_per_frame.keys())\n        for mask_inputs_per_frame in inference_state["mask_inputs_per_obj"].values():\n            input_frames_inds.update(mask_inputs_per_frame.keys())\n        assert all_consolidated_frame_inds == input_frames_inds\n\n    @torch.inference_mode()\n    def propagate_in_video(\n        self,\n        inference_state,\n        start_frame_idx=None,\n        max_frame_num_to_track=None,\n        reverse=False,\n    ):\n        """Propagate the input points across frames to track in the entire video."""\n        self.propagate_in_video_preflight(inference_state)\n\n        output_dict = inference_state["output_dict"]\n        consolidated_frame_inds = inference_state["consolidated_frame_inds"]\n        obj_ids = inference_state["obj_ids"]\n        num_frames = inference_state["num_frames"]\n        batch_size = self._get_obj_num(inference_state)\n        if len(output_dict["cond_frame_outputs"]) == 0:\n            raise RuntimeError("No points are provided; please add points first")\n        clear_non_cond_mem = self.clear_non_cond_mem_around_input and (\n            self.clear_non_cond_mem_for_multi_obj or batch_size <= 1\n        )\n\n        # set start index, end index, and processing order\n        if start_frame_idx is None:\n            # default: start from the earliest frame with input points\n            start_frame_idx = min(output_dict["cond_frame_outputs"])\n        if max_frame_num_to_track is None:\n            # default: track all the frames in the video\n            max_frame_num_to_track = num_frames\n        if reverse:\n            end_frame_idx = max(start_frame_idx - max_frame_num_to_track, 0)\n            if start_frame_idx > 0:\n                processing_order = range(start_frame_idx, end_frame_idx - 1, -1)\n            else:\n                processing_order = []  # skip reverse tracking if starting from frame 0\n        else:\n            end_frame_idx = min(\n                start_frame_idx + max_frame_num_to_track, num_frames - 1\n            )\n            processing_order = range(start_frame_idx, end_frame_idx + 1)\n\n        for frame_idx in tqdm(processing_order, desc="propagate in video"):\n            # We skip those frames already in consolidated outputs (these are frames\n            # that received input clicks or mask). Note that we cannot directly run\n            # batched forward on them via `_run_single_frame_inference` because the\n            # number of clicks on each object might be different.\n            if frame_idx in consolidated_frame_inds["cond_frame_outputs"]:\n                storage_key = "cond_frame_outputs"\n                current_out = output_dict[storage_key][frame_idx]\n                pred_masks = current_out["pred_masks"]\n                if clear_non_cond_mem:\n                    # clear non-conditioning memory of the surrounding frames\n                    self._clear_non_cond_mem_around_input(inference_state, frame_idx)\n            elif frame_idx in consolidated_frame_inds["non_cond_frame_outputs"]:\n                storage_key = "non_cond_frame_outputs"\n                current_out = output_dict[storage_key][frame_idx]\n                pred_masks = current_out["pred_masks"]\n            else:\n                storage_key = "non_cond_frame_outputs"\n                current_out, pred_masks = self._run_single_frame_inference(\n                    inference_state=inference_state,\n                    output_dict=output_dict,\n                    frame_idx=frame_idx,\n                    batch_size=batch_size,\n                    is_init_cond_frame=False,\n                    point_inputs=None,\n                    mask_inputs=None,\n                    reverse=reverse,\n                    run_mem_encoder=True,\n                )\n                output_dict[storage_key][frame_idx] = current_out\n            # Create slices of per-object outputs for subsequent interaction with each\n            # individual object after tracking.\n            self._add_output_per_object(\n                inference_state, frame_idx, current_out, storage_key\n            )\n            inference_state["frames_already_tracked"][frame_idx] = {"reverse": reverse}\n\n            # Resize the output mask to the original video resolution (we directly use\n            # the mask scores on GPU for output to avoid any CPU conversion in between)\n            _, video_res_masks = self._get_orig_video_res_output(\n                inference_state, pred_masks\n            )\n            yield frame_idx, obj_ids, video_res_masks\n\n    def _add_output_per_object(\n        self, inference_state, frame_idx, current_out, storage_key\n    ):\n        """\n        Split a multi-object output into per-object output slices and add them into\n        `output_dict_per_obj`. The resulting slices share the same tensor storage.\n        """\n        maskmem_features = current_out["maskmem_features"]\n        assert maskmem_features is None or isinstance(maskmem_features, torch.Tensor)\n\n        maskmem_pos_enc = current_out["maskmem_pos_enc"]\n        assert maskmem_pos_enc is None or isinstance(maskmem_pos_enc, list)\n\n        output_dict_per_obj = inference_state["output_dict_per_obj"]\n        for obj_idx, obj_output_dict in output_dict_per_obj.items():\n            obj_slice = slice(obj_idx, obj_idx + 1)\n            obj_out = {\n                "maskmem_features": None,\n                "maskmem_pos_enc": None,\n                "pred_masks": current_out["pred_masks"][obj_slice],\n                "obj_ptr": current_out["obj_ptr"][obj_slice],\n                "object_score_logits": current_out["object_score_logits"][obj_slice],\n            }\n            if maskmem_features is not None:\n                obj_out["maskmem_features"] = maskmem_features[obj_slice]\n            if maskmem_pos_enc is not None:\n                obj_out["maskmem_pos_enc"] = [x[obj_slice] for x in maskmem_pos_enc]\n            obj_output_dict[storage_key][frame_idx] = obj_out\n\n    @torch.inference_mode()\n    def clear_all_prompts_in_frame(\n        self, inference_state, frame_idx, obj_id, need_output=True\n    ):\n        """Remove all input points or mask in a specific frame for a given object."""\n        obj_idx = self._obj_id_to_idx(inference_state, obj_id)\n\n        # Clear the conditioning information on the given frame\n        inference_state["point_inputs_per_obj"][obj_idx].pop(frame_idx, None)\n        inference_state["mask_inputs_per_obj"][obj_idx].pop(frame_idx, None)\n\n        temp_output_dict_per_obj = inference_state["temp_output_dict_per_obj"]\n        temp_output_dict_per_obj[obj_idx]["cond_frame_outputs"].pop(frame_idx, None)\n        temp_output_dict_per_obj[obj_idx]["non_cond_frame_outputs"].pop(frame_idx, None)\n\n        # Check and see if there are still any inputs left on this frame\n        batch_size = self._get_obj_num(inference_state)\n        frame_has_input = False\n        for obj_idx2 in range(batch_size):\n            if frame_idx in inference_state["point_inputs_per_obj"][obj_idx2]:\n                frame_has_input = True\n                break\n            if frame_idx in inference_state["mask_inputs_per_obj"][obj_idx2]:\n                frame_has_input = True\n                break\n\n        # If this frame has no remaining inputs for any objects, we further clear its\n        # conditioning frame status\n        if not frame_has_input:\n            output_dict = inference_state["output_dict"]\n            consolidated_frame_inds = inference_state["consolidated_frame_inds"]\n            consolidated_frame_inds["cond_frame_outputs"].discard(frame_idx)\n            consolidated_frame_inds["non_cond_frame_outputs"].discard(frame_idx)\n            # Remove the frame\'s conditioning output (possibly downgrading it to non-conditioning)\n            out = output_dict["cond_frame_outputs"].pop(frame_idx, None)\n            if out is not None:\n                # The frame is not a conditioning frame anymore since it\'s not receiving inputs,\n                # so we "downgrade" its output (if exists) to a non-conditioning frame output.\n                output_dict["non_cond_frame_outputs"][frame_idx] = out\n                inference_state["frames_already_tracked"].pop(frame_idx, None)\n            # Similarly, do it for the sliced output on each object.\n            for obj_idx2 in range(batch_size):\n                obj_output_dict = inference_state["output_dict_per_obj"][obj_idx2]\n                obj_out = obj_output_dict["cond_frame_outputs"].pop(frame_idx, None)\n                if obj_out is not None:\n                    obj_output_dict["non_cond_frame_outputs"][frame_idx] = obj_out\n\n            # If all the conditioning frames have been removed, we also clear the tracking outputs\n            if len(output_dict["cond_frame_outputs"]) == 0:\n                self._reset_tracking_results(inference_state)\n\n        if not need_output:\n            return\n        # Finally, output updated masks per object (after removing the inputs above)\n        obj_ids = inference_state["obj_ids"]\n        is_cond = any(\n            frame_idx in obj_temp_output_dict["cond_frame_outputs"]\n            for obj_temp_output_dict in temp_output_dict_per_obj.values()\n        )\n        consolidated_out = self._consolidate_temp_output_across_obj(\n            inference_state,\n            frame_idx,\n            is_cond=is_cond,\n            run_mem_encoder=False,\n            consolidate_at_video_res=True,\n        )\n        _, video_res_masks = self._get_orig_video_res_output(\n            inference_state, consolidated_out["pred_masks_video_res"]\n        )\n        return frame_idx, obj_ids, video_res_masks\n\n    @torch.inference_mode()\n    def reset_state(self, inference_state):\n        """Remove all input points or mask in all frames throughout the video."""\n        self._reset_tracking_results(inference_state)\n        # Remove all object ids\n        inference_state["obj_id_to_idx"].clear()\n        inference_state["obj_idx_to_id"].clear()\n        inference_state["obj_ids"].clear()\n        inference_state["point_inputs_per_obj"].clear()\n        inference_state["mask_inputs_per_obj"].clear()\n        inference_state["output_dict_per_obj"].clear()\n        inference_state["temp_output_dict_per_obj"].clear()\n\n    def _reset_tracking_results(self, inference_state):\n        """Reset all tracking inputs and results across the videos."""\n        for v in inference_state["point_inputs_per_obj"].values():\n            v.clear()\n        for v in inference_state["mask_inputs_per_obj"].values():\n            v.clear()\n        for v in inference_state["output_dict_per_obj"].values():\n            v["cond_frame_outputs"].clear()\n            v["non_cond_frame_outputs"].clear()\n        for v in inference_state["temp_output_dict_per_obj"].values():\n            v["cond_frame_outputs"].clear()\n            v["non_cond_frame_outputs"].clear()\n        inference_state["output_dict"]["cond_frame_outputs"].clear()\n        inference_state["output_dict"]["non_cond_frame_outputs"].clear()\n        inference_state["consolidated_frame_inds"]["cond_frame_outputs"].clear()\n        inference_state["consolidated_frame_inds"]["non_cond_frame_outputs"].clear()\n        inference_state["tracking_has_started"] = False\n        inference_state["frames_already_tracked"].clear()\n\n    def _get_image_feature(self, inference_state, frame_idx, batch_size):\n        """Compute the image features on a given frame."""\n        # Look up in the cache first\n        image, backbone_out = inference_state["cached_features"].get(\n            frame_idx, (None, None)\n        )\n        if backbone_out is None:\n            # Cache miss -- we will run inference on a single image\n            device = inference_state["device"]\n            image = inference_state["images"][frame_idx].to(device).float().unsqueeze(0)\n            backbone_out = self.forward_image(image)\n            # Cache the most recent frame\'s feature (for repeated interactions with\n            # a frame; we can use an LRU cache for more frames in the future).\n            inference_state["cached_features"] = {frame_idx: (image, backbone_out)}\n\n        # expand the features to have the same dimension as the number of objects\n        expanded_image = image.expand(batch_size, -1, -1, -1)\n        expanded_backbone_out = {\n            "backbone_fpn": backbone_out["backbone_fpn"].copy(),\n            "vision_pos_enc": backbone_out["vision_pos_enc"].copy(),\n        }\n        for i, feat in enumerate(expanded_backbone_out["backbone_fpn"]):\n            expanded_backbone_out["backbone_fpn"][i] = feat.expand(\n                batch_size, -1, -1, -1\n            )\n        for i, pos in enumerate(expanded_backbone_out["vision_pos_enc"]):\n            pos = pos.expand(batch_size, -1, -1, -1)\n            expanded_backbone_out["vision_pos_enc"][i] = pos\n\n        features = self._prepare_backbone_features(expanded_backbone_out)\n        features = (expanded_image,) + features\n        return features\n\n    def _run_single_frame_inference(\n        self,\n        inference_state,\n        output_dict,\n        frame_idx,\n        batch_size,\n        is_init_cond_frame,\n        point_inputs,\n        mask_inputs,\n        reverse,\n        run_mem_encoder,\n        prev_sam_mask_logits=None,\n    ):\n        """Run tracking on a single frame based on current inputs and previous memory."""\n        # Retrieve correct image features\n        (\n            _,\n            _,\n            current_vision_feats,\n            current_vision_pos_embeds,\n            feat_sizes,\n        ) = self._get_image_feature(inference_state, frame_idx, batch_size)\n\n        # point and mask should not appear as input simultaneously on the same frame\n        assert point_inputs is None or mask_inputs is None\n        current_out = self.track_step(\n            frame_idx=frame_idx,\n            is_init_cond_frame=is_init_cond_frame,\n            current_vision_feats=current_vision_feats,\n            current_vision_pos_embeds=current_vision_pos_embeds,\n            feat_sizes=feat_sizes,\n            point_inputs=point_inputs,\n            mask_inputs=mask_inputs,\n            output_dict=output_dict,\n            num_frames=inference_state["num_frames"],\n            track_in_reverse=reverse,\n            run_mem_encoder=run_mem_encoder,\n            prev_sam_mask_logits=prev_sam_mask_logits,\n        )\n\n        # optionally offload the output to CPU memory to save GPU space\n        storage_device = inference_state["storage_device"]\n        maskmem_features = current_out["maskmem_features"]\n        if maskmem_features is not None:\n            maskmem_features = maskmem_features.to(torch.bfloat16)\n            maskmem_features = maskmem_features.to(storage_device, non_blocking=True)\n        pred_masks_gpu = current_out["pred_masks"]\n        # potentially fill holes in the predicted masks\n        if self.fill_hole_area > 0:\n            pred_masks_gpu = fill_holes_in_mask_scores(\n                pred_masks_gpu, self.fill_hole_area\n            )\n        pred_masks = pred_masks_gpu.to(storage_device, non_blocking=True)\n        # "maskmem_pos_enc" is the same across frames, so we only need to store one copy of it\n        maskmem_pos_enc = self._get_maskmem_pos_enc(inference_state, current_out)\n        # object pointer is a small tensor, so we always keep it on GPU memory for fast access\n        obj_ptr = current_out["obj_ptr"]\n        object_score_logits = current_out["object_score_logits"]\n        # make a compact version of this frame\'s output to reduce the state size\n        compact_current_out = {\n            "maskmem_features": maskmem_features,\n            "maskmem_pos_enc": maskmem_pos_enc,\n            "pred_masks": pred_masks,\n            "obj_ptr": obj_ptr,\n            "object_score_logits": object_score_logits,\n        }\n        return compact_current_out, pred_masks_gpu\n\n    def _run_memory_encoder(\n        self,\n        inference_state,\n        frame_idx,\n        batch_size,\n        high_res_masks,\n        object_score_logits,\n        is_mask_from_pts,\n    ):\n        """\n        Run the memory encoder on `high_res_masks`. This is usually after applying\n        non-overlapping constraints to object scores. Since their scores changed, their\n        memory also need to be computed again with the memory encoder.\n        """\n        # Retrieve correct image features\n        _, _, current_vision_feats, _, feat_sizes = self._get_image_feature(\n            inference_state, frame_idx, batch_size\n        )\n        maskmem_features, maskmem_pos_enc = self._encode_new_memory(\n            current_vision_feats=current_vision_feats,\n            feat_sizes=feat_sizes,\n            pred_masks_high_res=high_res_masks,\n            object_score_logits=object_score_logits,\n            is_mask_from_pts=is_mask_from_pts,\n        )\n\n        # optionally offload the output to CPU memory to save GPU space\n        storage_device = inference_state["storage_device"]\n        maskmem_features = maskmem_features.to(torch.bfloat16)\n        maskmem_features = maskmem_features.to(storage_device, non_blocking=True)\n        # "maskmem_pos_enc" is the same across frames, so we only need to store one copy of it\n        maskmem_pos_enc = self._get_maskmem_pos_enc(\n            inference_state, {"maskmem_pos_enc": maskmem_pos_enc}\n        )\n        return maskmem_features, maskmem_pos_enc\n\n    def _get_maskmem_pos_enc(self, inference_state, current_out):\n        """\n        `maskmem_pos_enc` is the same across frames and objects, so we cache it as\n        a constant in the inference session to reduce session storage size.\n        """\n        model_constants = inference_state["constants"]\n        # "out_maskmem_pos_enc" should be either a list of tensors or None\n        out_maskmem_pos_enc = current_out["maskmem_pos_enc"]\n        if out_maskmem_pos_enc is not None:\n            if "maskmem_pos_enc" not in model_constants:\n                assert isinstance(out_maskmem_pos_enc, list)\n                # only take the slice for one object, since it\'s same across objects\n                maskmem_pos_enc = [x[0:1].clone() for x in out_maskmem_pos_enc]\n                model_constants["maskmem_pos_enc"] = maskmem_pos_enc\n            else:\n                maskmem_pos_enc = model_constants["maskmem_pos_enc"]\n            # expand the cached maskmem_pos_enc to the actual batch size\n            batch_size = out_maskmem_pos_enc[0].size(0)\n            if (\n                out_maskmem_pos_enc[0].ndim == 3\n            ):  # (B, HW, C) because of spatial perceiver\n                expanded_maskmem_pos_enc = [\n                    x.expand(batch_size, -1, -1) for x in maskmem_pos_enc\n                ]\n            else:  # (B, C, H, W)\n                expanded_maskmem_pos_enc = [\n                    x.expand(batch_size, -1, -1, -1) for x in maskmem_pos_enc\n                ]\n        else:\n            expanded_maskmem_pos_enc = None\n        return expanded_maskmem_pos_enc\n\n    @torch.inference_mode()\n    def remove_object(self, inference_state, obj_id, strict=False, need_output=True):\n        """\n        Remove an object id from the tracking state. If strict is True, we check whether\n        the object id actually exists and raise an error if it doesn\'t exist.\n        """\n        old_obj_idx_to_rm = inference_state["obj_id_to_idx"].get(obj_id, None)\n        updated_frames = []\n        # Check whether this object_id to remove actually exists and possibly raise an error.\n        if old_obj_idx_to_rm is None:\n            if not strict:\n                return inference_state["obj_ids"], updated_frames\n            raise RuntimeError(\n                f"Cannot remove object id {obj_id} as it doesn\'t exist. "\n                f"All existing object ids: {inference_state[\'obj_ids\']}."\n            )\n\n        # If this is the only remaining object id, we simply reset the state.\n        if len(inference_state["obj_id_to_idx"]) == 1:\n            self.reset_state(inference_state)\n            return inference_state["obj_ids"], updated_frames\n\n        # There are still remaining objects after removing this object id. In this case,\n        # we need to delete the object storage from inference state tensors.\n        # Step 0: clear the input on those frames where this object id has point or mask input\n        # (note that this step is required as it might downgrade conditioning frames to\n        # non-conditioning ones)\n        obj_input_frames_inds = set()\n        obj_input_frames_inds.update(\n            inference_state["point_inputs_per_obj"][old_obj_idx_to_rm]\n        )\n        obj_input_frames_inds.update(\n            inference_state["mask_inputs_per_obj"][old_obj_idx_to_rm]\n        )\n        for frame_idx in obj_input_frames_inds:\n            self.clear_all_prompts_in_frame(\n                inference_state, frame_idx, obj_id, need_output=False\n            )\n\n        # Step 1: Update the object id mapping (note that it must be done after Step 0,\n        # since Step 0 still requires the old object id mappings in inference_state)\n        old_obj_ids = inference_state["obj_ids"]\n        old_obj_inds = list(range(len(old_obj_ids)))\n        remain_old_obj_inds = old_obj_inds.copy()\n        remain_old_obj_inds.remove(old_obj_idx_to_rm)\n        new_obj_ids = [old_obj_ids[old_idx] for old_idx in remain_old_obj_inds]\n        new_obj_inds = list(range(len(new_obj_ids)))\n        # build new mappings\n        old_idx_to_new_idx = dict(zip(remain_old_obj_inds, new_obj_inds))\n        inference_state["obj_id_to_idx"] = dict(zip(new_obj_ids, new_obj_inds))\n        inference_state["obj_idx_to_id"] = dict(zip(new_obj_inds, new_obj_ids))\n        inference_state["obj_ids"] = new_obj_ids\n\n        # Step 2: For per-object tensor storage, we shift their obj_idx in the dict keys.\n        # (note that "consolidated_frame_inds" doesn\'t need to be updated in this step as\n        # it\'s already handled in Step 0)\n        def _map_keys(container):\n            new_kvs = []\n            for k in old_obj_inds:\n                v = container.pop(k)\n                if k in old_idx_to_new_idx:\n                    new_kvs.append((old_idx_to_new_idx[k], v))\n            container.update(new_kvs)\n\n        _map_keys(inference_state["point_inputs_per_obj"])\n        _map_keys(inference_state["mask_inputs_per_obj"])\n        _map_keys(inference_state["output_dict_per_obj"])\n        _map_keys(inference_state["temp_output_dict_per_obj"])\n\n        # Step 3: For packed tensor storage, we index the remaining ids and rebuild the per-object slices.\n        def _slice_state(output_dict, storage_key):\n            for frame_idx, out in output_dict[storage_key].items():\n                out["maskmem_features"] = out["maskmem_features"][remain_old_obj_inds]\n                out["maskmem_pos_enc"] = [\n                    x[remain_old_obj_inds] for x in out["maskmem_pos_enc"]\n                ]\n                # "maskmem_pos_enc" is the same across frames, so we only need to store one copy of it\n                out["maskmem_pos_enc"] = self._get_maskmem_pos_enc(inference_state, out)\n                out["pred_masks"] = out["pred_masks"][remain_old_obj_inds]\n                out["obj_ptr"] = out["obj_ptr"][remain_old_obj_inds]\n                out["object_score_logits"] = out["object_score_logits"][\n                    remain_old_obj_inds\n                ]\n                # also update the per-object slices\n                self._add_output_per_object(\n                    inference_state, frame_idx, out, storage_key\n                )\n\n        _slice_state(inference_state["output_dict"], "cond_frame_outputs")\n        _slice_state(inference_state["output_dict"], "non_cond_frame_outputs")\n\n        # Step 4: Further collect the outputs on those frames in `obj_input_frames_inds`, which\n        # could show an updated mask for objects previously occluded by the object being removed\n        if need_output:\n            temp_output_dict_per_obj = inference_state["temp_output_dict_per_obj"]\n            for frame_idx in obj_input_frames_inds:\n                is_cond = any(\n                    frame_idx in obj_temp_output_dict["cond_frame_outputs"]\n                    for obj_temp_output_dict in temp_output_dict_per_obj.values()\n                )\n                consolidated_out = self._consolidate_temp_output_across_obj(\n                    inference_state,\n                    frame_idx,\n                    is_cond=is_cond,\n                    run_mem_encoder=False,\n                    consolidate_at_video_res=True,\n                )\n                _, video_res_masks = self._get_orig_video_res_output(\n                    inference_state, consolidated_out["pred_masks_video_res"]\n                )\n                updated_frames.append((frame_idx, video_res_masks))\n\n        return inference_state["obj_ids"], updated_frames\n\n    def _clear_non_cond_mem_around_input(self, inference_state, frame_idx):\n        """\n        Remove the non-conditioning memory around the input frame. When users provide\n        correction clicks, the surrounding frames\' non-conditioning memories can still\n        contain outdated object appearance information and could confuse the model.\n\n        This method clears those non-conditioning memories surrounding the interacted\n        frame to avoid giving the model both old and new information about the object.\n        """\n        r = self.memory_temporal_stride_for_eval\n        frame_idx_begin = frame_idx - r * self.num_maskmem\n        frame_idx_end = frame_idx + r * self.num_maskmem\n        output_dict = inference_state["output_dict"]\n        non_cond_frame_outputs = output_dict["non_cond_frame_outputs"]\n        for t in range(frame_idx_begin, frame_idx_end + 1):\n            non_cond_frame_outputs.pop(t, None)\n            for obj_output_dict in inference_state["output_dict_per_obj"].values():\n                obj_output_dict["non_cond_frame_outputs"].pop(t, None)\n', '_shared_test_resources/code/EdgeTAM/sam2/build_sam.py': '# Copyright (c) Meta Platforms, Inc. and affiliates.\n# All rights reserved.\n\n# This source code is licensed under the license found in the\n# LICENSE file in the root directory of this source tree.\n\nimport logging\nimport os\n\nimport sam2\n\nimport torch\nfrom hydra import compose\nfrom hydra.utils import instantiate\nfrom omegaconf import OmegaConf\n\n# Check if the user is running Python from the parent directory of the sam2 repo\n# (i.e. the directory where this repo is cloned into) -- this is not supported since\n# it could shadow the sam2 package and cause issues.\nif os.path.isdir(os.path.join(sam2.__path__[0], "sam2")):\n    # If the user has "sam2/sam2" in their path, they are likey importing the repo itself\n    # as "sam2" rather than importing the "sam2" python package (i.e. "sam2/sam2" directory).\n    # This typically happens because the user is running Python from the parent directory\n    # that contains the sam2 repo they cloned.\n    raise RuntimeError(\n        "You\'re likely running Python from the parent directory of the sam2 repository "\n        "(i.e. the directory where https://github.com/facebookresearch/sam2 is cloned into). "\n        "This is not supported since the `sam2` Python package could be shadowed by the "\n        "repository name (the repository is also named `sam2` and contains the Python package "\n        "in `sam2/sam2`). Please run Python from another directory (e.g. from the repo dir "\n        "rather than its parent dir, or from your home directory) after installing SAM 2."\n    )\n\n\nHF_MODEL_ID_TO_FILENAMES = {\n    "facebook/sam2-hiera-tiny": (\n        "configs/sam2/sam2_hiera_t.yaml",\n        "sam2_hiera_tiny.pt",\n    ),\n    "facebook/sam2-hiera-small": (\n        "configs/sam2/sam2_hiera_s.yaml",\n        "sam2_hiera_small.pt",\n    ),\n    "facebook/sam2-hiera-base-plus": (\n        "configs/sam2/sam2_hiera_b+.yaml",\n        "sam2_hiera_base_plus.pt",\n    ),\n    "facebook/sam2-hiera-large": (\n        "configs/sam2/sam2_hiera_l.yaml",\n        "sam2_hiera_large.pt",\n    ),\n    "facebook/sam2.1-hiera-tiny": (\n        "configs/sam2.1/sam2.1_hiera_t.yaml",\n        "sam2.1_hiera_tiny.pt",\n    ),\n    "facebook/sam2.1-hiera-small": (\n        "configs/sam2.1/sam2.1_hiera_s.yaml",\n        "sam2.1_hiera_small.pt",\n    ),\n    "facebook/sam2.1-hiera-base-plus": (\n        "configs/sam2.1/sam2.1_hiera_b+.yaml",\n        "sam2.1_hiera_base_plus.pt",\n    ),\n    "facebook/sam2.1-hiera-large": (\n        "configs/sam2.1/sam2.1_hiera_l.yaml",\n        "sam2.1_hiera_large.pt",\n    ),\n}\n\n\ndef build_sam2(\n    config_file,\n    ckpt_path=None,\n    device="cuda",\n    mode="eval",\n    hydra_overrides_extra=[],\n    apply_postprocessing=True,\n    **kwargs,\n):\n\n    if apply_postprocessing:\n        hydra_overrides_extra = hydra_overrides_extra.copy()\n        hydra_overrides_extra += [\n            # dynamically fall back to multi-mask if the single mask is not stable\n            "++model.sam_mask_decoder_extra_args.dynamic_multimask_via_stability=true",\n            "++model.sam_mask_decoder_extra_args.dynamic_multimask_stability_delta=0.05",\n            "++model.sam_mask_decoder_extra_args.dynamic_multimask_stability_thresh=0.98",\n        ]\n    # Read config and init model\n    cfg = compose(config_name=config_file, overrides=hydra_overrides_extra)\n    OmegaConf.resolve(cfg)\n    model = instantiate(cfg.model, _recursive_=True)\n    _load_checkpoint(model, ckpt_path)\n    model = model.to(device)\n    if mode == "eval":\n        model.eval()\n    return model\n\n\ndef build_sam2_video_predictor(\n    config_file,\n    ckpt_path=None,\n    device="cuda",\n    mode="eval",\n    hydra_overrides_extra=[],\n    apply_postprocessing=True,\n    **kwargs,\n):\n    hydra_overrides = [\n        "++model._target_=sam2.sam2_video_predictor.SAM2VideoPredictor",\n    ]\n    if apply_postprocessing:\n        hydra_overrides_extra = hydra_overrides_extra.copy()\n        hydra_overrides_extra += [\n            # dynamically fall back to multi-mask if the single mask is not stable\n            "++model.sam_mask_decoder_extra_args.dynamic_multimask_via_stability=true",\n            "++model.sam_mask_decoder_extra_args.dynamic_multimask_stability_delta=0.05",\n            "++model.sam_mask_decoder_extra_args.dynamic_multimask_stability_thresh=0.98",\n            # the sigmoid mask logits on interacted frames with clicks in the memory encoder so that the encoded masks are exactly as what users see from clicking\n            "++model.binarize_mask_from_pts_for_mem_enc=true",\n            # fill small holes in the low-res masks up to `fill_hole_area` (before resizing them to the original video resolution)\n            "++model.fill_hole_area=8",\n        ]\n    hydra_overrides.extend(hydra_overrides_extra)\n\n    # Read config and init model\n    cfg = compose(config_name=config_file, overrides=hydra_overrides)\n    OmegaConf.resolve(cfg)\n    print("configuration solved")\n    model = instantiate(cfg.model, _recursive_=True)\n    print("model instantiated")\n    _load_checkpoint(model, ckpt_path)\n    print("checkpoint loaded")\n    model = model.to(device)\n    if mode == "eval":\n        model.eval()\n    print("model ready")\n    return model\n\n\ndef _hf_download(model_id):\n    from huggingface_hub import hf_hub_download\n\n    config_name, checkpoint_name = HF_MODEL_ID_TO_FILENAMES[model_id]\n    ckpt_path = hf_hub_download(repo_id=model_id, filename=checkpoint_name)\n    return config_name, ckpt_path\n\n\ndef build_sam2_hf(model_id, **kwargs):\n    config_name, ckpt_path = _hf_download(model_id)\n    return build_sam2(config_file=config_name, ckpt_path=ckpt_path, **kwargs)\n\n\ndef build_sam2_video_predictor_hf(model_id, **kwargs):\n    config_name, ckpt_path = _hf_download(model_id)\n    return build_sam2_video_predictor(\n        config_file=config_name, ckpt_path=ckpt_path, **kwargs\n    )\n\n\ndef _load_checkpoint(model, ckpt_path):\n    if ckpt_path is not None:\n        sd = torch.load(ckpt_path, map_location="cpu", weights_only=True)["model"]\n        missing_keys, unexpected_keys = model.load_state_dict(sd)\n        if missing_keys:\n            logging.error(missing_keys)\n            raise RuntimeError()\n        if unexpected_keys:\n            logging.error(unexpected_keys)\n            raise RuntimeError()\n        logging.info("Loaded checkpoint sucessfully")\n', '_shared_test_resources/code/EdgeTAM/sam2/__init__.py': '# Copyright (c) Meta Platforms, Inc. and affiliates.\n# All rights reserved.\n\n# This source code is licensed under the license found in the\n# LICENSE file in the root directory of this source tree.\n\nfrom hydra import initialize_config_module\nfrom hydra.core.global_hydra import GlobalHydra\n\nif not GlobalHydra.instance().is_initialized():\n    initialize_config_module("sam2", version_base="1.2")\n', '_shared_test_resources/code/EdgeTAM/sam2/utils/amg.py': '# Copyright (c) Meta Platforms, Inc. and affiliates.\n# All rights reserved.\n\n# This source code is licensed under the license found in the\n# LICENSE file in the root directory of this source tree.\n\nimport math\nfrom copy import deepcopy\nfrom itertools import product\nfrom typing import Any, Dict, Generator, ItemsView, List, Tuple\n\nimport numpy as np\nimport torch\n\n# Very lightly adapted from https://github.com/facebookresearch/segment-anything/blob/main/segment_anything/utils/amg.py\n\n\nclass MaskData:\n    """\n    A structure for storing masks and their related data in batched format.\n    Implements basic filtering and concatenation.\n    """\n\n    def __init__(self, **kwargs) -> None:\n        for v in kwargs.values():\n            assert isinstance(\n                v, (list, np.ndarray, torch.Tensor)\n            ), "MaskData only supports list, numpy arrays, and torch tensors."\n        self._stats = dict(**kwargs)\n\n    def __setitem__(self, key: str, item: Any) -> None:\n        assert isinstance(\n            item, (list, np.ndarray, torch.Tensor)\n        ), "MaskData only supports list, numpy arrays, and torch tensors."\n        self._stats[key] = item\n\n    def __delitem__(self, key: str) -> None:\n        del self._stats[key]\n\n    def __getitem__(self, key: str) -> Any:\n        return self._stats[key]\n\n    def items(self) -> ItemsView[str, Any]:\n        return self._stats.items()\n\n    def filter(self, keep: torch.Tensor) -> None:\n        for k, v in self._stats.items():\n            if v is None:\n                self._stats[k] = None\n            elif isinstance(v, torch.Tensor):\n                self._stats[k] = v[torch.as_tensor(keep, device=v.device)]\n            elif isinstance(v, np.ndarray):\n                self._stats[k] = v[keep.detach().cpu().numpy()]\n            elif isinstance(v, list) and keep.dtype == torch.bool:\n                self._stats[k] = [a for i, a in enumerate(v) if keep[i]]\n            elif isinstance(v, list):\n                self._stats[k] = [v[i] for i in keep]\n            else:\n                raise TypeError(f"MaskData key {k} has an unsupported type {type(v)}.")\n\n    def cat(self, new_stats: "MaskData") -> None:\n        for k, v in new_stats.items():\n            if k not in self._stats or self._stats[k] is None:\n                self._stats[k] = deepcopy(v)\n            elif isinstance(v, torch.Tensor):\n                self._stats[k] = torch.cat([self._stats[k], v], dim=0)\n            elif isinstance(v, np.ndarray):\n                self._stats[k] = np.concatenate([self._stats[k], v], axis=0)\n            elif isinstance(v, list):\n                self._stats[k] = self._stats[k] + deepcopy(v)\n            else:\n                raise TypeError(f"MaskData key {k} has an unsupported type {type(v)}.")\n\n    def to_numpy(self) -> None:\n        for k, v in self._stats.items():\n            if isinstance(v, torch.Tensor):\n                self._stats[k] = v.float().detach().cpu().numpy()\n\n\ndef is_box_near_crop_edge(\n    boxes: torch.Tensor, crop_box: List[int], orig_box: List[int], atol: float = 20.0\n) -> torch.Tensor:\n    """Filter masks at the edge of a crop, but not at the edge of the original image."""\n    crop_box_torch = torch.as_tensor(crop_box, dtype=torch.float, device=boxes.device)\n    orig_box_torch = torch.as_tensor(orig_box, dtype=torch.float, device=boxes.device)\n    boxes = uncrop_boxes_xyxy(boxes, crop_box).float()\n    near_crop_edge = torch.isclose(boxes, crop_box_torch[None, :], atol=atol, rtol=0)\n    near_image_edge = torch.isclose(boxes, orig_box_torch[None, :], atol=atol, rtol=0)\n    near_crop_edge = torch.logical_and(near_crop_edge, ~near_image_edge)\n    return torch.any(near_crop_edge, dim=1)\n\n\ndef box_xyxy_to_xywh(box_xyxy: torch.Tensor) -> torch.Tensor:\n    box_xywh = deepcopy(box_xyxy)\n    box_xywh[2] = box_xywh[2] - box_xywh[0]\n    box_xywh[3] = box_xywh[3] - box_xywh[1]\n    return box_xywh\n\n\ndef batch_iterator(batch_size: int, *args) -> Generator[List[Any], None, None]:\n    assert len(args) > 0 and all(\n        len(a) == len(args[0]) for a in args\n    ), "Batched iteration must have inputs of all the same size."\n    n_batches = len(args[0]) // batch_size + int(len(args[0]) % batch_size != 0)\n    for b in range(n_batches):\n        yield [arg[b * batch_size : (b + 1) * batch_size] for arg in args]\n\n\ndef mask_to_rle_pytorch(tensor: torch.Tensor) -> List[Dict[str, Any]]:\n    """\n    Encodes masks to an uncompressed RLE, in the format expected by\n    pycoco tools.\n    """\n    # Put in fortran order and flatten h,w\n    b, h, w = tensor.shape\n    tensor = tensor.permute(0, 2, 1).flatten(1)\n\n    # Compute change indices\n    diff = tensor[:, 1:] ^ tensor[:, :-1]\n    change_indices = diff.nonzero()\n\n    # Encode run length\n    out = []\n    for i in range(b):\n        cur_idxs = change_indices[change_indices[:, 0] == i, 1]\n        cur_idxs = torch.cat(\n            [\n                torch.tensor([0], dtype=cur_idxs.dtype, device=cur_idxs.device),\n                cur_idxs + 1,\n                torch.tensor([h * w], dtype=cur_idxs.dtype, device=cur_idxs.device),\n            ]\n        )\n        btw_idxs = cur_idxs[1:] - cur_idxs[:-1]\n        counts = [] if tensor[i, 0] == 0 else [0]\n        counts.extend(btw_idxs.detach().cpu().tolist())\n        out.append({"size": [h, w], "counts": counts})\n    return out\n\n\ndef rle_to_mask(rle: Dict[str, Any]) -> np.ndarray:\n    """Compute a binary mask from an uncompressed RLE."""\n    h, w = rle["size"]\n    mask = np.empty(h * w, dtype=bool)\n    idx = 0\n    parity = False\n    for count in rle["counts"]:\n        mask[idx : idx + count] = parity\n        idx += count\n        parity ^= True\n    mask = mask.reshape(w, h)\n    return mask.transpose()  # Put in C order\n\n\ndef area_from_rle(rle: Dict[str, Any]) -> int:\n    return sum(rle["counts"][1::2])\n\n\ndef calculate_stability_score(\n    masks: torch.Tensor, mask_threshold: float, threshold_offset: float\n) -> torch.Tensor:\n    """\n    Computes the stability score for a batch of masks. The stability\n    score is the IoU between the binary masks obtained by thresholding\n    the predicted mask logits at high and low values.\n    """\n    # One mask is always contained inside the other.\n    # Save memory by preventing unnecessary cast to torch.int64\n    intersections = (\n        (masks > (mask_threshold + threshold_offset))\n        .sum(-1, dtype=torch.int16)\n        .sum(-1, dtype=torch.int32)\n    )\n    unions = (\n        (masks > (mask_threshold - threshold_offset))\n        .sum(-1, dtype=torch.int16)\n        .sum(-1, dtype=torch.int32)\n    )\n    return intersections / unions\n\n\ndef build_point_grid(n_per_side: int) -> np.ndarray:\n    """Generates a 2D grid of points evenly spaced in [0,1]x[0,1]."""\n    offset = 1 / (2 * n_per_side)\n    points_one_side = np.linspace(offset, 1 - offset, n_per_side)\n    points_x = np.tile(points_one_side[None, :], (n_per_side, 1))\n    points_y = np.tile(points_one_side[:, None], (1, n_per_side))\n    points = np.stack([points_x, points_y], axis=-1).reshape(-1, 2)\n    return points\n\n\ndef build_all_layer_point_grids(\n    n_per_side: int, n_layers: int, scale_per_layer: int\n) -> List[np.ndarray]:\n    """Generates point grids for all crop layers."""\n    points_by_layer = []\n    for i in range(n_layers + 1):\n        n_points = int(n_per_side / (scale_per_layer**i))\n        points_by_layer.append(build_point_grid(n_points))\n    return points_by_layer\n\n\ndef generate_crop_boxes(\n    im_size: Tuple[int, ...], n_layers: int, overlap_ratio: float\n) -> Tuple[List[List[int]], List[int]]:\n    """\n    Generates a list of crop boxes of different sizes. Each layer\n    has (2**i)**2 boxes for the ith layer.\n    """\n    crop_boxes, layer_idxs = [], []\n    im_h, im_w = im_size\n    short_side = min(im_h, im_w)\n\n    # Original image\n    crop_boxes.append([0, 0, im_w, im_h])\n    layer_idxs.append(0)\n\n    def crop_len(orig_len, n_crops, overlap):\n        return int(math.ceil((overlap * (n_crops - 1) + orig_len) / n_crops))\n\n    for i_layer in range(n_layers):\n        n_crops_per_side = 2 ** (i_layer + 1)\n        overlap = int(overlap_ratio * short_side * (2 / n_crops_per_side))\n\n        crop_w = crop_len(im_w, n_crops_per_side, overlap)\n        crop_h = crop_len(im_h, n_crops_per_side, overlap)\n\n        crop_box_x0 = [int((crop_w - overlap) * i) for i in range(n_crops_per_side)]\n        crop_box_y0 = [int((crop_h - overlap) * i) for i in range(n_crops_per_side)]\n\n        # Crops in XYWH format\n        for x0, y0 in product(crop_box_x0, crop_box_y0):\n            box = [x0, y0, min(x0 + crop_w, im_w), min(y0 + crop_h, im_h)]\n            crop_boxes.append(box)\n            layer_idxs.append(i_layer + 1)\n\n    return crop_boxes, layer_idxs\n\n\ndef uncrop_boxes_xyxy(boxes: torch.Tensor, crop_box: List[int]) -> torch.Tensor:\n    x0, y0, _, _ = crop_box\n    offset = torch.tensor([[x0, y0, x0, y0]], device=boxes.device)\n    # Check if boxes has a channel dimension\n    if len(boxes.shape) == 3:\n        offset = offset.unsqueeze(1)\n    return boxes + offset\n\n\ndef uncrop_points(points: torch.Tensor, crop_box: List[int]) -> torch.Tensor:\n    x0, y0, _, _ = crop_box\n    offset = torch.tensor([[x0, y0]], device=points.device)\n    # Check if points has a channel dimension\n    if len(points.shape) == 3:\n        offset = offset.unsqueeze(1)\n    return points + offset\n\n\ndef uncrop_masks(\n    masks: torch.Tensor, crop_box: List[int], orig_h: int, orig_w: int\n) -> torch.Tensor:\n    x0, y0, x1, y1 = crop_box\n    if x0 == 0 and y0 == 0 and x1 == orig_w and y1 == orig_h:\n        return masks\n    # Coordinate transform masks\n    pad_x, pad_y = orig_w - (x1 - x0), orig_h - (y1 - y0)\n    pad = (x0, pad_x - x0, y0, pad_y - y0)\n    return torch.nn.functional.pad(masks, pad, value=0)\n\n\ndef remove_small_regions(\n    mask: np.ndarray, area_thresh: float, mode: str\n) -> Tuple[np.ndarray, bool]:\n    """\n    Removes small disconnected regions and holes in a mask. Returns the\n    mask and an indicator of if the mask has been modified.\n    """\n    import cv2  # type: ignore\n\n    assert mode in ["holes", "islands"]\n    correct_holes = mode == "holes"\n    working_mask = (correct_holes ^ mask).astype(np.uint8)\n    n_labels, regions, stats, _ = cv2.connectedComponentsWithStats(working_mask, 8)\n    sizes = stats[:, -1][1:]  # Row 0 is background label\n    small_regions = [i + 1 for i, s in enumerate(sizes) if s < area_thresh]\n    if len(small_regions) == 0:\n        return mask, False\n    fill_labels = [0] + small_regions\n    if not correct_holes:\n        fill_labels = [i for i in range(n_labels) if i not in fill_labels]\n        # If every region is below threshold, keep largest\n        if len(fill_labels) == 0:\n            fill_labels = [int(np.argmax(sizes)) + 1]\n    mask = np.isin(regions, fill_labels)\n    return mask, True\n\n\ndef coco_encode_rle(uncompressed_rle: Dict[str, Any]) -> Dict[str, Any]:\n    from pycocotools import mask as mask_utils  # type: ignore\n\n    h, w = uncompressed_rle["size"]\n    rle = mask_utils.frPyObjects(uncompressed_rle, h, w)\n    rle["counts"] = rle["counts"].decode("utf-8")  # Necessary to serialize with json\n    return rle\n\n\ndef batched_mask_to_box(masks: torch.Tensor) -> torch.Tensor:\n    """\n    Calculates boxes in XYXY format around masks. Return [0,0,0,0] for\n    an empty mask. For input shape C1xC2x...xHxW, the output shape is C1xC2x...x4.\n    """\n    # torch.max below raises an error on empty inputs, just skip in this case\n    if torch.numel(masks) == 0:\n        return torch.zeros(*masks.shape[:-2], 4, device=masks.device)\n\n    # Normalize shape to CxHxW\n    shape = masks.shape\n    h, w = shape[-2:]\n    if len(shape) > 2:\n        masks = masks.flatten(0, -3)\n    else:\n        masks = masks.unsqueeze(0)\n\n    # Get top and bottom edges\n    in_height, _ = torch.max(masks, dim=-1)\n    in_height_coords = in_height * torch.arange(h, device=in_height.device)[None, :]\n    bottom_edges, _ = torch.max(in_height_coords, dim=-1)\n    in_height_coords = in_height_coords + h * (~in_height)\n    top_edges, _ = torch.min(in_height_coords, dim=-1)\n\n    # Get left and right edges\n    in_width, _ = torch.max(masks, dim=-2)\n    in_width_coords = in_width * torch.arange(w, device=in_width.device)[None, :]\n    right_edges, _ = torch.max(in_width_coords, dim=-1)\n    in_width_coords = in_width_coords + w * (~in_width)\n    left_edges, _ = torch.min(in_width_coords, dim=-1)\n\n    # If the mask is empty the right edge will be to the left of the left edge.\n    # Replace these boxes with [0, 0, 0, 0]\n    empty_filter = (right_edges < left_edges) | (bottom_edges < top_edges)\n    out = torch.stack([left_edges, top_edges, right_edges, bottom_edges], dim=-1)\n    out = out * (~empty_filter).unsqueeze(-1)\n\n    # Return to original shape\n    if len(shape) > 2:\n        out = out.reshape(*shape[:-2], 4)\n    else:\n        out = out[0]\n\n    return out\n', '_shared_test_resources/code/EdgeTAM/sam2/utils/__init__.py': '# Copyright (c) Meta Platforms, Inc. and affiliates.\n# All rights reserved.\n\n# This source code is licensed under the license found in the\n# LICENSE file in the root directory of this source tree.\n', '_shared_test_resources/code/EdgeTAM/sam2/utils/transforms.py': '# Copyright (c) Meta Platforms, Inc. and affiliates.\n# All rights reserved.\n\n# This source code is licensed under the license found in the\n# LICENSE file in the root directory of this source tree.\n\nimport warnings\n\nimport torch\nimport torch.nn as nn\nimport torch.nn.functional as F\nfrom torchvision.transforms import Normalize, Resize, ToTensor\n\n\nclass SAM2Transforms(nn.Module):\n    def __init__(\n        self, resolution, mask_threshold, max_hole_area=0.0, max_sprinkle_area=0.0\n    ):\n        """\n        Transforms for SAM2.\n        """\n        super().__init__()\n        self.resolution = resolution\n        self.mask_threshold = mask_threshold\n        self.max_hole_area = max_hole_area\n        self.max_sprinkle_area = max_sprinkle_area\n        self.mean = [0.485, 0.456, 0.406]\n        self.std = [0.229, 0.224, 0.225]\n        self.to_tensor = ToTensor()\n        self.transforms = torch.jit.script(\n            nn.Sequential(\n                Resize((self.resolution, self.resolution)),\n                Normalize(self.mean, self.std),\n            )\n        )\n\n    def __call__(self, x):\n        x = self.to_tensor(x)\n        return self.transforms(x)\n\n    def forward_batch(self, img_list):\n        img_batch = [self.transforms(self.to_tensor(img)) for img in img_list]\n        img_batch = torch.stack(img_batch, dim=0)\n        return img_batch\n\n    def transform_coords(\n        self, coords: torch.Tensor, normalize=False, orig_hw=None\n    ) -> torch.Tensor:\n        """\n        Expects a torch tensor with length 2 in the last dimension. The coordinates can be in absolute image or normalized coordinates,\n        If the coords are in absolute image coordinates, normalize should be set to True and original image size is required.\n\n        Returns\n            Un-normalized coordinates in the range of [0, 1] which is expected by the SAM2 model.\n        """\n        if normalize:\n            assert orig_hw is not None\n            h, w = orig_hw\n            coords = coords.clone()\n            coords[..., 0] = coords[..., 0] / w\n            coords[..., 1] = coords[..., 1] / h\n\n        coords = coords * self.resolution  # unnormalize coords\n        return coords\n\n    def transform_boxes(\n        self, boxes: torch.Tensor, normalize=False, orig_hw=None\n    ) -> torch.Tensor:\n        """\n        Expects a tensor of shape Bx4. The coordinates can be in absolute image or normalized coordinates,\n        if the coords are in absolute image coordinates, normalize should be set to True and original image size is required.\n        """\n        boxes = self.transform_coords(boxes.reshape(-1, 2, 2), normalize, orig_hw)\n        return boxes\n\n    def postprocess_masks(self, masks: torch.Tensor, orig_hw) -> torch.Tensor:\n        """\n        Perform PostProcessing on output masks.\n        """\n        from sam2.utils.misc import get_connected_components\n\n        masks = masks.float()\n        input_masks = masks\n        mask_flat = masks.flatten(0, 1).unsqueeze(1)  # flatten as 1-channel image\n        try:\n            if self.max_hole_area > 0:\n                # Holes are those connected components in background with area <= self.fill_hole_area\n                # (background regions are those with mask scores <= self.mask_threshold)\n                labels, areas = get_connected_components(\n                    mask_flat <= self.mask_threshold\n                )\n                is_hole = (labels > 0) & (areas <= self.max_hole_area)\n                is_hole = is_hole.reshape_as(masks)\n                # We fill holes with a small positive mask score (10.0) to change them to foreground.\n                masks = torch.where(is_hole, self.mask_threshold + 10.0, masks)\n\n            if self.max_sprinkle_area > 0:\n                labels, areas = get_connected_components(\n                    mask_flat > self.mask_threshold\n                )\n                is_hole = (labels > 0) & (areas <= self.max_sprinkle_area)\n                is_hole = is_hole.reshape_as(masks)\n                # We fill holes with negative mask score (-10.0) to change them to background.\n                masks = torch.where(is_hole, self.mask_threshold - 10.0, masks)\n        except Exception as e:\n            # Skip the post-processing step if the CUDA kernel fails\n            warnings.warn(\n                f"{e}\\n\\nSkipping the post-processing step due to the error above. You can "\n                "still use SAM 2 and it\'s OK to ignore the error above, although some post-processing "\n                "functionality may be limited (which doesn\'t affect the results in most cases; see "\n                "https://github.com/facebookresearch/sam2/blob/main/INSTALL.md).",\n                category=UserWarning,\n                stacklevel=2,\n            )\n            masks = input_masks\n\n        masks = F.interpolate(masks, orig_hw, mode="bilinear", align_corners=False)\n        return masks\n', '_shared_test_resources/code/EdgeTAM/sam2/utils/misc.py': '# Copyright (c) Meta Platforms, Inc. and affiliates.\n# All rights reserved.\n\n# This source code is licensed under the license found in the\n# LICENSE file in the root directory of this source tree.\n\nimport os\nimport warnings\nfrom threading import Thread\n\nimport numpy as np\nimport torch\nfrom PIL import Image\nfrom tqdm import tqdm\n\n\ndef get_sdpa_settings():\n    if torch.cuda.is_available():\n        old_gpu = torch.cuda.get_device_properties(0).major < 7\n        # only use Flash Attention on Ampere (8.0) or newer GPUs\n        use_flash_attn = torch.cuda.get_device_properties(0).major >= 8\n        if not use_flash_attn:\n            warnings.warn(\n                "Flash Attention is disabled as it requires a GPU with Ampere (8.0) CUDA capability.",\n                category=UserWarning,\n                stacklevel=2,\n            )\n        # keep math kernel for PyTorch versions before 2.2 (Flash Attention v2 is only\n        # available on PyTorch 2.2+, while Flash Attention v1 cannot handle all cases)\n        pytorch_version = tuple(int(v) for v in torch.__version__.split(".")[:2])\n        if pytorch_version < (2, 2):\n            warnings.warn(\n                f"You are using PyTorch {torch.__version__} without Flash Attention v2 support. "\n                "Consider upgrading to PyTorch 2.2+ for Flash Attention v2 (which could be faster).",\n                category=UserWarning,\n                stacklevel=2,\n            )\n        math_kernel_on = pytorch_version < (2, 2) or not use_flash_attn\n    else:\n        old_gpu = True\n        use_flash_attn = False\n        math_kernel_on = True\n\n    return old_gpu, use_flash_attn, math_kernel_on\n\n\ndef get_connected_components(mask):\n    """\n    Get the connected components (8-connectivity) of binary masks of shape (N, 1, H, W).\n\n    Inputs:\n    - mask: A binary mask tensor of shape (N, 1, H, W), where 1 is foreground and 0 is\n            background.\n\n    Outputs:\n    - labels: A tensor of shape (N, 1, H, W) containing the connected component labels\n              for foreground pixels and 0 for background pixels.\n    - counts: A tensor of shape (N, 1, H, W) containing the area of the connected\n              components for foreground pixels and 0 for background pixels.\n    """\n    from sam2 import _C\n\n    return _C.get_connected_componnets(mask.to(torch.uint8).contiguous())\n\n\ndef mask_to_box(masks: torch.Tensor):\n    """\n    compute bounding box given an input mask\n\n    Inputs:\n    - masks: [B, 1, H, W] masks, dtype=torch.Tensor\n\n    Returns:\n    - box_coords: [B, 1, 4], contains (x, y) coordinates of top left and bottom right box corners, dtype=torch.Tensor\n    """\n    B, _, h, w = masks.shape\n    device = masks.device\n    xs = torch.arange(w, device=device, dtype=torch.int32)\n    ys = torch.arange(h, device=device, dtype=torch.int32)\n    grid_xs, grid_ys = torch.meshgrid(xs, ys, indexing="xy")\n    grid_xs = grid_xs[None, None, ...].expand(B, 1, h, w)\n    grid_ys = grid_ys[None, None, ...].expand(B, 1, h, w)\n    min_xs, _ = torch.min(torch.where(masks, grid_xs, w).flatten(-2), dim=-1)\n    max_xs, _ = torch.max(torch.where(masks, grid_xs, -1).flatten(-2), dim=-1)\n    min_ys, _ = torch.min(torch.where(masks, grid_ys, h).flatten(-2), dim=-1)\n    max_ys, _ = torch.max(torch.where(masks, grid_ys, -1).flatten(-2), dim=-1)\n    bbox_coords = torch.stack((min_xs, min_ys, max_xs, max_ys), dim=-1)\n\n    return bbox_coords\n\n\ndef _load_img_as_tensor(img_path, image_size):\n    img_pil = Image.open(img_path)\n    img_np = np.array(img_pil.convert("RGB").resize((image_size, image_size)))\n    if img_np.dtype == np.uint8:  # np.uint8 is expected for JPEG images\n        img_np = img_np / 255.0\n    else:\n        raise RuntimeError(f"Unknown image dtype: {img_np.dtype} on {img_path}")\n    img = torch.from_numpy(img_np).permute(2, 0, 1)\n    video_width, video_height = img_pil.size  # the original video size\n    return img, video_height, video_width\n\n\nclass AsyncVideoFrameLoader:\n    """\n    A list of video frames to be load asynchronously without blocking session start.\n    """\n\n    def __init__(\n        self,\n        img_paths,\n        image_size,\n        offload_video_to_cpu,\n        img_mean,\n        img_std,\n        compute_device,\n    ):\n        self.img_paths = img_paths\n        self.image_size = image_size\n        self.offload_video_to_cpu = offload_video_to_cpu\n        self.img_mean = img_mean\n        self.img_std = img_std\n        # items in `self.images` will be loaded asynchronously\n        self.images = [None] * len(img_paths)\n        # catch and raise any exceptions in the async loading thread\n        self.exception = None\n        # video_height and video_width be filled when loading the first image\n        self.video_height = None\n        self.video_width = None\n        self.compute_device = compute_device\n\n        # load the first frame to fill video_height and video_width and also\n        # to cache it (since it\'s most likely where the user will click)\n        self.__getitem__(0)\n\n        # load the rest of frames asynchronously without blocking the session start\n        def _load_frames():\n            try:\n                for n in tqdm(range(len(self.images)), desc="frame loading (JPEG)"):\n                    self.__getitem__(n)\n            except Exception as e:\n                self.exception = e\n\n        self.thread = Thread(target=_load_frames, daemon=True)\n        self.thread.start()\n\n    def __getitem__(self, index):\n        if self.exception is not None:\n            raise RuntimeError("Failure in frame loading thread") from self.exception\n\n        img = self.images[index]\n        if img is not None:\n            return img\n\n        img, video_height, video_width = _load_img_as_tensor(\n            self.img_paths[index], self.image_size\n        )\n        self.video_height = video_height\n        self.video_width = video_width\n        # normalize by mean and std\n        img -= self.img_mean\n        img /= self.img_std\n        if not self.offload_video_to_cpu:\n            img = img.to(self.compute_device, non_blocking=True)\n        self.images[index] = img\n        return img\n\n    def __len__(self):\n        return len(self.images)\n\n\ndef load_video_frames(\n    video_path,\n    image_size,\n    offload_video_to_cpu,\n    img_mean=(0.485, 0.456, 0.406),\n    img_std=(0.229, 0.224, 0.225),\n    async_loading_frames=False,\n    compute_device=torch.device("cuda"),\n):\n    """\n    Load the video frames from video_path. The frames are resized to image_size as in\n    the model and are loaded to GPU if offload_video_to_cpu=False. This is used by the demo.\n    """\n    is_bytes = isinstance(video_path, bytes)\n    is_str = isinstance(video_path, str)\n    is_mp4_path = is_str and os.path.splitext(video_path)[-1] in [".mp4", ".MP4"]\n    if is_bytes or is_mp4_path:\n        return load_video_frames_from_video_file(\n            video_path=video_path,\n            image_size=image_size,\n            offload_video_to_cpu=offload_video_to_cpu,\n            img_mean=img_mean,\n            img_std=img_std,\n            compute_device=compute_device,\n        )\n    elif is_str and os.path.isdir(video_path):\n        return load_video_frames_from_jpg_images(\n            video_path=video_path,\n            image_size=image_size,\n            offload_video_to_cpu=offload_video_to_cpu,\n            img_mean=img_mean,\n            img_std=img_std,\n            async_loading_frames=async_loading_frames,\n            compute_device=compute_device,\n        )\n    else:\n        raise NotImplementedError(\n            "Only MP4 video and JPEG folder are supported at this moment"\n        )\n\n\ndef load_video_frames_from_jpg_images(\n    video_path,\n    image_size,\n    offload_video_to_cpu,\n    img_mean=(0.485, 0.456, 0.406),\n    img_std=(0.229, 0.224, 0.225),\n    async_loading_frames=False,\n    compute_device=torch.device("cuda"),\n):\n    """\n    Load the video frames from a directory of JPEG files ("<frame_index>.jpg" format).\n\n    The frames are resized to image_size x image_size and are loaded to GPU if\n    `offload_video_to_cpu` is `False` and to CPU if `offload_video_to_cpu` is `True`.\n\n    You can load a frame asynchronously by setting `async_loading_frames` to `True`.\n    """\n    if isinstance(video_path, str) and os.path.isdir(video_path):\n        jpg_folder = video_path\n    else:\n        raise NotImplementedError(\n            "Only JPEG frames are supported at this moment. For video files, you may use "\n            "ffmpeg (https://ffmpeg.org/) to extract frames into a folder of JPEG files, such as \\n"\n            "```\\n"\n            "ffmpeg -i <your_video>.mp4 -q:v 2 -start_number 0 <output_dir>/\'%05d.jpg\'\\n"\n            "```\\n"\n            "where `-q:v` generates high-quality JPEG frames and `-start_number 0` asks "\n            "ffmpeg to start the JPEG file from 00000.jpg."\n        )\n\n    frame_names = [\n        p\n        for p in os.listdir(jpg_folder)\n        if os.path.splitext(p)[-1] in [".jpg", ".jpeg", ".JPG", ".JPEG"]\n    ]\n    frame_names.sort(key=lambda p: int(os.path.splitext(p)[0]))\n    num_frames = len(frame_names)\n    if num_frames == 0:\n        raise RuntimeError(f"no images found in {jpg_folder}")\n    img_paths = [os.path.join(jpg_folder, frame_name) for frame_name in frame_names]\n    img_mean = torch.tensor(img_mean, dtype=torch.float32)[:, None, None]\n    img_std = torch.tensor(img_std, dtype=torch.float32)[:, None, None]\n\n    if async_loading_frames:\n        lazy_images = AsyncVideoFrameLoader(\n            img_paths,\n            image_size,\n            offload_video_to_cpu,\n            img_mean,\n            img_std,\n            compute_device,\n        )\n        return lazy_images, lazy_images.video_height, lazy_images.video_width\n\n    images = torch.zeros(num_frames, 3, image_size, image_size, dtype=torch.float32)\n    for n, img_path in enumerate(tqdm(img_paths, desc="frame loading (JPEG)")):\n        images[n], video_height, video_width = _load_img_as_tensor(img_path, image_size)\n    if not offload_video_to_cpu:\n        images = images.to(compute_device)\n        img_mean = img_mean.to(compute_device)\n        img_std = img_std.to(compute_device)\n    # normalize by mean and std\n    images -= img_mean\n    images /= img_std\n    return images, video_height, video_width\n\n\ndef load_video_frames_from_video_file(\n    video_path,\n    image_size,\n    offload_video_to_cpu,\n    img_mean=(0.485, 0.456, 0.406),\n    img_std=(0.229, 0.224, 0.225),\n    compute_device=torch.device("cuda"),\n):\n    """Load the video frames from a video file."""\n    import decord\n\n    img_mean = torch.tensor(img_mean, dtype=torch.float32)[:, None, None]\n    img_std = torch.tensor(img_std, dtype=torch.float32)[:, None, None]\n    # Get the original video height and width\n    decord.bridge.set_bridge("torch")\n    video_height, video_width, _ = decord.VideoReader(video_path).next().shape\n    # Iterate over all frames in the video\n    images = []\n    for frame in decord.VideoReader(video_path, width=image_size, height=image_size):\n        images.append(frame.permute(2, 0, 1))\n\n    images = torch.stack(images, dim=0).float() / 255.0\n    if not offload_video_to_cpu:\n        images = images.to(compute_device)\n        img_mean = img_mean.to(compute_device)\n        img_std = img_std.to(compute_device)\n    # normalize by mean and std\n    images -= img_mean\n    images /= img_std\n    return images, video_height, video_width\n\n\ndef fill_holes_in_mask_scores(mask, max_area):\n    """\n    A post processor to fill small holes in mask scores with area under `max_area`.\n    """\n    # Holes are those connected components in background with area <= self.max_area\n    # (background regions are those with mask scores <= 0)\n    assert max_area > 0, "max_area must be positive"\n\n    input_mask = mask\n    try:\n        labels, areas = get_connected_components(mask <= 0)\n        is_hole = (labels > 0) & (areas <= max_area)\n        # We fill holes with a small positive mask score (0.1) to change them to foreground.\n        mask = torch.where(is_hole, 0.1, mask)\n    except Exception as e:\n        # Skip the post-processing step on removing small holes if the CUDA kernel fails\n        warnings.warn(\n            f"{e}\\n\\nSkipping the post-processing step due to the error above. You can "\n            "still use SAM 2 and it\'s OK to ignore the error above, although some post-processing "\n            "functionality may be limited (which doesn\'t affect the results in most cases; see "\n            "https://github.com/facebookresearch/sam2/blob/main/INSTALL.md).",\n            category=UserWarning,\n            stacklevel=2,\n        )\n        mask = input_mask\n\n    return mask\n\n\ndef concat_points(old_point_inputs, new_points, new_labels):\n    """Add new points and labels to previous point inputs (add at the end)."""\n    if old_point_inputs is None:\n        points, labels = new_points, new_labels\n    else:\n        points = torch.cat([old_point_inputs["point_coords"], new_points], dim=1)\n        labels = torch.cat([old_point_inputs["point_labels"], new_labels], dim=1)\n\n    return {"point_coords": points, "point_labels": labels}\n', '_shared_test_resources/code/EdgeTAM/sam2/csrc/connected_components.cu': '// Copyright (c) Meta Platforms, Inc. and affiliates.\n// All rights reserved.\n\n// This source code is licensed under the license found in the\n// LICENSE file in the root directory of this source tree.\n\n// adapted from https://github.com/zsef123/Connected_components_PyTorch\n// with license found in the LICENSE_cctorch file in the root directory.\n#include <ATen/cuda/CUDAContext.h>\n#include <cuda.h>\n#include <cuda_runtime.h>\n#include <torch/extension.h>\n#include <torch/script.h>\n#include <vector>\n\n// 2d\n#define BLOCK_ROWS 16\n#define BLOCK_COLS 16\n\nnamespace cc2d {\n\ntemplate <typename T>\n__device__ __forceinline__ unsigned char hasBit(T bitmap, unsigned char pos) {\n  return (bitmap >> pos) & 1;\n}\n\n__device__ int32_t find(const int32_t* s_buf, int32_t n) {\n  while (s_buf[n] != n)\n    n = s_buf[n];\n  return n;\n}\n\n__device__ int32_t find_n_compress(int32_t* s_buf, int32_t n) {\n  const int32_t id = n;\n  while (s_buf[n] != n) {\n    n = s_buf[n];\n    s_buf[id] = n;\n  }\n  return n;\n}\n\n__device__ void union_(int32_t* s_buf, int32_t a, int32_t b) {\n  bool done;\n  do {\n    a = find(s_buf, a);\n    b = find(s_buf, b);\n\n    if (a < b) {\n      int32_t old = atomicMin(s_buf + b, a);\n      done = (old == b);\n      b = old;\n    } else if (b < a) {\n      int32_t old = atomicMin(s_buf + a, b);\n      done = (old == a);\n      a = old;\n    } else\n      done = true;\n\n  } while (!done);\n}\n\n__global__ void\ninit_labeling(int32_t* label, const uint32_t W, const uint32_t H) {\n  const uint32_t row = (blockIdx.y * blockDim.y + threadIdx.y) * 2;\n  const uint32_t col = (blockIdx.x * blockDim.x + threadIdx.x) * 2;\n  const uint32_t idx = row * W + col;\n\n  if (row < H && col < W)\n    label[idx] = idx;\n}\n\n__global__ void\nmerge(uint8_t* img, int32_t* label, const uint32_t W, const uint32_t H) {\n  const uint32_t row = (blockIdx.y * blockDim.y + threadIdx.y) * 2;\n  const uint32_t col = (blockIdx.x * blockDim.x + threadIdx.x) * 2;\n  const uint32_t idx = row * W + col;\n\n  if (row >= H || col >= W)\n    return;\n\n  uint32_t P = 0;\n\n  if (img[idx])\n    P |= 0x777;\n  if (row + 1 < H && img[idx + W])\n    P |= 0x777 << 4;\n  if (col + 1 < W && img[idx + 1])\n    P |= 0x777 << 1;\n\n  if (col == 0)\n    P &= 0xEEEE;\n  if (col + 1 >= W)\n    P &= 0x3333;\n  else if (col + 2 >= W)\n    P &= 0x7777;\n\n  if (row == 0)\n    P &= 0xFFF0;\n  if (row + 1 >= H)\n    P &= 0xFF;\n\n  if (P > 0) {\n    // If need check about top-left pixel(if flag the first bit) and hit the\n    // top-left pixel\n    if (hasBit(P, 0) && img[idx - W - 1]) {\n      union_(label, idx, idx - 2 * W - 2); // top left block\n    }\n\n    if ((hasBit(P, 1) && img[idx - W]) || (hasBit(P, 2) && img[idx - W + 1]))\n      union_(label, idx, idx - 2 * W); // top bottom block\n\n    if (hasBit(P, 3) && img[idx + 2 - W])\n      union_(label, idx, idx - 2 * W + 2); // top right block\n\n    if ((hasBit(P, 4) && img[idx - 1]) || (hasBit(P, 8) && img[idx + W - 1]))\n      union_(label, idx, idx - 2); // just left block\n  }\n}\n\n__global__ void compression(int32_t* label, const int32_t W, const int32_t H) {\n  const uint32_t row = (blockIdx.y * blockDim.y + threadIdx.y) * 2;\n  const uint32_t col = (blockIdx.x * blockDim.x + threadIdx.x) * 2;\n  const uint32_t idx = row * W + col;\n\n  if (row < H && col < W)\n    find_n_compress(label, idx);\n}\n\n__global__ void final_labeling(\n    const uint8_t* img,\n    int32_t* label,\n    const int32_t W,\n    const int32_t H) {\n  const uint32_t row = (blockIdx.y * blockDim.y + threadIdx.y) * 2;\n  const uint32_t col = (blockIdx.x * blockDim.x + threadIdx.x) * 2;\n  const uint32_t idx = row * W + col;\n\n  if (row >= H || col >= W)\n    return;\n\n  int32_t y = label[idx] + 1;\n\n  if (img[idx])\n    label[idx] = y;\n  else\n    label[idx] = 0;\n\n  if (col + 1 < W) {\n    if (img[idx + 1])\n      label[idx + 1] = y;\n    else\n      label[idx + 1] = 0;\n\n    if (row + 1 < H) {\n      if (img[idx + W + 1])\n        label[idx + W + 1] = y;\n      else\n        label[idx + W + 1] = 0;\n    }\n  }\n\n  if (row + 1 < H) {\n    if (img[idx + W])\n      label[idx + W] = y;\n    else\n      label[idx + W] = 0;\n  }\n}\n\n__global__ void init_counting(\n    const int32_t* label,\n    int32_t* count_init,\n    const int32_t W,\n    const int32_t H) {\n  const uint32_t row = (blockIdx.y * blockDim.y + threadIdx.y);\n  const uint32_t col = (blockIdx.x * blockDim.x + threadIdx.x);\n  const uint32_t idx = row * W + col;\n\n  if (row >= H || col >= W)\n    return;\n\n  int32_t y = label[idx];\n  if (y > 0) {\n    int32_t count_idx = y - 1;\n    atomicAdd(count_init + count_idx, 1);\n  }\n}\n\n__global__ void final_counting(\n    const int32_t* label,\n    const int32_t* count_init,\n    int32_t* count_final,\n    const int32_t W,\n    const int32_t H) {\n  const uint32_t row = (blockIdx.y * blockDim.y + threadIdx.y);\n  const uint32_t col = (blockIdx.x * blockDim.x + threadIdx.x);\n  const uint32_t idx = row * W + col;\n\n  if (row >= H || col >= W)\n    return;\n\n  int32_t y = label[idx];\n  if (y > 0) {\n    int32_t count_idx = y - 1;\n    count_final[idx] = count_init[count_idx];\n  } else {\n    count_final[idx] = 0;\n  }\n}\n\n} // namespace cc2d\n\nstd::vector<torch::Tensor> get_connected_componnets(\n    const torch::Tensor& inputs) {\n  AT_ASSERTM(inputs.is_cuda(), "inputs must be a CUDA tensor");\n  AT_ASSERTM(inputs.ndimension() == 4, "inputs must be [N, 1, H, W] shape");\n  AT_ASSERTM(\n      inputs.scalar_type() == torch::kUInt8, "inputs must be a uint8 type");\n\n  const uint32_t N = inputs.size(0);\n  const uint32_t C = inputs.size(1);\n  const uint32_t H = inputs.size(2);\n  const uint32_t W = inputs.size(3);\n\n  AT_ASSERTM(C == 1, "inputs must be [N, 1, H, W] shape");\n  AT_ASSERTM((H % 2) == 0, "height must be an even number");\n  AT_ASSERTM((W % 2) == 0, "width must be an even number");\n\n  // label must be uint32_t\n  auto label_options =\n      torch::TensorOptions().dtype(torch::kInt32).device(inputs.device());\n  torch::Tensor labels = torch::zeros({N, C, H, W}, label_options);\n  torch::Tensor counts_init = torch::zeros({N, C, H, W}, label_options);\n  torch::Tensor counts_final = torch::zeros({N, C, H, W}, label_options);\n\n  dim3 grid = dim3(\n      ((W + 1) / 2 + BLOCK_COLS - 1) / BLOCK_COLS,\n      ((H + 1) / 2 + BLOCK_ROWS - 1) / BLOCK_ROWS);\n  dim3 block = dim3(BLOCK_COLS, BLOCK_ROWS);\n  dim3 grid_count =\n      dim3((W + BLOCK_COLS) / BLOCK_COLS, (H + BLOCK_ROWS) / BLOCK_ROWS);\n  dim3 block_count = dim3(BLOCK_COLS, BLOCK_ROWS);\n  cudaStream_t stream = at::cuda::getCurrentCUDAStream();\n\n  for (int n = 0; n < N; n++) {\n    uint32_t offset = n * H * W;\n\n    cc2d::init_labeling<<<grid, block, 0, stream>>>(\n        labels.data_ptr<int32_t>() + offset, W, H);\n    cc2d::merge<<<grid, block, 0, stream>>>(\n        inputs.data_ptr<uint8_t>() + offset,\n        labels.data_ptr<int32_t>() + offset,\n        W,\n        H);\n    cc2d::compression<<<grid, block, 0, stream>>>(\n        labels.data_ptr<int32_t>() + offset, W, H);\n    cc2d::final_labeling<<<grid, block, 0, stream>>>(\n        inputs.data_ptr<uint8_t>() + offset,\n        labels.data_ptr<int32_t>() + offset,\n        W,\n        H);\n\n    // get the counting of each pixel\n    cc2d::init_counting<<<grid_count, block_count, 0, stream>>>(\n        labels.data_ptr<int32_t>() + offset,\n        counts_init.data_ptr<int32_t>() + offset,\n        W,\n        H);\n    cc2d::final_counting<<<grid_count, block_count, 0, stream>>>(\n        labels.data_ptr<int32_t>() + offset,\n        counts_init.data_ptr<int32_t>() + offset,\n        counts_final.data_ptr<int32_t>() + offset,\n        W,\n        H);\n  }\n\n  // returned values are [labels, counts]\n  std::vector<torch::Tensor> outputs;\n  outputs.push_back(labels);\n  outputs.push_back(counts_final);\n  return outputs;\n}\n\nPYBIND11_MODULE(TORCH_EXTENSION_NAME, m) {\n  m.def(\n      "get_connected_componnets",\n      &get_connected_componnets,\n      "get_connected_componnets");\n}\n', '_shared_test_resources/code/EdgeTAM/sam2/modeling/memory_attention.py': '# Copyright (c) Meta Platforms, Inc. and affiliates.\n# All rights reserved.\n\n# This source code is licensed under the license found in the\n# LICENSE file in the root directory of this source tree.\n\nfrom typing import Optional\n\nimport torch\n\nfrom sam2.modeling.sam.transformer import RoPEAttention, RoPEAttentionv2\n\nfrom sam2.modeling.sam2_utils import get_activation_fn, get_clones\nfrom torch import nn, Tensor\n\n\nclass MemoryAttentionLayer(nn.Module):\n\n    def __init__(\n        self,\n        activation: str,\n        cross_attention: nn.Module,\n        d_model: int,\n        dim_feedforward: int,\n        dropout: float,\n        pos_enc_at_attn: bool,\n        pos_enc_at_cross_attn_keys: bool,\n        pos_enc_at_cross_attn_queries: bool,\n        self_attention: nn.Module,\n    ):\n        super().__init__()\n        self.d_model = d_model\n        self.dim_feedforward = dim_feedforward\n        self.dropout_value = dropout\n        self.self_attn = self_attention\n        self.cross_attn_image = cross_attention\n\n        # Implementation of Feedforward model\n        self.linear1 = nn.Linear(d_model, dim_feedforward)\n        self.dropout = nn.Dropout(dropout)\n        self.linear2 = nn.Linear(dim_feedforward, d_model)\n\n        self.norm1 = nn.LayerNorm(d_model)\n        self.norm2 = nn.LayerNorm(d_model)\n        self.norm3 = nn.LayerNorm(d_model)\n        self.dropout1 = nn.Dropout(dropout)\n        self.dropout2 = nn.Dropout(dropout)\n        self.dropout3 = nn.Dropout(dropout)\n\n        self.activation_str = activation\n        self.activation = get_activation_fn(activation)\n\n        # Where to add pos enc\n        self.pos_enc_at_attn = pos_enc_at_attn\n        self.pos_enc_at_cross_attn_queries = pos_enc_at_cross_attn_queries\n        self.pos_enc_at_cross_attn_keys = pos_enc_at_cross_attn_keys\n\n    def _forward_sa(self, tgt, query_pos):\n        # Self-Attention\n        tgt2 = self.norm1(tgt)\n        q = k = tgt2 + query_pos if self.pos_enc_at_attn else tgt2\n        tgt2 = self.self_attn(q, k, v=tgt2)\n        tgt = tgt + self.dropout1(tgt2)\n        return tgt\n\n    def _forward_ca(\n        self, tgt, memory, query_pos, pos, num_k_exclude_rope=0, rope_k_repeat=-1\n    ):\n        kwds = {}\n        if rope_k_repeat >= 0:\n            assert isinstance(self.cross_attn_image, RoPEAttentionv2)\n            kwds["num_k_exclude_rope"] = num_k_exclude_rope\n            kwds["rope_k_repeat"] = rope_k_repeat\n        elif num_k_exclude_rope > 0:\n            assert isinstance(self.cross_attn_image, RoPEAttention)\n            kwds = {"num_k_exclude_rope": num_k_exclude_rope}\n\n        # Cross-Attention\n        tgt2 = self.norm2(tgt)\n        tgt2 = self.cross_attn_image(\n            q=tgt2 + query_pos if self.pos_enc_at_cross_attn_queries else tgt2,\n            k=memory + pos if self.pos_enc_at_cross_attn_keys else memory,\n            v=memory,\n            **kwds,\n        )\n        tgt = tgt + self.dropout2(tgt2)\n        return tgt\n\n    def forward(\n        self,\n        tgt,\n        memory,\n        pos: Optional[Tensor] = None,\n        query_pos: Optional[Tensor] = None,\n        num_k_exclude_rope: int = 0,\n        rope_k_repeat: int = -1,\n    ) -> torch.Tensor:\n\n        # Self-Attn, Cross-Attn\n        tgt = self._forward_sa(tgt, query_pos)\n        tgt = self._forward_ca(\n            tgt, memory, query_pos, pos, num_k_exclude_rope, rope_k_repeat\n        )\n        # MLP\n        tgt2 = self.norm3(tgt)\n        tgt2 = self.linear2(self.dropout(self.activation(self.linear1(tgt2))))\n        tgt = tgt + self.dropout3(tgt2)\n        return tgt\n\n\nclass MemoryAttention(nn.Module):\n    def __init__(\n        self,\n        d_model: int,\n        pos_enc_at_input: bool,\n        layer: nn.Module,\n        num_layers: int,\n        batch_first: bool = True,  # Do layers expect batch first input?\n    ):\n        super().__init__()\n        self.d_model = d_model\n        self.layers = get_clones(layer, num_layers)\n        self.num_layers = num_layers\n        self.norm = nn.LayerNorm(d_model)\n        self.pos_enc_at_input = pos_enc_at_input\n        self.batch_first = batch_first\n\n    def forward(\n        self,\n        curr: torch.Tensor,  # self-attention inputs\n        memory: torch.Tensor,  # cross-attention inputs\n        curr_pos: Optional[Tensor] = None,  # pos_enc for self-attention inputs\n        memory_pos: Optional[Tensor] = None,  # pos_enc for cross-attention inputs\n        num_obj_ptr_tokens: int = 0,  # number of object pointer *tokens*\n        num_spatial_mem: int = -1,  # number of spatial memory embeddings\n    ):\n        if isinstance(curr, list):\n            assert isinstance(curr_pos, list)\n            assert len(curr) == len(curr_pos) == 1\n            curr, curr_pos = (\n                curr[0],\n                curr_pos[0],\n            )\n\n        assert (\n            curr.shape[1] == memory.shape[1]\n        ), "Batch size must be the same for curr and memory"\n\n        output = curr\n        if self.pos_enc_at_input and curr_pos is not None:\n            output = output + 0.1 * curr_pos\n\n        if self.batch_first:\n            # Convert to batch first\n            output = output.transpose(0, 1)\n            curr_pos = curr_pos.transpose(0, 1)\n            memory = memory.transpose(0, 1)\n            memory_pos = memory_pos.transpose(0, 1)\n\n        for layer in self.layers:\n            kwds = {}\n            if isinstance(layer.cross_attn_image, RoPEAttention):\n                kwds = {"num_k_exclude_rope": num_obj_ptr_tokens}\n            if isinstance(layer.cross_attn_image, RoPEAttentionv2):\n                kwds["num_k_exclude_rope"] = num_obj_ptr_tokens\n                kwds["rope_k_repeat"] = num_spatial_mem\n\n            output = layer(\n                tgt=output,\n                memory=memory,\n                pos=memory_pos,\n                query_pos=curr_pos,\n                **kwds,\n            )\n        normed_output = self.norm(output)\n\n        if self.batch_first:\n            # Convert back to seq first\n            normed_output = normed_output.transpose(0, 1)\n            curr_pos = curr_pos.transpose(0, 1)\n\n        return normed_output\n', '_shared_test_resources/code/EdgeTAM/sam2/modeling/sam2_base.py': '# Copyright (c) Meta Platforms, Inc. and affiliates.\n# All rights reserved.\n\n# This source code is licensed under the license found in the\n# LICENSE file in the root directory of this source tree.\n\nimport torch\nimport torch.distributed\nimport torch.nn.functional as F\n\nfrom sam2.modeling.sam.mask_decoder import MaskDecoder\nfrom sam2.modeling.sam.prompt_encoder import PromptEncoder\nfrom sam2.modeling.sam.transformer import TwoWayTransformer\nfrom sam2.modeling.sam2_utils import get_1d_sine_pe, MLP, select_closest_cond_frames\n\nfrom torch.nn.init import trunc_normal_\n\n# a large negative value as a placeholder score for missing objects\nNO_OBJ_SCORE = -1024.0\n\n\nclass SAM2Base(torch.nn.Module):\n    def __init__(\n        self,\n        image_encoder,\n        memory_attention,\n        memory_encoder,\n        num_maskmem=7,  # default 1 input frame + 6 previous frames\n        image_size=512,\n        backbone_stride=16,  # stride of the image backbone output\n        sigmoid_scale_for_mem_enc=1.0,  # scale factor for mask sigmoid prob\n        sigmoid_bias_for_mem_enc=0.0,  # bias factor for mask sigmoid prob\n        # During evaluation, whether to binarize the sigmoid mask logits on interacted frames with clicks\n        binarize_mask_from_pts_for_mem_enc=False,\n        use_mask_input_as_output_without_sam=False,  # on frames with mask input, whether to directly output the input mask without using a SAM prompt encoder + mask decoder\n        # The maximum number of conditioning frames to participate in the memory attention (-1 means no limit; if there are more conditioning frames than this limit,\n        # we only cross-attend to the temporally closest `max_cond_frames_in_attn` conditioning frames in the encoder when tracking each frame). This gives the model\n        # a temporal locality when handling a large number of annotated frames (since closer frames should be more important) and also avoids GPU OOM.\n        max_cond_frames_in_attn=-1,\n        # on the first frame, whether to directly add the no-memory embedding to the image feature\n        # (instead of using the transformer encoder)\n        directly_add_no_mem_embed=False,\n        # whether to use high-resolution feature maps in the SAM mask decoder\n        use_high_res_features_in_sam=False,\n        # whether to output multiple (3) masks for the first click on initial conditioning frames\n        multimask_output_in_sam=False,\n        # the minimum and maximum number of clicks to use multimask_output_in_sam (only relevant when `multimask_output_in_sam=True`;\n        # default is 1 for both, meaning that only the first click gives multimask output; also note that a box counts as two points)\n        multimask_min_pt_num=1,\n        multimask_max_pt_num=1,\n        # whether to also use multimask output for tracking (not just for the first click on initial conditioning frames; only relevant when `multimask_output_in_sam=True`)\n        multimask_output_for_tracking=False,\n        # Whether to use multimask tokens for obj ptr; Only relevant when both\n        # use_obj_ptrs_in_encoder=True and multimask_output_for_tracking=True\n        use_multimask_token_for_obj_ptr: bool = False,\n        # whether to use sigmoid to restrict ious prediction to [0-1]\n        iou_prediction_use_sigmoid=False,\n        # The memory bank\'s temporal stride during evaluation (i.e. the `r` parameter in XMem and Cutie; XMem and Cutie use r=5).\n        # For r>1, the (self.num_maskmem - 1) non-conditioning memory frames consist of\n        # (self.num_maskmem - 2) nearest frames from every r-th frames, plus the last frame.\n        memory_temporal_stride_for_eval=1,\n        # whether to apply non-overlapping constraints on the object masks in the memory encoder during evaluation (to avoid/alleviate superposing masks)\n        non_overlap_masks_for_mem_enc=False,\n        # whether to cross-attend to object pointers from other frames (based on SAM output tokens) in the encoder\n        use_obj_ptrs_in_encoder=False,\n        # the maximum number of object pointers from other frames in encoder cross attention (only relevant when `use_obj_ptrs_in_encoder=True`)\n        max_obj_ptrs_in_encoder=16,\n        # whether to add temporal positional encoding to the object pointers in the encoder (only relevant when `use_obj_ptrs_in_encoder=True`)\n        add_tpos_enc_to_obj_ptrs=True,\n        # whether to add an extra linear projection layer for the temporal positional encoding in the object pointers to avoid potential interference\n        # with spatial positional encoding (only relevant when both `use_obj_ptrs_in_encoder=True` and `add_tpos_enc_to_obj_ptrs=True`)\n        proj_tpos_enc_in_obj_ptrs=False,\n        # whether to use signed distance (instead of unsigned absolute distance) in the temporal positional encoding in the object pointers\n        # (only relevant when both `use_obj_ptrs_in_encoder=True` and `add_tpos_enc_to_obj_ptrs=True`)\n        use_signed_tpos_enc_to_obj_ptrs=False,\n        # whether to only attend to object pointers in the past (before the current frame) in the encoder during evaluation\n        # (only relevant when `use_obj_ptrs_in_encoder=True`; this might avoid pointer information too far in the future to distract the initial tracking)\n        only_obj_ptrs_in_the_past_for_eval=False,\n        # Whether to predict if there is an object in the frame\n        pred_obj_scores: bool = False,\n        # Whether to use an MLP to predict object scores\n        pred_obj_scores_mlp: bool = False,\n        # Only relevant if pred_obj_scores=True and use_obj_ptrs_in_encoder=True;\n        # Whether to have a fixed no obj pointer when there is no object present\n        # or to use it as an additive embedding with obj_ptr produced by decoder\n        fixed_no_obj_ptr: bool = False,\n        # Soft no object, i.e. mix in no_obj_ptr softly,\n        # hope to make recovery easier if there is a mistake and mitigate accumulation of errors\n        soft_no_obj_ptr: bool = False,\n        use_mlp_for_obj_ptr_proj: bool = False,\n        # add no obj embedding to spatial frames\n        no_obj_embed_spatial: bool = False,\n        # extra arguments used to construct the SAM mask decoder; if not None, it should be a dict of kwargs to be passed into `MaskDecoder` class.\n        sam_mask_decoder_extra_args=None,\n        compile_image_encoder: bool = False,\n        # perceiver\n        spatial_perceiver=None,\n    ):\n        super().__init__()\n\n        # Part 1: the image backbone\n        self.image_encoder = image_encoder\n        # Use level 0, 1, 2 for high-res setting, or just level 2 for the default setting\n        self.use_high_res_features_in_sam = use_high_res_features_in_sam\n        self.num_feature_levels = 3 if use_high_res_features_in_sam else 1\n        self.use_obj_ptrs_in_encoder = use_obj_ptrs_in_encoder\n        self.max_obj_ptrs_in_encoder = max_obj_ptrs_in_encoder\n        if use_obj_ptrs_in_encoder:\n            # A conv layer to downsample the mask prompt to stride 4 (the same stride as\n            # low-res SAM mask logits) and to change its scales from 0~1 to SAM logit scale,\n            # so that it can be fed into the SAM mask decoder to generate a pointer.\n            self.mask_downsample = torch.nn.Conv2d(1, 1, kernel_size=4, stride=4)\n        self.add_tpos_enc_to_obj_ptrs = add_tpos_enc_to_obj_ptrs\n        if proj_tpos_enc_in_obj_ptrs:\n            assert add_tpos_enc_to_obj_ptrs  # these options need to be used together\n        self.proj_tpos_enc_in_obj_ptrs = proj_tpos_enc_in_obj_ptrs\n        self.use_signed_tpos_enc_to_obj_ptrs = use_signed_tpos_enc_to_obj_ptrs\n        self.only_obj_ptrs_in_the_past_for_eval = only_obj_ptrs_in_the_past_for_eval\n\n        # Part 2: memory attention to condition current frame\'s visual features\n        # with memories (and obj ptrs) from past frames\n        self.memory_attention = memory_attention\n        self.hidden_dim = image_encoder.neck.d_model\n\n        # Part 3: memory encoder for the previous frame\'s outputs\n        self.memory_encoder = memory_encoder\n        self.mem_dim = self.hidden_dim\n        if hasattr(self.memory_encoder, "out_proj") and hasattr(\n            self.memory_encoder.out_proj, "weight"\n        ):\n            # if there is compression of memories along channel dim\n            self.mem_dim = self.memory_encoder.out_proj.weight.shape[0]\n        self.num_maskmem = num_maskmem  # Number of memories accessible\n        # Temporal encoding of the memories\n        self.maskmem_tpos_enc = torch.nn.Parameter(\n            torch.zeros(num_maskmem, 1, 1, self.mem_dim)\n        )\n        trunc_normal_(self.maskmem_tpos_enc, std=0.02)\n        # a single token to indicate no memory embedding from previous frames\n        self.no_mem_embed = torch.nn.Parameter(torch.zeros(1, 1, self.hidden_dim))\n        self.no_mem_pos_enc = torch.nn.Parameter(torch.zeros(1, 1, self.hidden_dim))\n        trunc_normal_(self.no_mem_embed, std=0.02)\n        trunc_normal_(self.no_mem_pos_enc, std=0.02)\n        self.directly_add_no_mem_embed = directly_add_no_mem_embed\n        # Apply sigmoid to the output raw mask logits (to turn them from\n        # range (-inf, +inf) to range (0, 1)) before feeding them into the memory encoder\n        self.sigmoid_scale_for_mem_enc = sigmoid_scale_for_mem_enc\n        self.sigmoid_bias_for_mem_enc = sigmoid_bias_for_mem_enc\n        self.binarize_mask_from_pts_for_mem_enc = binarize_mask_from_pts_for_mem_enc\n        self.non_overlap_masks_for_mem_enc = non_overlap_masks_for_mem_enc\n        self.memory_temporal_stride_for_eval = memory_temporal_stride_for_eval\n        # On frames with mask input, whether to directly output the input mask without\n        # using a SAM prompt encoder + mask decoder\n        self.use_mask_input_as_output_without_sam = use_mask_input_as_output_without_sam\n        self.multimask_output_in_sam = multimask_output_in_sam\n        self.multimask_min_pt_num = multimask_min_pt_num\n        self.multimask_max_pt_num = multimask_max_pt_num\n        self.multimask_output_for_tracking = multimask_output_for_tracking\n        self.use_multimask_token_for_obj_ptr = use_multimask_token_for_obj_ptr\n        self.iou_prediction_use_sigmoid = iou_prediction_use_sigmoid\n\n        # Part 4: SAM-style prompt encoder (for both mask and point inputs)\n        # and SAM-style mask decoder for the final mask output\n        self.image_size = image_size\n        self.backbone_stride = backbone_stride\n        self.sam_mask_decoder_extra_args = sam_mask_decoder_extra_args\n        self.pred_obj_scores = pred_obj_scores\n        self.pred_obj_scores_mlp = pred_obj_scores_mlp\n        self.fixed_no_obj_ptr = fixed_no_obj_ptr\n        self.soft_no_obj_ptr = soft_no_obj_ptr\n        if self.fixed_no_obj_ptr:\n            assert self.pred_obj_scores\n            assert self.use_obj_ptrs_in_encoder\n        if self.pred_obj_scores and self.use_obj_ptrs_in_encoder:\n            self.no_obj_ptr = torch.nn.Parameter(torch.zeros(1, self.hidden_dim))\n            trunc_normal_(self.no_obj_ptr, std=0.02)\n        self.use_mlp_for_obj_ptr_proj = use_mlp_for_obj_ptr_proj\n        self.no_obj_embed_spatial = None\n        if no_obj_embed_spatial:\n            self.no_obj_embed_spatial = torch.nn.Parameter(torch.zeros(1, self.mem_dim))\n            trunc_normal_(self.no_obj_embed_spatial, std=0.02)\n\n        self._build_sam_heads()\n        self.max_cond_frames_in_attn = max_cond_frames_in_attn\n\n        # Perceiver\n        self.spatial_perceiver = spatial_perceiver\n\n        # Model compilation\n        if compile_image_encoder:\n            # Compile the forward function (not the full module) to allow loading checkpoints.\n            print(\n                "Image encoder compilation is enabled. First forward pass will be slow."\n            )\n            self.image_encoder.forward = torch.compile(\n                self.image_encoder.forward,\n                mode="max-autotune",\n                fullgraph=True,\n                dynamic=False,\n            )\n\n    @property\n    def device(self):\n        return next(self.parameters()).device\n\n    def forward(self, *args, **kwargs):\n        raise NotImplementedError(\n            "Please use the corresponding methods in SAM2VideoPredictor for inference or SAM2Train for training/fine-tuning"\n            "See notebooks/video_predictor_example.ipynb for an inference example."\n        )\n\n    def _build_sam_heads(self):\n        """Build SAM-style prompt encoder and mask decoder."""\n        self.sam_prompt_embed_dim = self.hidden_dim\n        self.sam_image_embedding_size = self.image_size // self.backbone_stride\n\n        # build PromptEncoder and MaskDecoder from SAM\n        # (their hyperparameters like `mask_in_chans=16` are from SAM code)\n        self.sam_prompt_encoder = PromptEncoder(\n            embed_dim=self.sam_prompt_embed_dim,\n            image_embedding_size=(\n                self.sam_image_embedding_size,\n                self.sam_image_embedding_size,\n            ),\n            input_image_size=(self.image_size, self.image_size),\n            mask_in_chans=16,\n        )\n        self.sam_mask_decoder = MaskDecoder(\n            num_multimask_outputs=3,\n            transformer=TwoWayTransformer(\n                depth=2,\n                embedding_dim=self.sam_prompt_embed_dim,\n                mlp_dim=2048,\n                num_heads=8,\n            ),\n            transformer_dim=self.sam_prompt_embed_dim,\n            iou_head_depth=3,\n            iou_head_hidden_dim=256,\n            use_high_res_features=self.use_high_res_features_in_sam,\n            iou_prediction_use_sigmoid=self.iou_prediction_use_sigmoid,\n            pred_obj_scores=self.pred_obj_scores,\n            pred_obj_scores_mlp=self.pred_obj_scores_mlp,\n            use_multimask_token_for_obj_ptr=self.use_multimask_token_for_obj_ptr,\n            **(self.sam_mask_decoder_extra_args or {}),\n        )\n        if self.use_obj_ptrs_in_encoder:\n            # a linear projection on SAM output tokens to turn them into object pointers\n            self.obj_ptr_proj = torch.nn.Linear(self.hidden_dim, self.hidden_dim)\n            if self.use_mlp_for_obj_ptr_proj:\n                self.obj_ptr_proj = MLP(\n                    self.hidden_dim, self.hidden_dim, self.hidden_dim, 3\n                )\n        else:\n            self.obj_ptr_proj = torch.nn.Identity()\n        if self.proj_tpos_enc_in_obj_ptrs:\n            # a linear projection on temporal positional encoding in object pointers to\n            # avoid potential interference with spatial positional encoding\n            self.obj_ptr_tpos_proj = torch.nn.Linear(self.hidden_dim, self.mem_dim)\n        else:\n            self.obj_ptr_tpos_proj = torch.nn.Identity()\n\n    def _forward_sam_heads(\n        self,\n        backbone_features,\n        point_inputs=None,\n        mask_inputs=None,\n        high_res_features=None,\n        multimask_output=False,\n    ):\n        """\n        Forward SAM prompt encoders and mask heads.\n\n        Inputs:\n        - backbone_features: image features of [B, C, H, W] shape\n        - point_inputs: a dictionary with "point_coords" and "point_labels", where\n          1) "point_coords" has [B, P, 2] shape and float32 dtype and contains the\n             absolute pixel-unit coordinate in (x, y) format of the P input points\n          2) "point_labels" has shape [B, P] and int32 dtype, where 1 means\n             positive clicks, 0 means negative clicks, and -1 means padding\n        - mask_inputs: a mask of [B, 1, H*16, W*16] shape, float or bool, with the\n          same spatial size as the image.\n        - high_res_features: either 1) None or 2) or a list of length 2 containing\n          two feature maps of [B, C, 4*H, 4*W] and [B, C, 2*H, 2*W] shapes respectively,\n          which will be used as high-resolution feature maps for SAM decoder.\n        - multimask_output: if it\'s True, we output 3 candidate masks and their 3\n          corresponding IoU estimates, and if it\'s False, we output only 1 mask and\n          its corresponding IoU estimate.\n\n        Outputs:\n        - low_res_multimasks: [B, M, H*4, W*4] shape (where M = 3 if\n          `multimask_output=True` and M = 1 if `multimask_output=False`), the SAM\n          output mask logits (before sigmoid) for the low-resolution masks, with 4x\n          the resolution (1/4 stride) of the input backbone_features.\n        - high_res_multimasks: [B, M, H*16, W*16] shape (where M = 3\n          if `multimask_output=True` and M = 1 if `multimask_output=False`),\n          upsampled from the low-resolution masks, with shape size as the image\n          (stride is 1 pixel).\n        - ious, [B, M] shape, where (where M = 3 if `multimask_output=True` and M = 1\n          if `multimask_output=False`), the estimated IoU of each output mask.\n        - low_res_masks: [B, 1, H*4, W*4] shape, the best mask in `low_res_multimasks`.\n          If `multimask_output=True`, it\'s the mask with the highest IoU estimate.\n          If `multimask_output=False`, it\'s the same as `low_res_multimasks`.\n        - high_res_masks: [B, 1, H*16, W*16] shape, the best mask in `high_res_multimasks`.\n          If `multimask_output=True`, it\'s the mask with the highest IoU estimate.\n          If `multimask_output=False`, it\'s the same as `high_res_multimasks`.\n        - obj_ptr: [B, C] shape, the object pointer vector for the output mask, extracted\n          based on the output token from the SAM mask decoder.\n        """\n        B = backbone_features.size(0)\n        device = backbone_features.device\n        assert backbone_features.size(1) == self.sam_prompt_embed_dim\n        assert backbone_features.size(2) == self.sam_image_embedding_size\n        assert backbone_features.size(3) == self.sam_image_embedding_size\n\n        # a) Handle point prompts\n        if point_inputs is not None:\n            sam_point_coords = point_inputs["point_coords"]\n            sam_point_labels = point_inputs["point_labels"]\n            assert sam_point_coords.size(0) == B and sam_point_labels.size(0) == B\n        else:\n            # If no points are provide, pad with an empty point (with label -1)\n            sam_point_coords = torch.zeros(B, 1, 2, device=device)\n            sam_point_labels = -torch.ones(B, 1, dtype=torch.int32, device=device)\n\n        # b) Handle mask prompts\n        if mask_inputs is not None:\n            # If mask_inputs is provided, downsize it into low-res mask input if needed\n            # and feed it as a dense mask prompt into the SAM mask encoder\n            assert len(mask_inputs.shape) == 4 and mask_inputs.shape[:2] == (B, 1)\n            if mask_inputs.shape[-2:] != self.sam_prompt_encoder.mask_input_size:\n                sam_mask_prompt = F.interpolate(\n                    mask_inputs.float(),\n                    size=self.sam_prompt_encoder.mask_input_size,\n                    align_corners=False,\n                    mode="bilinear",\n                    antialias=True,  # use antialias for downsampling\n                )\n            else:\n                sam_mask_prompt = mask_inputs\n        else:\n            # Otherwise, simply feed None (and SAM\'s prompt encoder will add\n            # a learned `no_mask_embed` to indicate no mask input in this case).\n            sam_mask_prompt = None\n\n        sparse_embeddings, dense_embeddings = self.sam_prompt_encoder(\n            points=(sam_point_coords, sam_point_labels),\n            boxes=None,\n            masks=sam_mask_prompt,\n        )\n        (\n            low_res_multimasks,\n            ious,\n            sam_output_tokens,\n            object_score_logits,\n        ) = self.sam_mask_decoder(\n            image_embeddings=backbone_features,\n            image_pe=self.sam_prompt_encoder.get_dense_pe(),\n            sparse_prompt_embeddings=sparse_embeddings,\n            dense_prompt_embeddings=dense_embeddings,\n            multimask_output=multimask_output,\n            repeat_image=False,  # the image is already batched\n            high_res_features=high_res_features,\n        )\n        if self.pred_obj_scores:\n            is_obj_appearing = object_score_logits > 0\n\n            # Mask used for spatial memories is always a *hard* choice between obj and no obj,\n            # consistent with the actual mask prediction\n            low_res_multimasks = torch.where(\n                is_obj_appearing[:, None, None],\n                low_res_multimasks,\n                NO_OBJ_SCORE,\n            )\n\n        # convert masks from possibly bfloat16 (or float16) to float32\n        # (older PyTorch versions before 2.1 don\'t support `interpolate` on bf16)\n        low_res_multimasks = low_res_multimasks.float()\n        high_res_multimasks = F.interpolate(\n            low_res_multimasks,\n            size=(self.image_size, self.image_size),\n            mode="bilinear",\n            align_corners=False,\n        )\n\n        sam_output_token = sam_output_tokens[:, 0]\n        if multimask_output:\n            # take the best mask prediction (with the highest IoU estimation)\n            best_iou_inds = torch.argmax(ious, dim=-1)\n            batch_inds = torch.arange(B, device=device)\n            low_res_masks = low_res_multimasks[batch_inds, best_iou_inds].unsqueeze(1)\n            high_res_masks = high_res_multimasks[batch_inds, best_iou_inds].unsqueeze(1)\n            if sam_output_tokens.size(1) > 1:\n                sam_output_token = sam_output_tokens[batch_inds, best_iou_inds]\n        else:\n            low_res_masks, high_res_masks = low_res_multimasks, high_res_multimasks\n\n        # Extract object pointer from the SAM output token (with occlusion handling)\n        obj_ptr = self.obj_ptr_proj(sam_output_token)\n        if self.pred_obj_scores:\n            # Allow *soft* no obj ptr, unlike for masks\n            if self.soft_no_obj_ptr:\n                lambda_is_obj_appearing = object_score_logits.sigmoid()\n            else:\n                lambda_is_obj_appearing = is_obj_appearing.float()\n\n            if self.fixed_no_obj_ptr:\n                obj_ptr = lambda_is_obj_appearing * obj_ptr\n            obj_ptr = obj_ptr + (1 - lambda_is_obj_appearing) * self.no_obj_ptr\n\n        return (\n            low_res_multimasks,\n            high_res_multimasks,\n            ious,\n            low_res_masks,\n            high_res_masks,\n            obj_ptr,\n            object_score_logits,\n        )\n\n    def _use_mask_as_output(self, backbone_features, high_res_features, mask_inputs):\n        """\n        Directly turn binary `mask_inputs` into a output mask logits without using SAM.\n        (same input and output shapes as in _forward_sam_heads above).\n        """\n        # Use -10/+10 as logits for neg/pos pixels (very close to 0/1 in prob after sigmoid).\n        out_scale, out_bias = 20.0, -10.0  # sigmoid(-10.0)=4.5398e-05\n        mask_inputs_float = mask_inputs.float()\n        high_res_masks = mask_inputs_float * out_scale + out_bias\n        low_res_masks = F.interpolate(\n            high_res_masks,\n            size=(high_res_masks.size(-2) // 4, high_res_masks.size(-1) // 4),\n            align_corners=False,\n            mode="bilinear",\n            antialias=True,  # use antialias for downsampling\n        )\n        # a dummy IoU prediction of all 1\'s under mask input\n        ious = mask_inputs.new_ones(mask_inputs.size(0), 1).float()\n        if not self.use_obj_ptrs_in_encoder:\n            # all zeros as a dummy object pointer (of shape [B, C])\n            obj_ptr = torch.zeros(\n                mask_inputs.size(0), self.hidden_dim, device=mask_inputs.device\n            )\n        else:\n            # produce an object pointer using the SAM decoder from the mask input\n            _, _, _, _, _, obj_ptr, _ = self._forward_sam_heads(\n                backbone_features=backbone_features,\n                mask_inputs=self.mask_downsample(mask_inputs_float),\n                high_res_features=high_res_features,\n            )\n        # In this method, we are treating mask_input as output, e.g. using it directly to create spatial mem;\n        # Below, we follow the same design axiom to use mask_input to decide if obj appears or not instead of relying\n        # on the object_scores from the SAM decoder.\n        is_obj_appearing = torch.any(mask_inputs.flatten(1).float() > 0.0, dim=1)\n        is_obj_appearing = is_obj_appearing[..., None]\n        lambda_is_obj_appearing = is_obj_appearing.float()\n        object_score_logits = out_scale * lambda_is_obj_appearing + out_bias\n        if self.pred_obj_scores:\n            if self.fixed_no_obj_ptr:\n                obj_ptr = lambda_is_obj_appearing * obj_ptr\n            obj_ptr = obj_ptr + (1 - lambda_is_obj_appearing) * self.no_obj_ptr\n\n        return (\n            low_res_masks,\n            high_res_masks,\n            ious,\n            low_res_masks,\n            high_res_masks,\n            obj_ptr,\n            object_score_logits,\n        )\n\n    def forward_image(self, img_batch: torch.Tensor):\n        """Get the image feature on the input batch."""\n        backbone_out = self.image_encoder(img_batch)\n        if self.use_high_res_features_in_sam:\n            # precompute projected level 0 and level 1 features in SAM decoder\n            # to avoid running it again on every SAM click\n            backbone_out["backbone_fpn"][0] = self.sam_mask_decoder.conv_s0(\n                backbone_out["backbone_fpn"][0]\n            )\n            backbone_out["backbone_fpn"][1] = self.sam_mask_decoder.conv_s1(\n                backbone_out["backbone_fpn"][1]\n            )\n        return backbone_out\n\n    def _prepare_backbone_features(self, backbone_out):\n        """Prepare and flatten visual features."""\n        backbone_out = backbone_out.copy()\n        assert len(backbone_out["backbone_fpn"]) == len(backbone_out["vision_pos_enc"])\n        assert len(backbone_out["backbone_fpn"]) >= self.num_feature_levels\n\n        feature_maps = backbone_out["backbone_fpn"][-self.num_feature_levels :]\n        vision_pos_embeds = backbone_out["vision_pos_enc"][-self.num_feature_levels :]\n\n        feat_sizes = [(x.shape[-2], x.shape[-1]) for x in vision_pos_embeds]\n        # flatten NxCxHxW to HWxNxC\n        vision_feats = [x.flatten(2).permute(2, 0, 1) for x in feature_maps]\n        vision_pos_embeds = [x.flatten(2).permute(2, 0, 1) for x in vision_pos_embeds]\n\n        return backbone_out, vision_feats, vision_pos_embeds, feat_sizes\n\n    def _prepare_memory_conditioned_features(\n        self,\n        frame_idx,\n        is_init_cond_frame,\n        current_vision_feats,\n        current_vision_pos_embeds,\n        feat_sizes,\n        output_dict,\n        num_frames,\n        track_in_reverse=False,  # tracking in reverse time order (for demo usage)\n    ):\n        """Fuse the current frame\'s visual feature map with previous memory."""\n        B = current_vision_feats[-1].size(1)  # batch size on this frame\n        C = self.hidden_dim\n        H, W = feat_sizes[-1]  # top-level (lowest-resolution) feature size\n        device = current_vision_feats[-1].device\n        # The case of `self.num_maskmem == 0` below is primarily used for reproducing SAM on images.\n        # In this case, we skip the fusion with any memory.\n        if self.num_maskmem == 0:  # Disable memory and skip fusion\n            pix_feat = current_vision_feats[-1].permute(1, 2, 0).view(B, C, H, W)\n            return pix_feat\n\n        num_obj_ptr_tokens = 0\n        tpos_sign_mul = -1 if track_in_reverse else 1\n        # Step 1: condition the visual features of the current frame on previous memories\n        if not is_init_cond_frame:\n            # Retrieve the memories encoded with the maskmem backbone\n            to_cat_memory, to_cat_memory_pos_embed = [], []\n            # Add conditioning frames\'s output first (all cond frames have t_pos=0 for\n            # when getting temporal positional embedding below)\n            assert len(output_dict["cond_frame_outputs"]) > 0\n            # Select a maximum number of temporally closest cond frames for cross attention\n            cond_outputs = output_dict["cond_frame_outputs"]\n            selected_cond_outputs, unselected_cond_outputs = select_closest_cond_frames(\n                frame_idx, cond_outputs, self.max_cond_frames_in_attn\n            )\n            t_pos_and_prevs = [(0, out) for out in selected_cond_outputs.values()]\n            # Add last (self.num_maskmem - 1) frames before current frame for non-conditioning memory\n            # the earliest one has t_pos=1 and the latest one has t_pos=self.num_maskmem-1\n            # We also allow taking the memory frame non-consecutively (with stride>1), in which case\n            # we take (self.num_maskmem - 2) frames among every stride-th frames plus the last frame.\n            stride = 1 if self.training else self.memory_temporal_stride_for_eval\n            for t_pos in range(1, self.num_maskmem):\n                t_rel = self.num_maskmem - t_pos  # how many frames before current frame\n                if t_rel == 1:\n                    # for t_rel == 1, we take the last frame (regardless of r)\n                    if not track_in_reverse:\n                        # the frame immediately before this frame (i.e. frame_idx - 1)\n                        prev_frame_idx = frame_idx - t_rel\n                    else:\n                        # the frame immediately after this frame (i.e. frame_idx + 1)\n                        prev_frame_idx = frame_idx + t_rel\n                else:\n                    # for t_rel >= 2, we take the memory frame from every r-th frames\n                    if not track_in_reverse:\n                        # first find the nearest frame among every r-th frames before this frame\n                        # for r=1, this would be (frame_idx - 2)\n                        prev_frame_idx = ((frame_idx - 2) // stride) * stride\n                        # then seek further among every r-th frames\n                        prev_frame_idx = prev_frame_idx - (t_rel - 2) * stride\n                    else:\n                        # first find the nearest frame among every r-th frames after this frame\n                        # for r=1, this would be (frame_idx + 2)\n                        prev_frame_idx = -(-(frame_idx + 2) // stride) * stride\n                        # then seek further among every r-th frames\n                        prev_frame_idx = prev_frame_idx + (t_rel - 2) * stride\n                out = output_dict["non_cond_frame_outputs"].get(prev_frame_idx, None)\n                if out is None:\n                    # If an unselected conditioning frame is among the last (self.num_maskmem - 1)\n                    # frames, we still attend to it as if it\'s a non-conditioning frame.\n                    out = unselected_cond_outputs.get(prev_frame_idx, None)\n                t_pos_and_prevs.append((t_pos, out))\n\n            for t_pos, prev in t_pos_and_prevs:\n                if prev is None:\n                    continue  # skip padding frames\n                # "maskmem_features" might have been offloaded to CPU in demo use cases,\n                # so we load it back to GPU (it\'s a no-op if it\'s already on GPU).\n                feats = prev["maskmem_features"].to(device, non_blocking=True)\n                if feats.ndim == 3:  # (B, HW, C) because of spatial perceiver\n                    to_cat_memory.append(feats.permute(1, 0, 2))\n                else:  # (B, C, H, W)\n                    to_cat_memory.append(feats.flatten(2).permute(2, 0, 1))\n                # Spatial positional encoding (it might have been offloaded to CPU in eval)\n                maskmem_enc = prev["maskmem_pos_enc"][-1].to(device)\n                if maskmem_enc.ndim == 3:  # (B, HW, C) because of spatial perceiver\n                    maskmem_enc = maskmem_enc.permute(1, 0, 2)\n                else:  # (B, C, H, W)\n                    maskmem_enc = maskmem_enc.flatten(2).permute(2, 0, 1)\n                # Temporal positional encoding\n                maskmem_enc = (\n                    maskmem_enc + self.maskmem_tpos_enc[self.num_maskmem - t_pos - 1]\n                )\n                to_cat_memory_pos_embed.append(maskmem_enc)\n\n            num_spatial_mem = len(to_cat_memory)\n\n            # Construct the list of past object pointers\n            if self.use_obj_ptrs_in_encoder:\n                max_obj_ptrs_in_encoder = min(num_frames, self.max_obj_ptrs_in_encoder)\n                # First add those object pointers from selected conditioning frames\n                # (optionally, only include object pointers in the past during evaluation)\n                if not self.training and self.only_obj_ptrs_in_the_past_for_eval:\n                    ptr_cond_outputs = {\n                        t: out\n                        for t, out in selected_cond_outputs.items()\n                        if (t >= frame_idx if track_in_reverse else t <= frame_idx)\n                    }\n                else:\n                    ptr_cond_outputs = selected_cond_outputs\n                pos_and_ptrs = [\n                    # Temporal pos encoding contains how far away each pointer is from current frame\n                    (\n                        (\n                            (frame_idx - t) * tpos_sign_mul\n                            if self.use_signed_tpos_enc_to_obj_ptrs\n                            else abs(frame_idx - t)\n                        ),\n                        out["obj_ptr"],\n                    )\n                    for t, out in ptr_cond_outputs.items()\n                ]\n                # Add up to (max_obj_ptrs_in_encoder - 1) non-conditioning frames before current frame\n                for t_diff in range(1, max_obj_ptrs_in_encoder):\n                    t = frame_idx + t_diff if track_in_reverse else frame_idx - t_diff\n                    if t < 0 or (num_frames is not None and t >= num_frames):\n                        break\n                    out = output_dict["non_cond_frame_outputs"].get(\n                        t, unselected_cond_outputs.get(t, None)\n                    )\n                    if out is not None:\n                        pos_and_ptrs.append((t_diff, out["obj_ptr"]))\n                # If we have at least one object pointer, add them to the across attention\n                if len(pos_and_ptrs) > 0:\n                    pos_list, ptrs_list = zip(*pos_and_ptrs)\n                    # stack object pointers along dim=0 into [ptr_seq_len, B, C] shape\n                    obj_ptrs = torch.stack(ptrs_list, dim=0)\n                    # a temporal positional embedding based on how far each object pointer is from\n                    # the current frame (sine embedding normalized by the max pointer num).\n                    if self.add_tpos_enc_to_obj_ptrs:\n                        t_diff_max = max_obj_ptrs_in_encoder - 1\n                        tpos_dim = C if self.proj_tpos_enc_in_obj_ptrs else self.mem_dim\n                        obj_pos = torch.tensor(pos_list, device=device)\n                        obj_pos = get_1d_sine_pe(obj_pos / t_diff_max, dim=tpos_dim)\n                        obj_pos = self.obj_ptr_tpos_proj(obj_pos)\n                        obj_pos = obj_pos.unsqueeze(1).expand(-1, B, self.mem_dim)\n                    else:\n                        obj_pos = obj_ptrs.new_zeros(len(pos_list), B, self.mem_dim)\n                    if self.mem_dim < C:\n                        # split a pointer into (C // self.mem_dim) tokens for self.mem_dim < C\n                        obj_ptrs = obj_ptrs.reshape(\n                            -1, B, C // self.mem_dim, self.mem_dim\n                        )\n                        obj_ptrs = obj_ptrs.permute(0, 2, 1, 3).flatten(0, 1)\n                        obj_pos = obj_pos.repeat_interleave(C // self.mem_dim, dim=0)\n                    to_cat_memory.append(obj_ptrs)\n                    to_cat_memory_pos_embed.append(obj_pos)\n                    num_obj_ptr_tokens = obj_ptrs.shape[0]\n                else:\n                    num_obj_ptr_tokens = 0\n        else:\n            # for initial conditioning frames, encode them without using any previous memory\n            if self.directly_add_no_mem_embed:\n                # directly add no-mem embedding (instead of using the transformer encoder)\n                pix_feat_with_mem = current_vision_feats[-1] + self.no_mem_embed\n                pix_feat_with_mem = pix_feat_with_mem.permute(1, 2, 0).view(B, C, H, W)\n                return pix_feat_with_mem\n\n            # Use a dummy token on the first frame (to avoid empty memory input to tranformer encoder)\n            to_cat_memory = [self.no_mem_embed.expand(1, B, self.mem_dim)]\n            to_cat_memory_pos_embed = [self.no_mem_pos_enc.expand(1, B, self.mem_dim)]\n            num_spatial_mem = len(to_cat_memory)\n\n        # Step 2: Concatenate the memories and forward through the transformer encoder\n        memory = torch.cat(to_cat_memory, dim=0)\n        memory_pos_embed = torch.cat(to_cat_memory_pos_embed, dim=0)\n\n        pix_feat_with_mem = self.memory_attention(\n            curr=current_vision_feats,\n            curr_pos=current_vision_pos_embeds,\n            memory=memory,\n            memory_pos=memory_pos_embed,\n            num_obj_ptr_tokens=num_obj_ptr_tokens,\n            num_spatial_mem=num_spatial_mem,\n        )\n        # reshape the output (HW)BC => BCHW\n        pix_feat_with_mem = pix_feat_with_mem.permute(1, 2, 0).view(B, C, H, W)\n        return pix_feat_with_mem\n\n    def _encode_new_memory(\n        self,\n        current_vision_feats,\n        feat_sizes,\n        pred_masks_high_res,\n        object_score_logits,\n        is_mask_from_pts,\n    ):\n        """Encode the current image and its prediction into a memory feature."""\n        B = current_vision_feats[-1].size(1)  # batch size on this frame\n        C = self.hidden_dim\n        H, W = feat_sizes[-1]  # top-level (lowest-resolution) feature size\n        # top-level feature, (HW)BC => BCHW\n        pix_feat = current_vision_feats[-1].permute(1, 2, 0).view(B, C, H, W)\n        if self.non_overlap_masks_for_mem_enc and not self.training:\n            # optionally, apply non-overlapping constraints to the masks (it\'s applied\n            # in the batch dimension and should only be used during eval, where all\n            # the objects come from the same video under batch size 1).\n            pred_masks_high_res = self._apply_non_overlapping_constraints(\n                pred_masks_high_res\n            )\n        # scale the raw mask logits with a temperature before applying sigmoid\n        binarize = self.binarize_mask_from_pts_for_mem_enc and is_mask_from_pts\n        if binarize and not self.training:\n            mask_for_mem = (pred_masks_high_res > 0).float()\n        else:\n            # apply sigmoid on the raw mask logits to turn them into range (0, 1)\n            mask_for_mem = torch.sigmoid(pred_masks_high_res)\n        # apply scale and bias terms to the sigmoid probabilities\n        if self.sigmoid_scale_for_mem_enc != 1.0:\n            mask_for_mem = mask_for_mem * self.sigmoid_scale_for_mem_enc\n        if self.sigmoid_bias_for_mem_enc != 0.0:\n            mask_for_mem = mask_for_mem + self.sigmoid_bias_for_mem_enc\n        maskmem_out = self.memory_encoder(\n            pix_feat, mask_for_mem, skip_mask_sigmoid=True  # sigmoid already applied\n        )\n        maskmem_features = maskmem_out["vision_features"]\n        maskmem_pos_enc = maskmem_out["vision_pos_enc"]\n        # add a no-object embedding to the spatial memory to indicate that the frame\n        # is predicted to be occluded (i.e. no object is appearing in the frame)\n        if self.no_obj_embed_spatial is not None:\n            is_obj_appearing = (object_score_logits > 0).float()\n            maskmem_features += (\n                1 - is_obj_appearing[..., None, None]\n            ) * self.no_obj_embed_spatial[..., None, None].expand(\n                *maskmem_features.shape\n            )\n\n        if self.spatial_perceiver is not None:\n            maskmem_features, maskmem_pos_enc[0] = self.spatial_perceiver(\n                maskmem_features, maskmem_pos_enc[0]\n            )\n\n        return maskmem_features, maskmem_pos_enc\n\n    def _track_step(\n        self,\n        frame_idx,\n        is_init_cond_frame,\n        current_vision_feats,\n        current_vision_pos_embeds,\n        feat_sizes,\n        point_inputs,\n        mask_inputs,\n        output_dict,\n        num_frames,\n        track_in_reverse,\n        prev_sam_mask_logits,\n    ):\n        current_out = {"point_inputs": point_inputs, "mask_inputs": mask_inputs}\n        # High-resolution feature maps for the SAM head, reshape (HW)BC => BCHW\n        if len(current_vision_feats) > 1:\n            high_res_features = [\n                x.permute(1, 2, 0).view(x.size(1), x.size(2), *s)\n                for x, s in zip(current_vision_feats[:-1], feat_sizes[:-1])\n            ]\n        else:\n            high_res_features = None\n        if mask_inputs is not None and self.use_mask_input_as_output_without_sam:\n            # When use_mask_input_as_output_without_sam=True, we directly output the mask input\n            # (see it as a GT mask) without using a SAM prompt encoder + mask decoder.\n            pix_feat = current_vision_feats[-1].permute(1, 2, 0)\n            pix_feat = pix_feat.view(-1, self.hidden_dim, *feat_sizes[-1])\n            sam_outputs = self._use_mask_as_output(\n                pix_feat, high_res_features, mask_inputs\n            )\n        else:\n            # fused the visual feature with previous memory features in the memory bank\n            pix_feat = self._prepare_memory_conditioned_features(\n                frame_idx=frame_idx,\n                is_init_cond_frame=is_init_cond_frame,\n                current_vision_feats=current_vision_feats[-1:],\n                current_vision_pos_embeds=current_vision_pos_embeds[-1:],\n                feat_sizes=feat_sizes[-1:],\n                output_dict=output_dict,\n                num_frames=num_frames,\n                track_in_reverse=track_in_reverse,\n            )\n            # apply SAM-style segmentation head\n            # here we might feed previously predicted low-res SAM mask logits into the SAM mask decoder,\n            # e.g. in demo where such logits come from earlier interaction instead of correction sampling\n            # (in this case, any `mask_inputs` shouldn\'t reach here as they are sent to _use_mask_as_output instead)\n            if prev_sam_mask_logits is not None:\n                assert point_inputs is not None and mask_inputs is None\n                mask_inputs = prev_sam_mask_logits\n            multimask_output = self._use_multimask(is_init_cond_frame, point_inputs)\n            sam_outputs = self._forward_sam_heads(\n                backbone_features=pix_feat,\n                point_inputs=point_inputs,\n                mask_inputs=mask_inputs,\n                high_res_features=high_res_features,\n                multimask_output=multimask_output,\n            )\n\n        return current_out, sam_outputs, high_res_features, pix_feat\n\n    def _encode_memory_in_output(\n        self,\n        current_vision_feats,\n        feat_sizes,\n        point_inputs,\n        run_mem_encoder,\n        high_res_masks,\n        object_score_logits,\n        current_out,\n    ):\n        if run_mem_encoder and self.num_maskmem > 0:\n            high_res_masks_for_mem_enc = high_res_masks\n            maskmem_features, maskmem_pos_enc = self._encode_new_memory(\n                current_vision_feats=current_vision_feats,\n                feat_sizes=feat_sizes,\n                pred_masks_high_res=high_res_masks_for_mem_enc,\n                object_score_logits=object_score_logits,\n                is_mask_from_pts=(point_inputs is not None),\n            )\n            current_out["maskmem_features"] = maskmem_features\n            current_out["maskmem_pos_enc"] = maskmem_pos_enc\n        else:\n            current_out["maskmem_features"] = None\n            current_out["maskmem_pos_enc"] = None\n\n    def track_step(\n        self,\n        frame_idx,\n        is_init_cond_frame,\n        current_vision_feats,\n        current_vision_pos_embeds,\n        feat_sizes,\n        point_inputs,\n        mask_inputs,\n        output_dict,\n        num_frames,\n        track_in_reverse=False,  # tracking in reverse time order (for demo usage)\n        # Whether to run the memory encoder on the predicted masks. Sometimes we might want\n        # to skip the memory encoder with `run_mem_encoder=False`. For example,\n        # in demo we might call `track_step` multiple times for each user click,\n        # and only encode the memory when the user finalizes their clicks. And in ablation\n        # settings like SAM training on static images, we don\'t need the memory encoder.\n        run_mem_encoder=True,\n        # The previously predicted SAM mask logits (which can be fed together with new clicks in demo).\n        prev_sam_mask_logits=None,\n    ):\n        current_out, sam_outputs, _, _ = self._track_step(\n            frame_idx,\n            is_init_cond_frame,\n            current_vision_feats,\n            current_vision_pos_embeds,\n            feat_sizes,\n            point_inputs,\n            mask_inputs,\n            output_dict,\n            num_frames,\n            track_in_reverse,\n            prev_sam_mask_logits,\n        )\n\n        (\n            _,\n            _,\n            _,\n            low_res_masks,\n            high_res_masks,\n            obj_ptr,\n            object_score_logits,\n        ) = sam_outputs\n\n        current_out["pred_masks"] = low_res_masks\n        current_out["pred_masks_high_res"] = high_res_masks\n        current_out["obj_ptr"] = obj_ptr\n        if not self.training:\n            # Only add this in inference (to avoid unused param in activation checkpointing;\n            # it\'s mainly used in the demo to encode spatial memories w/ consolidated masks)\n            current_out["object_score_logits"] = object_score_logits\n\n        # Finally run the memory encoder on the predicted mask to encode\n        # it into a new memory feature (that can be used in future frames)\n        self._encode_memory_in_output(\n            current_vision_feats,\n            feat_sizes,\n            point_inputs,\n            run_mem_encoder,\n            high_res_masks,\n            object_score_logits,\n            current_out,\n        )\n\n        return current_out\n\n    def _use_multimask(self, is_init_cond_frame, point_inputs):\n        """Whether to use multimask output in the SAM head."""\n        num_pts = 0 if point_inputs is None else point_inputs["point_labels"].size(1)\n        multimask_output = (\n            self.multimask_output_in_sam\n            and (is_init_cond_frame or self.multimask_output_for_tracking)\n            and (self.multimask_min_pt_num <= num_pts <= self.multimask_max_pt_num)\n        )\n        return multimask_output\n\n    def _apply_non_overlapping_constraints(self, pred_masks):\n        """\n        Apply non-overlapping constraints to the object scores in pred_masks. Here we\n        keep only the highest scoring object at each spatial location in pred_masks.\n        """\n        batch_size = pred_masks.size(0)\n        if batch_size == 1:\n            return pred_masks\n\n        device = pred_masks.device\n        # "max_obj_inds": object index of the object with the highest score at each location\n        max_obj_inds = torch.argmax(pred_masks, dim=0, keepdim=True)\n        # "batch_obj_inds": object index of each object slice (along dim 0) in `pred_masks`\n        batch_obj_inds = torch.arange(batch_size, device=device)[:, None, None, None]\n        keep = max_obj_inds == batch_obj_inds\n        # suppress overlapping regions\' scores below -10.0 so that the foreground regions\n        # don\'t overlap (here sigmoid(-10.0)=4.5398e-05)\n        pred_masks = torch.where(keep, pred_masks, torch.clamp(pred_masks, max=-10.0))\n        return pred_masks\n', '_shared_test_resources/code/EdgeTAM/sam2/modeling/sam2_utils.py': '# Copyright (c) Meta Platforms, Inc. and affiliates.\n# All rights reserved.\n\n# This source code is licensed under the license found in the\n# LICENSE file in the root directory of this source tree.\n\n\nimport copy\nfrom typing import Tuple\n\nimport numpy as np\nimport torch\nimport torch.nn as nn\nimport torch.nn.functional as F\n\nfrom sam2.utils.misc import mask_to_box\n\n\ndef select_closest_cond_frames(frame_idx, cond_frame_outputs, max_cond_frame_num):\n    """\n    Select up to `max_cond_frame_num` conditioning frames from `cond_frame_outputs`\n    that are temporally closest to the current frame at `frame_idx`. Here, we take\n    - a) the closest conditioning frame before `frame_idx` (if any);\n    - b) the closest conditioning frame after `frame_idx` (if any);\n    - c) any other temporally closest conditioning frames until reaching a total\n         of `max_cond_frame_num` conditioning frames.\n\n    Outputs:\n    - selected_outputs: selected items (keys & values) from `cond_frame_outputs`.\n    - unselected_outputs: items (keys & values) not selected in `cond_frame_outputs`.\n    """\n    if max_cond_frame_num == -1 or len(cond_frame_outputs) <= max_cond_frame_num:\n        selected_outputs = cond_frame_outputs\n        unselected_outputs = {}\n    else:\n        assert max_cond_frame_num >= 2, "we should allow using 2+ conditioning frames"\n        selected_outputs = {}\n\n        # the closest conditioning frame before `frame_idx` (if any)\n        idx_before = max((t for t in cond_frame_outputs if t < frame_idx), default=None)\n        if idx_before is not None:\n            selected_outputs[idx_before] = cond_frame_outputs[idx_before]\n\n        # the closest conditioning frame after `frame_idx` (if any)\n        idx_after = min((t for t in cond_frame_outputs if t >= frame_idx), default=None)\n        if idx_after is not None:\n            selected_outputs[idx_after] = cond_frame_outputs[idx_after]\n\n        # add other temporally closest conditioning frames until reaching a total\n        # of `max_cond_frame_num` conditioning frames.\n        num_remain = max_cond_frame_num - len(selected_outputs)\n        inds_remain = sorted(\n            (t for t in cond_frame_outputs if t not in selected_outputs),\n            key=lambda x: abs(x - frame_idx),\n        )[:num_remain]\n        selected_outputs.update((t, cond_frame_outputs[t]) for t in inds_remain)\n        unselected_outputs = {\n            t: v for t, v in cond_frame_outputs.items() if t not in selected_outputs\n        }\n\n    return selected_outputs, unselected_outputs\n\n\ndef get_1d_sine_pe(pos_inds, dim, temperature=10000):\n    """\n    Get 1D sine positional embedding as in the original Transformer paper.\n    """\n    pe_dim = dim // 2\n    dim_t = torch.arange(pe_dim, dtype=torch.float32, device=pos_inds.device)\n    dim_t = temperature ** (2 * (dim_t // 2) / pe_dim)\n\n    pos_embed = pos_inds.unsqueeze(-1) / dim_t\n    pos_embed = torch.cat([pos_embed.sin(), pos_embed.cos()], dim=-1)\n    return pos_embed\n\n\ndef get_activation_fn(activation):\n    """Return an activation function given a string"""\n    if activation == "relu":\n        return F.relu\n    if activation == "gelu":\n        return F.gelu\n    if activation == "glu":\n        return F.glu\n    raise RuntimeError(f"activation should be relu/gelu, not {activation}.")\n\n\ndef get_clones(module, N):\n    return nn.ModuleList([copy.deepcopy(module) for i in range(N)])\n\n\nclass DropPath(nn.Module):\n    # adapted from https://github.com/huggingface/pytorch-image-models/blob/main/timm/layers/drop.py\n    def __init__(self, drop_prob=0.0, scale_by_keep=True):\n        super(DropPath, self).__init__()\n        self.drop_prob = drop_prob\n        self.scale_by_keep = scale_by_keep\n\n    def forward(self, x):\n        if self.drop_prob == 0.0 or not self.training:\n            return x\n        keep_prob = 1 - self.drop_prob\n        shape = (x.shape[0],) + (1,) * (x.ndim - 1)\n        random_tensor = x.new_empty(shape).bernoulli_(keep_prob)\n        if keep_prob > 0.0 and self.scale_by_keep:\n            random_tensor.div_(keep_prob)\n        return x * random_tensor\n\n\n# Lightly adapted from\n# https://github.com/facebookresearch/MaskFormer/blob/main/mask_former/modeling/transformer/transformer_predictor.py # noqa\nclass MLP(nn.Module):\n    def __init__(\n        self,\n        input_dim: int,\n        hidden_dim: int,\n        output_dim: int,\n        num_layers: int,\n        activation: nn.Module = nn.ReLU,\n        sigmoid_output: bool = False,\n    ) -> None:\n        super().__init__()\n        self.num_layers = num_layers\n        h = [hidden_dim] * (num_layers - 1)\n        self.layers = nn.ModuleList(\n            nn.Linear(n, k) for n, k in zip([input_dim] + h, h + [output_dim])\n        )\n        self.sigmoid_output = sigmoid_output\n        self.act = activation()\n\n    def forward(self, x):\n        for i, layer in enumerate(self.layers):\n            x = self.act(layer(x)) if i < self.num_layers - 1 else layer(x)\n        if self.sigmoid_output:\n            x = F.sigmoid(x)\n        return x\n\n\n# From https://github.com/facebookresearch/detectron2/blob/main/detectron2/layers/batch_norm.py # noqa\n# Itself from https://github.com/facebookresearch/ConvNeXt/blob/d1fa8f6fef0a165b27399986cc2bdacc92777e40/models/convnext.py#L119  # noqa\nclass LayerNorm2d(nn.Module):\n    def __init__(self, num_channels: int, eps: float = 1e-6) -> None:\n        super().__init__()\n        self.weight = nn.Parameter(torch.ones(num_channels))\n        self.bias = nn.Parameter(torch.zeros(num_channels))\n        self.eps = eps\n\n    def forward(self, x: torch.Tensor) -> torch.Tensor:\n        u = x.mean(1, keepdim=True)\n        s = (x - u).pow(2).mean(1, keepdim=True)\n        x = (x - u) / torch.sqrt(s + self.eps)\n        x = self.weight[:, None, None] * x + self.bias[:, None, None]\n        return x\n\n\ndef sample_box_points(\n    masks: torch.Tensor,\n    noise: float = 0.1,  # SAM default\n    noise_bound: int = 20,  # SAM default\n    top_left_label: int = 2,\n    bottom_right_label: int = 3,\n) -> Tuple[np.array, np.array]:\n    """\n    Sample a noised version of the top left and bottom right corners of a given `bbox`\n\n    Inputs:\n    - masks: [B, 1, H,W] boxes, dtype=torch.Tensor\n    - noise: noise as a fraction of box width and height, dtype=float\n    - noise_bound: maximum amount of noise (in pure pixesl), dtype=int\n\n    Returns:\n    - box_coords: [B, num_pt, 2], contains (x, y) coordinates of top left and bottom right box corners, dtype=torch.float\n    - box_labels: [B, num_pt], label 2 is reserverd for top left and 3 for bottom right corners, dtype=torch.int32\n    """\n    device = masks.device\n    box_coords = mask_to_box(masks)\n    B, _, H, W = masks.shape\n    box_labels = torch.tensor(\n        [top_left_label, bottom_right_label], dtype=torch.int, device=device\n    ).repeat(B)\n    if noise > 0.0:\n        if not isinstance(noise_bound, torch.Tensor):\n            noise_bound = torch.tensor(noise_bound, device=device)\n        bbox_w = box_coords[..., 2] - box_coords[..., 0]\n        bbox_h = box_coords[..., 3] - box_coords[..., 1]\n        max_dx = torch.min(bbox_w * noise, noise_bound)\n        max_dy = torch.min(bbox_h * noise, noise_bound)\n        box_noise = 2 * torch.rand(B, 1, 4, device=device) - 1\n        box_noise = box_noise * torch.stack((max_dx, max_dy, max_dx, max_dy), dim=-1)\n\n        box_coords = box_coords + box_noise\n        img_bounds = (\n            torch.tensor([W, H, W, H], device=device) - 1\n        )  # uncentered pixel coords\n        box_coords.clamp_(torch.zeros_like(img_bounds), img_bounds)  # In place clamping\n\n    box_coords = box_coords.reshape(-1, 2, 2)  # always 2 points\n    box_labels = box_labels.reshape(-1, 2)\n    return box_coords, box_labels\n\n\ndef sample_random_points_from_errors(gt_masks, pred_masks, num_pt=1):\n    """\n    Sample `num_pt` random points (along with their labels) independently from the error regions.\n\n    Inputs:\n    - gt_masks: [B, 1, H_im, W_im] masks, dtype=torch.bool\n    - pred_masks: [B, 1, H_im, W_im] masks, dtype=torch.bool or None\n    - num_pt: int, number of points to sample independently for each of the B error maps\n\n    Outputs:\n    - points: [B, num_pt, 2], dtype=torch.float, contains (x, y) coordinates of each sampled point\n    - labels: [B, num_pt], dtype=torch.int32, where 1 means positive clicks and 0 means\n      negative clicks\n    """\n    if pred_masks is None:  # if pred_masks is not provided, treat it as empty\n        pred_masks = torch.zeros_like(gt_masks)\n    assert gt_masks.dtype == torch.bool and gt_masks.size(1) == 1\n    assert pred_masks.dtype == torch.bool and pred_masks.shape == gt_masks.shape\n    assert num_pt >= 0\n\n    B, _, H_im, W_im = gt_masks.shape\n    device = gt_masks.device\n\n    # false positive region, a new point sampled in this region should have\n    # negative label to correct the FP error\n    fp_masks = ~gt_masks & pred_masks\n    # false negative region, a new point sampled in this region should have\n    # positive label to correct the FN error\n    fn_masks = gt_masks & ~pred_masks\n    # whether the prediction completely match the ground-truth on each mask\n    all_correct = torch.all((gt_masks == pred_masks).flatten(2), dim=2)\n    all_correct = all_correct[..., None, None]\n\n    # channel 0 is FP map, while channel 1 is FN map\n    pts_noise = torch.rand(B, num_pt, H_im, W_im, 2, device=device)\n    # sample a negative new click from FP region or a positive new click\n    # from FN region, depend on where the maximum falls,\n    # and in case the predictions are all correct (no FP or FN), we just\n    # sample a negative click from the background region\n    pts_noise[..., 0] *= fp_masks | (all_correct & ~gt_masks)\n    pts_noise[..., 1] *= fn_masks\n    pts_idx = pts_noise.flatten(2).argmax(dim=2)\n    labels = (pts_idx % 2).to(torch.int32)\n    pts_idx = pts_idx // 2\n    pts_x = pts_idx % W_im\n    pts_y = pts_idx // W_im\n    points = torch.stack([pts_x, pts_y], dim=2).to(torch.float)\n    return points, labels\n\n\ndef sample_one_point_from_error_center(gt_masks, pred_masks, padding=True):\n    """\n    Sample 1 random point (along with its label) from the center of each error region,\n    that is, the point with the largest distance to the boundary of each error region.\n    This is the RITM sampling method from https://github.com/saic-vul/ritm_interactive_segmentation/blob/master/isegm/inference/clicker.py\n\n    Inputs:\n    - gt_masks: [B, 1, H_im, W_im] masks, dtype=torch.bool\n    - pred_masks: [B, 1, H_im, W_im] masks, dtype=torch.bool or None\n    - padding: if True, pad with boundary of 1 px for distance transform\n\n    Outputs:\n    - points: [B, 1, 2], dtype=torch.float, contains (x, y) coordinates of each sampled point\n    - labels: [B, 1], dtype=torch.int32, where 1 means positive clicks and 0 means negative clicks\n    """\n    import cv2\n\n    if pred_masks is None:\n        pred_masks = torch.zeros_like(gt_masks)\n    assert gt_masks.dtype == torch.bool and gt_masks.size(1) == 1\n    assert pred_masks.dtype == torch.bool and pred_masks.shape == gt_masks.shape\n\n    B, _, _, W_im = gt_masks.shape\n    device = gt_masks.device\n\n    # false positive region, a new point sampled in this region should have\n    # negative label to correct the FP error\n    fp_masks = ~gt_masks & pred_masks\n    # false negative region, a new point sampled in this region should have\n    # positive label to correct the FN error\n    fn_masks = gt_masks & ~pred_masks\n\n    fp_masks = fp_masks.cpu().numpy()\n    fn_masks = fn_masks.cpu().numpy()\n    points = torch.zeros(B, 1, 2, dtype=torch.float)\n    labels = torch.ones(B, 1, dtype=torch.int32)\n    for b in range(B):\n        fn_mask = fn_masks[b, 0]\n        fp_mask = fp_masks[b, 0]\n        if padding:\n            fn_mask = np.pad(fn_mask, ((1, 1), (1, 1)), "constant")\n            fp_mask = np.pad(fp_mask, ((1, 1), (1, 1)), "constant")\n        # compute the distance of each point in FN/FP region to its boundary\n        fn_mask_dt = cv2.distanceTransform(fn_mask.astype(np.uint8), cv2.DIST_L2, 0)\n        fp_mask_dt = cv2.distanceTransform(fp_mask.astype(np.uint8), cv2.DIST_L2, 0)\n        if padding:\n            fn_mask_dt = fn_mask_dt[1:-1, 1:-1]\n            fp_mask_dt = fp_mask_dt[1:-1, 1:-1]\n\n        # take the point in FN/FP region with the largest distance to its boundary\n        fn_mask_dt_flat = fn_mask_dt.reshape(-1)\n        fp_mask_dt_flat = fp_mask_dt.reshape(-1)\n        fn_argmax = np.argmax(fn_mask_dt_flat)\n        fp_argmax = np.argmax(fp_mask_dt_flat)\n        is_positive = fn_mask_dt_flat[fn_argmax] > fp_mask_dt_flat[fp_argmax]\n        pt_idx = fn_argmax if is_positive else fp_argmax\n        points[b, 0, 0] = pt_idx % W_im  # x\n        points[b, 0, 1] = pt_idx // W_im  # y\n        labels[b, 0] = int(is_positive)\n\n    points = points.to(device)\n    labels = labels.to(device)\n    return points, labels\n\n\ndef get_next_point(gt_masks, pred_masks, method):\n    if method == "uniform":\n        return sample_random_points_from_errors(gt_masks, pred_masks)\n    elif method == "center":\n        return sample_one_point_from_error_center(gt_masks, pred_masks)\n    else:\n        raise ValueError(f"unknown sampling method {method}")\n', '_shared_test_resources/code/EdgeTAM/sam2/modeling/__init__.py': '# Copyright (c) Meta Platforms, Inc. and affiliates.\n# All rights reserved.\n\n# This source code is licensed under the license found in the\n# LICENSE file in the root directory of this source tree.\n', '_shared_test_resources/code/EdgeTAM/sam2/modeling/position_encoding.py': '# Copyright (c) Meta Platforms, Inc. and affiliates.\n# All rights reserved.\n\n# This source code is licensed under the license found in the\n# LICENSE file in the root directory of this source tree.\n\nimport math\nfrom typing import Any, Optional, Tuple\n\nimport numpy as np\n\nimport torch\nfrom torch import nn\n\n\nclass PositionEmbeddingSine(nn.Module):\n    """\n    This is a more standard version of the position embedding, very similar to the one\n    used by the Attention Is All You Need paper, generalized to work on images.\n    """\n\n    def __init__(\n        self,\n        num_pos_feats,\n        temperature: int = 10000,\n        normalize: bool = True,\n        scale: Optional[float] = None,\n    ):\n        super().__init__()\n        assert num_pos_feats % 2 == 0, "Expecting even model width"\n        self.num_pos_feats = num_pos_feats // 2\n        self.temperature = temperature\n        self.normalize = normalize\n        if scale is not None and normalize is False:\n            raise ValueError("normalize should be True if scale is passed")\n        if scale is None:\n            scale = 2 * math.pi\n        self.scale = scale\n\n        self.cache = {}\n\n    def _encode_xy(self, x, y):\n        # The positions are expected to be normalized\n        assert len(x) == len(y) and x.ndim == y.ndim == 1\n        x_embed = x * self.scale\n        y_embed = y * self.scale\n\n        dim_t = torch.arange(self.num_pos_feats, dtype=torch.float32, device=x.device)\n        dim_t = self.temperature ** (2 * (dim_t // 2) / self.num_pos_feats)\n\n        pos_x = x_embed[:, None] / dim_t\n        pos_y = y_embed[:, None] / dim_t\n        pos_x = torch.stack(\n            (pos_x[:, 0::2].sin(), pos_x[:, 1::2].cos()), dim=2\n        ).flatten(1)\n        pos_y = torch.stack(\n            (pos_y[:, 0::2].sin(), pos_y[:, 1::2].cos()), dim=2\n        ).flatten(1)\n        return pos_x, pos_y\n\n    @torch.no_grad()\n    def encode_boxes(self, x, y, w, h):\n        pos_x, pos_y = self._encode_xy(x, y)\n        pos = torch.cat((pos_y, pos_x, h[:, None], w[:, None]), dim=1)\n        return pos\n\n    encode = encode_boxes  # Backwards compatibility\n\n    @torch.no_grad()\n    def encode_points(self, x, y, labels):\n        (bx, nx), (by, ny), (bl, nl) = x.shape, y.shape, labels.shape\n        assert bx == by and nx == ny and bx == bl and nx == nl\n        pos_x, pos_y = self._encode_xy(x.flatten(), y.flatten())\n        pos_x, pos_y = pos_x.reshape(bx, nx, -1), pos_y.reshape(by, ny, -1)\n        pos = torch.cat((pos_y, pos_x, labels[:, :, None]), dim=2)\n        return pos\n\n    @torch.no_grad()\n    def forward(self, x: torch.Tensor):\n        cache_key = (x.shape[-2], x.shape[-1])\n        if cache_key in self.cache:\n            return self.cache[cache_key][None].repeat(x.shape[0], 1, 1, 1)\n        y_embed = (\n            torch.arange(1, x.shape[-2] + 1, dtype=torch.float32, device=x.device)\n            .view(1, -1, 1)\n            .repeat(x.shape[0], 1, x.shape[-1])\n        )\n        x_embed = (\n            torch.arange(1, x.shape[-1] + 1, dtype=torch.float32, device=x.device)\n            .view(1, 1, -1)\n            .repeat(x.shape[0], x.shape[-2], 1)\n        )\n\n        if self.normalize:\n            eps = 1e-6\n            y_embed = y_embed / (y_embed[:, -1:, :] + eps) * self.scale\n            x_embed = x_embed / (x_embed[:, :, -1:] + eps) * self.scale\n\n        dim_t = torch.arange(self.num_pos_feats, dtype=torch.float32, device=x.device)\n        dim_t = self.temperature ** (2 * (dim_t // 2) / self.num_pos_feats)\n\n        pos_x = x_embed[:, :, :, None] / dim_t\n        pos_y = y_embed[:, :, :, None] / dim_t\n        pos_x = torch.stack(\n            (pos_x[:, :, :, 0::2].sin(), pos_x[:, :, :, 1::2].cos()), dim=4\n        ).flatten(3)\n        pos_y = torch.stack(\n            (pos_y[:, :, :, 0::2].sin(), pos_y[:, :, :, 1::2].cos()), dim=4\n        ).flatten(3)\n        pos = torch.cat((pos_y, pos_x), dim=3).permute(0, 3, 1, 2)\n        self.cache[cache_key] = pos[0]\n        return pos\n\n\nclass PositionEmbeddingRandom(nn.Module):\n    """\n    Positional encoding using random spatial frequencies.\n    """\n\n    def __init__(self, num_pos_feats: int = 64, scale: Optional[float] = None) -> None:\n        super().__init__()\n        if scale is None or scale <= 0.0:\n            scale = 1.0\n        self.register_buffer(\n            "positional_encoding_gaussian_matrix",\n            scale * torch.randn((2, num_pos_feats)),\n        )\n\n    def _pe_encoding(self, coords: torch.Tensor) -> torch.Tensor:\n        """Positionally encode points that are normalized to [0,1]."""\n        # assuming coords are in [0, 1]^2 square and have d_1 x ... x d_n x 2 shape\n        coords = 2 * coords - 1\n        coords = coords @ self.positional_encoding_gaussian_matrix\n        coords = 2 * np.pi * coords\n        # outputs d_1 x ... x d_n x C shape\n        return torch.cat([torch.sin(coords), torch.cos(coords)], dim=-1)\n\n    def forward(self, size: Tuple[int, int]) -> torch.Tensor:\n        """Generate positional encoding for a grid of the specified size."""\n        h, w = size\n        device: Any = self.positional_encoding_gaussian_matrix.device\n        grid = torch.ones((h, w), device=device, dtype=torch.float32)\n        y_embed = grid.cumsum(dim=0) - 0.5\n        x_embed = grid.cumsum(dim=1) - 0.5\n        y_embed = y_embed / h\n        x_embed = x_embed / w\n\n        pe = self._pe_encoding(torch.stack([x_embed, y_embed], dim=-1))\n        return pe.permute(2, 0, 1)  # C x H x W\n\n    def forward_with_coords(\n        self, coords_input: torch.Tensor, image_size: Tuple[int, int]\n    ) -> torch.Tensor:\n        """Positionally encode points that are not normalized to [0,1]."""\n        coords = coords_input.clone()\n        coords[:, :, 0] = coords[:, :, 0] / image_size[1]\n        coords[:, :, 1] = coords[:, :, 1] / image_size[0]\n        return self._pe_encoding(coords.to(torch.float))  # B x N x C\n\n\n# Rotary Positional Encoding, adapted from:\n# 1. https://github.com/meta-llama/codellama/blob/main/llama/model.py\n# 2. https://github.com/naver-ai/rope-vit\n# 3. https://github.com/lucidrains/rotary-embedding-torch\n\n\ndef init_t_xy(end_x: int, end_y: int):\n    t = torch.arange(end_x * end_y, dtype=torch.float32)\n    t_x = (t % end_x).float()\n    t_y = torch.div(t, end_x, rounding_mode="floor").float()\n    return t_x, t_y\n\n\ndef compute_axial_cis(dim: int, end_x: int, end_y: int, theta: float = 10000.0):\n    freqs_x = 1.0 / (theta ** (torch.arange(0, dim, 4)[: (dim // 4)].float() / dim))\n    freqs_y = 1.0 / (theta ** (torch.arange(0, dim, 4)[: (dim // 4)].float() / dim))\n\n    t_x, t_y = init_t_xy(end_x, end_y)\n    freqs_x = torch.outer(t_x, freqs_x)\n    freqs_y = torch.outer(t_y, freqs_y)\n    freqs_cis_x = torch.polar(torch.ones_like(freqs_x), freqs_x)\n    freqs_cis_y = torch.polar(torch.ones_like(freqs_y), freqs_y)\n    return torch.cat([freqs_cis_x, freqs_cis_y], dim=-1)\n\n\ndef reshape_for_broadcast(freqs_cis: torch.Tensor, x: torch.Tensor):\n    ndim = x.ndim\n    assert 0 <= 1 < ndim\n    assert freqs_cis.shape == (x.shape[-2], x.shape[-1])\n    shape = [d if i >= ndim - 2 else 1 for i, d in enumerate(x.shape)]\n    return freqs_cis.view(*shape)\n\n\ndef apply_rotary_enc(\n    xq: torch.Tensor,\n    xk: torch.Tensor,\n    freqs_cis: torch.Tensor,\n    repeat_freqs_k: bool = False,\n):\n    xq_ = torch.view_as_complex(xq.float().reshape(*xq.shape[:-1], -1, 2))\n    xk_ = (\n        torch.view_as_complex(xk.float().reshape(*xk.shape[:-1], -1, 2))\n        if xk.shape[-2] != 0\n        else None\n    )\n    freqs_cis = reshape_for_broadcast(freqs_cis, xq_)\n    xq_out = torch.view_as_real(xq_ * freqs_cis).flatten(3)\n    if xk_ is None:\n        # no keys to rotate, due to dropout\n        return xq_out.type_as(xq).to(xq.device), xk\n    # repeat freqs along seq_len dim to match k seq_len\n    if repeat_freqs_k:\n        r = xk_.shape[-2] // xq_.shape[-2]\n        if freqs_cis.is_cuda:\n            freqs_cis = freqs_cis.repeat(*([1] * (freqs_cis.ndim - 2)), r, 1)\n        else:\n            # torch.repeat on complex numbers may not be supported on non-CUDA devices\n            # (freqs_cis has 4 dims and we repeat on dim 2) so we use expand + flatten\n            freqs_cis = freqs_cis.unsqueeze(2).expand(-1, -1, r, -1, -1).flatten(2, 3)\n    xk_out = torch.view_as_real(xk_ * freqs_cis).flatten(3)\n    return xq_out.type_as(xq).to(xq.device), xk_out.type_as(xk).to(xk.device)\n\n\ndef apply_rotary_enc_v2(\n    x: torch.Tensor,\n    freqs_cis: torch.Tensor,\n    repeat_freqs: int,\n):\n    # no keys to rotate, due to dropout\n    if repeat_freqs == 0:\n        assert x.shape[-2] == 0\n    if x.shape[-2] == 0:\n        return x\n\n    B, N_heads, N_tokens, C_per_head = x.shape\n    if N_tokens == freqs_cis.shape[0] * repeat_freqs:\n        x_rope = x\n        x_no_rope = None\n    else:\n        rope_tokens = freqs_cis.shape[0]\n        no_rope_tokens = N_tokens // repeat_freqs - rope_tokens\n        x = x.view(B, N_heads, repeat_freqs, N_tokens // repeat_freqs, C_per_head)\n        x_rope = x[..., no_rope_tokens:, :].reshape(B, N_heads, -1, C_per_head)\n        x_no_rope = x[..., :no_rope_tokens, :].reshape(B, N_heads, -1, C_per_head)\n\n    x_rope = torch.view_as_complex(x_rope.float().reshape(*x_rope.shape[:-1], -1, 2))\n    if repeat_freqs > 1:\n        x_one_frame = x_rope[..., : x_rope.shape[-2] // repeat_freqs, :]\n        freqs_cis = reshape_for_broadcast(freqs_cis, x_one_frame)\n    else:\n        freqs_cis = reshape_for_broadcast(freqs_cis, x_rope)\n    # repeat freqs along seq_len dim to match k seq_len\n    if repeat_freqs > 1:\n        if freqs_cis.is_cuda:\n            freqs_cis = freqs_cis.repeat(*([1] * (freqs_cis.ndim - 2)), repeat_freqs, 1)\n        else:\n            # torch.repeat on complex numbers may not be supported on non-CUDA devices\n            # (freqs_cis has 4 dims and we repeat on dim 2) so we use expand + flatten\n            freqs_cis = (\n                freqs_cis.unsqueeze(2)\n                .expand(-1, -1, repeat_freqs, -1, -1)\n                .flatten(2, 3)\n            )\n    x_out = torch.view_as_real(x_rope * freqs_cis).flatten(3)\n    x_out = x_out.type_as(x).to(x.device)\n\n    if x_no_rope is not None:\n        x_out = x_out.view(B, N_heads, repeat_freqs, -1, C_per_head)\n        x_no_rope = x_no_rope.view(B, N_heads, repeat_freqs, -1, C_per_head)\n        x_out = torch.cat((x_no_rope, x_out), dim=3).view(\n            B, N_heads, N_tokens, C_per_head\n        )\n    return x_out\n', '_shared_test_resources/code/EdgeTAM/sam2/modeling/memory_encoder.py': '# Copyright (c) Meta Platforms, Inc. and affiliates.\n# All rights reserved.\n\n# This source code is licensed under the license found in the\n# LICENSE file in the root directory of this source tree.\n\nimport math\nfrom typing import Tuple\n\nimport torch\nimport torch.nn as nn\nimport torch.nn.functional as F\n\nfrom sam2.modeling.sam2_utils import DropPath, get_clones, LayerNorm2d\n\n\nclass MaskDownSampler(nn.Module):\n    """\n    Progressively downsample a mask by total_stride, each time by stride.\n    Note that LayerNorm is applied per *token*, like in ViT.\n\n    With each downsample (by a factor stride**2), channel capacity increases by the same factor.\n    In the end, we linearly project to embed_dim channels.\n    """\n\n    def __init__(\n        self,\n        embed_dim=256,\n        kernel_size=4,\n        stride=4,\n        padding=0,\n        total_stride=16,\n        activation=nn.GELU,\n    ):\n        super().__init__()\n        num_layers = int(math.log2(total_stride) // math.log2(stride))\n        assert stride**num_layers == total_stride\n        self.encoder = nn.Sequential()\n        mask_in_chans, mask_out_chans = 1, 1\n        for _ in range(num_layers):\n            mask_out_chans = mask_in_chans * (stride**2)\n            self.encoder.append(\n                nn.Conv2d(\n                    mask_in_chans,\n                    mask_out_chans,\n                    kernel_size=kernel_size,\n                    stride=stride,\n                    padding=padding,\n                )\n            )\n            self.encoder.append(LayerNorm2d(mask_out_chans))\n            self.encoder.append(activation())\n            mask_in_chans = mask_out_chans\n\n        self.encoder.append(nn.Conv2d(mask_out_chans, embed_dim, kernel_size=1))\n\n    def forward(self, x):\n        return self.encoder(x)\n\n\n# Lightly adapted from ConvNext (https://github.com/facebookresearch/ConvNeXt)\nclass CXBlock(nn.Module):\n    r"""ConvNeXt Block. There are two equivalent implementations:\n    (1) DwConv -> LayerNorm (channels_first) -> 1x1 Conv -> GELU -> 1x1 Conv; all in (N, C, H, W)\n    (2) DwConv -> Permute to (N, H, W, C); LayerNorm (channels_last) -> Linear -> GELU -> Linear; Permute back\n    We use (2) as we find it slightly faster in PyTorch\n\n    Args:\n        dim (int): Number of input channels.\n        drop_path (float): Stochastic depth rate. Default: 0.0\n        layer_scale_init_value (float): Init value for Layer Scale. Default: 1e-6.\n    """\n\n    def __init__(\n        self,\n        dim,\n        kernel_size=7,\n        padding=3,\n        drop_path=0.0,\n        layer_scale_init_value=1e-6,\n        use_dwconv=True,\n    ):\n        super().__init__()\n        self.dwconv = nn.Conv2d(\n            dim,\n            dim,\n            kernel_size=kernel_size,\n            padding=padding,\n            groups=dim if use_dwconv else 1,\n        )  # depthwise conv\n        self.norm = LayerNorm2d(dim, eps=1e-6)\n        self.pwconv1 = nn.Linear(\n            dim, 4 * dim\n        )  # pointwise/1x1 convs, implemented with linear layers\n        self.act = nn.GELU()\n        self.pwconv2 = nn.Linear(4 * dim, dim)\n        self.gamma = (\n            nn.Parameter(layer_scale_init_value * torch.ones((dim)), requires_grad=True)\n            if layer_scale_init_value > 0\n            else None\n        )\n        self.drop_path = DropPath(drop_path) if drop_path > 0.0 else nn.Identity()\n\n    def forward(self, x):\n        input = x\n        x = self.dwconv(x)\n        x = self.norm(x)\n        x = x.permute(0, 2, 3, 1)  # (N, C, H, W) -> (N, H, W, C)\n        x = self.pwconv1(x)\n        x = self.act(x)\n        x = self.pwconv2(x)\n        if self.gamma is not None:\n            x = self.gamma * x\n        x = x.permute(0, 3, 1, 2)  # (N, H, W, C) -> (N, C, H, W)\n\n        x = input + self.drop_path(x)\n        return x\n\n\nclass Fuser(nn.Module):\n    def __init__(self, layer, num_layers, dim=None, input_projection=False):\n        super().__init__()\n        self.proj = nn.Identity()\n        self.layers = get_clones(layer, num_layers)\n\n        if input_projection:\n            assert dim is not None\n            self.proj = nn.Conv2d(dim, dim, kernel_size=1)\n\n    def forward(self, x):\n        # normally x: (N, C, H, W)\n        x = self.proj(x)\n        for layer in self.layers:\n            x = layer(x)\n        return x\n\n\nclass MemoryEncoder(nn.Module):\n    def __init__(\n        self,\n        out_dim,\n        mask_downsampler,\n        fuser,\n        position_encoding,\n        in_dim=256,  # in_dim of pix_feats\n    ):\n        super().__init__()\n\n        self.mask_downsampler = mask_downsampler\n\n        self.pix_feat_proj = nn.Conv2d(in_dim, in_dim, kernel_size=1)\n        self.fuser = fuser\n        self.position_encoding = position_encoding\n        self.out_proj = nn.Identity()\n        if out_dim != in_dim:\n            self.out_proj = nn.Conv2d(in_dim, out_dim, kernel_size=1)\n\n    def forward(\n        self,\n        pix_feat: torch.Tensor,\n        masks: torch.Tensor,\n        skip_mask_sigmoid: bool = False,\n    ) -> Tuple[torch.Tensor, torch.Tensor]:\n        ## Process masks\n        # sigmoid, so that less domain shift from gt masks which are bool\n        if not skip_mask_sigmoid:\n            masks = F.sigmoid(masks)\n        masks = self.mask_downsampler(masks)\n\n        ## Fuse pix_feats and downsampled masks\n        # in case the visual features are on CPU, cast them to CUDA\n        pix_feat = pix_feat.to(masks.device)\n\n        x = self.pix_feat_proj(pix_feat)\n        x = x + masks\n        x = self.fuser(x)\n        x = self.out_proj(x)\n\n        pos = self.position_encoding(x).to(x.dtype)\n\n        return {"vision_features": x, "vision_pos_enc": [pos]}\n', '_shared_test_resources/code/EdgeTAM/sam2/modeling/perceiver.py': '# Copyright (c) Meta Platforms, Inc. and affiliates.\n# All rights reserved.\n\n# This source code is licensed under the license found in the\n# LICENSE file in the root directory of this source tree.\n\nimport math\n\nimport torch\nimport torch.nn as nn\nimport torch.nn.functional as F\n\n\ndef FeedForward(dim, mult=4):\n    inner_dim = int(dim * mult)\n    return nn.Sequential(\n        nn.LayerNorm(dim),\n        nn.Linear(dim, inner_dim, bias=False),\n        nn.GELU(),\n        nn.Linear(inner_dim, dim, bias=False),\n    )\n\n\nclass PerceiverAttention(nn.Module):\n    def __init__(\n        self, *, dim, dim_head=64, heads=8, dropout_p=0.05, concat_kv_latents=True\n    ):\n        super().__init__()\n        self.scale = dim_head**-0.5\n        self.heads = heads\n        inner_dim = dim_head * heads\n\n        self.norm_x = nn.LayerNorm(dim)\n        self.norm_latents = nn.LayerNorm(dim)\n\n        self.to_q = nn.Linear(dim, inner_dim, bias=False)\n        self.to_kv = nn.Linear(dim, inner_dim * 2, bias=False)\n        self.to_out = nn.Linear(inner_dim, dim, bias=False)\n\n        self.dropout_p = dropout_p\n        self.concat_kv_latents = concat_kv_latents\n\n    def _separate_heads(self, x: torch.Tensor, num_heads: int) -> torch.Tensor:\n        b, n, c = x.shape\n        x = x.reshape(b, n, num_heads, c // num_heads)\n        return x.transpose(1, 2)  # B x N_heads x N_tokens x C_per_head\n\n    def _recombine_heads(self, x: torch.Tensor) -> torch.Tensor:\n        b, n_heads, n_tokens, c_per_head = x.shape\n        x = x.transpose(1, 2)\n        return x.reshape(b, n_tokens, n_heads * c_per_head)  # B x N_tokens x C\n\n    def forward(self, latents, x, pos=None):\n        latents = self.norm_latents(latents)\n        x = self.norm_x(x)\n\n        q = self.to_q(latents)\n\n        # the paper differs from Perceiver in which they also concat the key / values derived from the latents to be attended to\n        if self.concat_kv_latents:\n            kv_input = torch.cat((x, latents), dim=-2)\n        else:\n            kv_input = x\n        k, v = self.to_kv(kv_input).chunk(2, dim=-1)\n\n        q = self._separate_heads(q, self.heads)\n        k = self._separate_heads(k, self.heads)\n        v = self._separate_heads(v, self.heads)\n\n        if pos is not None:\n            assert not self.concat_kv_latents\n            pos = self._separate_heads(pos, self.heads)\n            k, v = k + pos, v + pos\n\n        out = F.scaled_dot_product_attention(\n            q,\n            k,\n            v,\n            attn_mask=None,\n            dropout_p=self.dropout_p if self.training else 0.0,\n        )\n        out = self._recombine_heads(out)\n        return self.to_out(out)\n\n\nclass Attention(nn.Module):\n    def __init__(self, *, dim, dim_head=64, heads=8, dropout_p=0.05):\n        super().__init__()\n        self.scale = dim_head**-0.5\n        self.heads = heads\n        inner_dim = dim_head * heads\n\n        self.norm = nn.LayerNorm(dim)\n\n        self.to_q = nn.Linear(dim, inner_dim, bias=False)\n        self.to_kv = nn.Linear(dim, inner_dim * 2, bias=False)\n        self.to_out = nn.Linear(inner_dim, dim, bias=False)\n\n        self.dropout_p = dropout_p\n\n    def _separate_heads(self, x: torch.Tensor, num_heads: int) -> torch.Tensor:\n        b, n, c = x.shape\n        x = x.reshape(b, n, num_heads, c // num_heads)\n        return x.transpose(1, 2)  # B x N_heads x N_tokens x C_per_head\n\n    def _recombine_heads(self, x: torch.Tensor) -> torch.Tensor:\n        b, n_heads, n_tokens, c_per_head = x.shape\n        x = x.transpose(1, 2)\n        return x.reshape(b, n_tokens, n_heads * c_per_head)  # B x N_tokens x C\n\n    def forward(self, x):\n        x = self.norm(x)\n\n        q = self.to_q(x)\n        k, v = self.to_kv(x).chunk(2, dim=-1)\n\n        q = self._separate_heads(q, self.heads)\n        k = self._separate_heads(k, self.heads)\n        v = self._separate_heads(v, self.heads)\n\n        out = F.scaled_dot_product_attention(\n            q,\n            k,\n            v,\n            attn_mask=None,\n            dropout_p=self.dropout_p if self.training else 0.0,\n        )\n        out = self._recombine_heads(out)\n        return self.to_out(out)\n\n\nclass PerceiverEncoderLayer(nn.Module):\n    def __init__(\n        self,\n        dim,\n        dim_head=64,\n        heads=8,\n        ff_mult=4,\n        hidden_dropout_p=0.0,\n        attention_dropout_p=0.0,\n        concat_kv_latents=False,\n        use_self_attn=False,\n    ):\n        super().__init__()\n        self.attn = PerceiverAttention(\n            dim=dim,\n            dim_head=dim_head,\n            heads=heads,\n            dropout_p=attention_dropout_p,\n            concat_kv_latents=concat_kv_latents,\n        )\n        self.ff = FeedForward(dim=dim, mult=ff_mult)\n        self.dropout = nn.Dropout(hidden_dropout_p)\n        self.use_self_attn = use_self_attn\n        if use_self_attn:\n            self.self_attn = Attention(\n                dim=dim,\n                dim_head=dim_head,\n                heads=heads,\n                dropout_p=attention_dropout_p,\n            )\n            self.self_ff = FeedForward(dim=dim, mult=ff_mult)\n\n    def forward(self, latents, x, pos=None):\n        latents = self.attn(latents, x, pos) + latents\n        latents = self.dropout(latents)\n        latents = self.ff(latents) + latents\n        if self.use_self_attn:\n            latents = self.self_attn(latents) + latents\n            latents = self.self_ff(latents) + latents\n        return latents\n\n\ndef window_partition(x, window_size):\n    """\n    Args:\n        x: (B, H, W, C)\n        window_size (int): window size\n\n    Returns:\n        windows: (num_windows*B, window_size, window_size, C)\n    """\n    B, H, W, C = x.shape\n    x = x.view(B, H // window_size, window_size, W // window_size, window_size, C)\n    windows = (\n        x.permute(0, 1, 3, 2, 4, 5).contiguous().view(-1, window_size, window_size, C)\n    )\n    return windows\n\n\ndef window_reverse(windows, window_size, H, W):\n    """\n    Args:\n        windows: (num_windows*B, window_size, window_size, C)\n        window_size (int): Window size\n        H (int): Height of image\n        W (int): Width of image\n\n    Returns:\n        x: (B, H, W, C)\n    """\n    B = int(windows.shape[0] / (H * W / window_size / window_size))\n    x = windows.view(\n        B, H // window_size, W // window_size, window_size, window_size, -1\n    )\n    x = x.permute(0, 1, 3, 2, 4, 5).contiguous().view(B, H, W, -1)\n    return x\n\n\nclass PerceiverResampler(nn.Module):\n    def __init__(\n        self,\n        *,\n        dim,\n        depth,\n        dim_head=64,\n        heads=1,\n        num_latents=-1,\n        num_latents_2d=-1,\n        ff_mult=4,\n        hidden_dropout_p=0.1,\n        attention_dropout_p=0.05,\n        pos_enc_at_key_value=False,\n        concat_kv_latents=False,\n        position_encoding=None,\n        use_self_attn=False,\n        **kwargs,\n    ):\n        super().__init__()\n        self.num_latents = num_latents\n        self.num_latents_2d = num_latents_2d\n\n        if num_latents > 0:\n            self.latents = nn.Parameter(torch.randn(num_latents, dim))\n        if num_latents_2d > 0:\n            self.latents_2d = nn.Parameter(torch.randn(num_latents_2d, dim))\n        self.position_encoding = position_encoding\n\n        self.layers = nn.ModuleList([])\n        for _ in range(depth):\n            self.layers.append(\n                PerceiverEncoderLayer(\n                    dim=dim,\n                    dim_head=dim_head,\n                    heads=heads,\n                    ff_mult=ff_mult,\n                    hidden_dropout_p=hidden_dropout_p,\n                    attention_dropout_p=attention_dropout_p,\n                    concat_kv_latents=concat_kv_latents,\n                    use_self_attn=use_self_attn,\n                ),\n            )\n\n        self.norm = nn.LayerNorm(dim)\n        self.pos_enc_at_key_value = pos_enc_at_key_value\n\n    def forward(self, x, pos=None):\n        out_latents = []\n        out_pos = []\n        if self.num_latents > 0:\n            latents_1d, pos_1d = self.forward_1d(x, pos)\n            out_latents.append(latents_1d)\n            out_pos.append(pos_1d)\n        if self.num_latents_2d > 0:\n            latents_2d, pos_2d = self.forward_2d(x)\n            out_latents.append(latents_2d)\n            out_pos.append(pos_2d)\n\n        latents = torch.concat(out_latents, dim=1)\n        if pos is not None:\n            pos = torch.concat(out_pos, dim=1)\n\n        return latents, pos\n\n    def forward_1d(self, x, pos):\n        latents = self.latents.unsqueeze(0).expand(x.shape[0], -1, -1)\n        x = x.permute(0, 2, 3, 1).flatten(1, 2)\n\n        if not self.pos_enc_at_key_value:\n            _pos = None\n        if pos is not None:\n            _pos = pos.permute(0, 2, 3, 1).flatten(1, 2)\n        else:\n            _pos = None\n\n        for layer in self.layers:\n            latents = layer(latents, x, _pos)\n\n        if pos is not None:\n            pos = torch.zeros_like(latents)\n\n        latents = self.norm(latents)\n        return latents, pos\n\n    def forward_2d(self, x):\n        B, C, H, W = x.shape\n\n        # expand() produces a non-contiguous view in current PyTorch releases;\n        # reshape preserves the intended flattened batch layout.\n        latents_2d = self.latents_2d.unsqueeze(0).expand(B, -1, -1).reshape(-1, 1, C)\n\n        num_window = int(math.sqrt(self.num_latents_2d))\n        window_size = H // num_window\n        x = x.permute(0, 2, 3, 1)\n\n        x = window_partition(x, window_size)\n        x = x.flatten(1, 2)\n\n        for layer in self.layers:\n            latents_2d = layer(latents_2d, x)\n\n        latents_2d = latents_2d.view(B, num_window, num_window, C).permute(0, 3, 1, 2)\n\n        pos_2d = self.position_encoding(latents_2d)\n        pos_2d = pos_2d.permute(0, 2, 3, 1).flatten(1, 2)\n\n        latents_2d = latents_2d.permute(0, 2, 3, 1).flatten(1, 2)\n\n        latents_2d = self.norm(latents_2d)\n\n        return latents_2d, pos_2d\n', '_shared_test_resources/code/EdgeTAM/sam2/modeling/sam/transformer.py': '# Copyright (c) Meta Platforms, Inc. and affiliates.\n# All rights reserved.\n\n# This source code is licensed under the license found in the\n# LICENSE file in the root directory of this source tree.\n\nimport contextlib\nimport math\nimport warnings\nfrom functools import partial\nfrom typing import Tuple, Type\n\nimport torch\nimport torch.nn.functional as F\n\nfrom sam2.modeling.position_encoding import (\n    apply_rotary_enc,\n    apply_rotary_enc_v2,\n    compute_axial_cis,\n)\nfrom sam2.modeling.sam2_utils import MLP\nfrom sam2.utils.misc import get_sdpa_settings\nfrom torch import nn, Tensor\n\nwarnings.simplefilter(action="ignore", category=FutureWarning)\n# Check whether Flash Attention is available (and use it by default)\nOLD_GPU, USE_FLASH_ATTN, MATH_KERNEL_ON = get_sdpa_settings()\n# A fallback setting to allow all available kernels if Flash Attention fails\nALLOW_ALL_KERNELS = False\n\n\ndef sdp_kernel_context(dropout_p):\n    """\n    Get the context for the attention scaled dot-product kernel. We use Flash Attention\n    by default, but fall back to all available kernels if Flash Attention fails.\n    """\n    if ALLOW_ALL_KERNELS:\n        return contextlib.nullcontext()\n\n    return torch.backends.cuda.sdp_kernel(\n        enable_flash=USE_FLASH_ATTN,\n        # if Flash attention kernel is off, then math kernel needs to be enabled\n        enable_math=(OLD_GPU and dropout_p > 0.0) or MATH_KERNEL_ON,\n        enable_mem_efficient=OLD_GPU,\n    )\n\n\nclass TwoWayTransformer(nn.Module):\n    def __init__(\n        self,\n        depth: int,\n        embedding_dim: int,\n        num_heads: int,\n        mlp_dim: int,\n        activation: Type[nn.Module] = nn.ReLU,\n        attention_downsample_rate: int = 2,\n    ) -> None:\n        """\n        A transformer decoder that attends to an input image using\n        queries whose positional embedding is supplied.\n\n        Args:\n          depth (int): number of layers in the transformer\n          embedding_dim (int): the channel dimension for the input embeddings\n          num_heads (int): the number of heads for multihead attention. Must\n            divide embedding_dim\n          mlp_dim (int): the channel dimension internal to the MLP block\n          activation (nn.Module): the activation to use in the MLP block\n        """\n        super().__init__()\n        self.depth = depth\n        self.embedding_dim = embedding_dim\n        self.num_heads = num_heads\n        self.mlp_dim = mlp_dim\n        self.layers = nn.ModuleList()\n\n        for i in range(depth):\n            self.layers.append(\n                TwoWayAttentionBlock(\n                    embedding_dim=embedding_dim,\n                    num_heads=num_heads,\n                    mlp_dim=mlp_dim,\n                    activation=activation,\n                    attention_downsample_rate=attention_downsample_rate,\n                    skip_first_layer_pe=(i == 0),\n                )\n            )\n\n        self.final_attn_token_to_image = Attention(\n            embedding_dim, num_heads, downsample_rate=attention_downsample_rate\n        )\n        self.norm_final_attn = nn.LayerNorm(embedding_dim)\n\n    def forward(\n        self,\n        image_embedding: Tensor,\n        image_pe: Tensor,\n        point_embedding: Tensor,\n    ) -> Tuple[Tensor, Tensor]:\n        """\n        Args:\n          image_embedding (torch.Tensor): image to attend to. Should be shape\n            B x embedding_dim x h x w for any h and w.\n          image_pe (torch.Tensor): the positional encoding to add to the image. Must\n            have the same shape as image_embedding.\n          point_embedding (torch.Tensor): the embedding to add to the query points.\n            Must have shape B x N_points x embedding_dim for any N_points.\n\n        Returns:\n          torch.Tensor: the processed point_embedding\n          torch.Tensor: the processed image_embedding\n        """\n        # BxCxHxW -> BxHWxC == B x N_image_tokens x C\n        bs, c, h, w = image_embedding.shape\n        image_embedding = image_embedding.flatten(2).permute(0, 2, 1)\n        image_pe = image_pe.flatten(2).permute(0, 2, 1)\n\n        # Prepare queries\n        queries = point_embedding\n        keys = image_embedding\n\n        # Apply transformer blocks and final layernorm\n        for layer in self.layers:\n            queries, keys = layer(\n                queries=queries,\n                keys=keys,\n                query_pe=point_embedding,\n                key_pe=image_pe,\n            )\n\n        # Apply the final attention layer from the points to the image\n        q = queries + point_embedding\n        k = keys + image_pe\n        attn_out = self.final_attn_token_to_image(q=q, k=k, v=keys)\n        queries = queries + attn_out\n        queries = self.norm_final_attn(queries)\n\n        return queries, keys\n\n\nclass TwoWayAttentionBlock(nn.Module):\n    def __init__(\n        self,\n        embedding_dim: int,\n        num_heads: int,\n        mlp_dim: int = 2048,\n        activation: Type[nn.Module] = nn.ReLU,\n        attention_downsample_rate: int = 2,\n        skip_first_layer_pe: bool = False,\n    ) -> None:\n        """\n        A transformer block with four layers: (1) self-attention of sparse\n        inputs, (2) cross attention of sparse inputs to dense inputs, (3) mlp\n        block on sparse inputs, and (4) cross attention of dense inputs to sparse\n        inputs.\n\n        Arguments:\n          embedding_dim (int): the channel dimension of the embeddings\n          num_heads (int): the number of heads in the attention layers\n          mlp_dim (int): the hidden dimension of the mlp block\n          activation (nn.Module): the activation of the mlp block\n          skip_first_layer_pe (bool): skip the PE on the first layer\n        """\n        super().__init__()\n        self.self_attn = Attention(embedding_dim, num_heads)\n        self.norm1 = nn.LayerNorm(embedding_dim)\n\n        self.cross_attn_token_to_image = Attention(\n            embedding_dim, num_heads, downsample_rate=attention_downsample_rate\n        )\n        self.norm2 = nn.LayerNorm(embedding_dim)\n\n        self.mlp = MLP(\n            embedding_dim, mlp_dim, embedding_dim, num_layers=2, activation=activation\n        )\n        self.norm3 = nn.LayerNorm(embedding_dim)\n\n        self.norm4 = nn.LayerNorm(embedding_dim)\n        self.cross_attn_image_to_token = Attention(\n            embedding_dim, num_heads, downsample_rate=attention_downsample_rate\n        )\n\n        self.skip_first_layer_pe = skip_first_layer_pe\n\n    def forward(\n        self, queries: Tensor, keys: Tensor, query_pe: Tensor, key_pe: Tensor\n    ) -> Tuple[Tensor, Tensor]:\n        # Self attention block\n        if self.skip_first_layer_pe:\n            queries = self.self_attn(q=queries, k=queries, v=queries)\n        else:\n            q = queries + query_pe\n            attn_out = self.self_attn(q=q, k=q, v=queries)\n            queries = queries + attn_out\n        queries = self.norm1(queries)\n\n        # Cross attention block, tokens attending to image embedding\n        q = queries + query_pe\n        k = keys + key_pe\n        attn_out = self.cross_attn_token_to_image(q=q, k=k, v=keys)\n        queries = queries + attn_out\n        queries = self.norm2(queries)\n\n        # MLP block\n        mlp_out = self.mlp(queries)\n        queries = queries + mlp_out\n        queries = self.norm3(queries)\n\n        # Cross attention block, image embedding attending to tokens\n        q = queries + query_pe\n        k = keys + key_pe\n        attn_out = self.cross_attn_image_to_token(q=k, k=q, v=queries)\n        keys = keys + attn_out\n        keys = self.norm4(keys)\n\n        return queries, keys\n\n\nclass Attention(nn.Module):\n    """\n    An attention layer that allows for downscaling the size of the embedding\n    after projection to queries, keys, and values.\n    """\n\n    def __init__(\n        self,\n        embedding_dim: int,\n        num_heads: int,\n        downsample_rate: int = 1,\n        dropout: float = 0.0,\n        kv_in_dim: int = None,\n    ) -> None:\n        super().__init__()\n        self.embedding_dim = embedding_dim\n        self.kv_in_dim = kv_in_dim if kv_in_dim is not None else embedding_dim\n        self.internal_dim = embedding_dim // downsample_rate\n        self.num_heads = num_heads\n        assert (\n            self.internal_dim % num_heads == 0\n        ), "num_heads must divide embedding_dim."\n\n        self.q_proj = nn.Linear(embedding_dim, self.internal_dim)\n        self.k_proj = nn.Linear(self.kv_in_dim, self.internal_dim)\n        self.v_proj = nn.Linear(self.kv_in_dim, self.internal_dim)\n        self.out_proj = nn.Linear(self.internal_dim, embedding_dim)\n\n        self.dropout_p = dropout\n\n    def _separate_heads(self, x: Tensor, num_heads: int) -> Tensor:\n        b, n, c = x.shape\n        x = x.reshape(b, n, num_heads, c // num_heads)\n        return x.transpose(1, 2)  # B x N_heads x N_tokens x C_per_head\n\n    def _recombine_heads(self, x: Tensor) -> Tensor:\n        b, n_heads, n_tokens, c_per_head = x.shape\n        x = x.transpose(1, 2)\n        return x.reshape(b, n_tokens, n_heads * c_per_head)  # B x N_tokens x C\n\n    def forward(self, q: Tensor, k: Tensor, v: Tensor) -> Tensor:\n        # Input projections\n        q = self.q_proj(q)\n        k = self.k_proj(k)\n        v = self.v_proj(v)\n\n        # Separate into heads\n        q = self._separate_heads(q, self.num_heads)\n        k = self._separate_heads(k, self.num_heads)\n        v = self._separate_heads(v, self.num_heads)\n\n        dropout_p = self.dropout_p if self.training else 0.0\n        # Attention\n        try:\n            with sdp_kernel_context(dropout_p):\n                out = F.scaled_dot_product_attention(q, k, v, dropout_p=dropout_p)\n        except Exception as e:\n            # Fall back to all kernels if the Flash attention kernel fails\n            warnings.warn(\n                f"Flash Attention kernel failed due to: {e}\\nFalling back to all available "\n                f"kernels for scaled_dot_product_attention (which may have a slower speed).",\n                category=UserWarning,\n                stacklevel=2,\n            )\n            global ALLOW_ALL_KERNELS\n            ALLOW_ALL_KERNELS = True\n            out = F.scaled_dot_product_attention(q, k, v, dropout_p=dropout_p)\n\n        out = self._recombine_heads(out)\n        out = self.out_proj(out)\n\n        return out\n\n\nclass RoPEAttention(Attention):\n    """Attention with rotary position encoding."""\n\n    def __init__(\n        self,\n        *args,\n        rope_theta=10000.0,\n        # whether to repeat q rope to match k length\n        # this is needed for cross-attention to memories\n        rope_k_repeat=False,\n        feat_sizes=(32, 32),  # [w, h] for stride 16 feats at 512 resolution\n        **kwargs,\n    ):\n        super().__init__(*args, **kwargs)\n\n        self.compute_cis = partial(\n            compute_axial_cis, dim=self.internal_dim // self.num_heads, theta=rope_theta\n        )\n        freqs_cis = self.compute_cis(end_x=feat_sizes[0], end_y=feat_sizes[1])\n        self.freqs_cis = freqs_cis\n        self.rope_k_repeat = rope_k_repeat\n\n    def forward(\n        self, q: Tensor, k: Tensor, v: Tensor, num_k_exclude_rope: int = 0\n    ) -> Tensor:\n        # Input projections\n        q = self.q_proj(q)\n        k = self.k_proj(k)\n        v = self.v_proj(v)\n\n        # Separate into heads\n        q = self._separate_heads(q, self.num_heads)\n        k = self._separate_heads(k, self.num_heads)\n        v = self._separate_heads(v, self.num_heads)\n\n        # Apply rotary position encoding\n        w = h = math.sqrt(q.shape[-2])\n        self.freqs_cis = self.freqs_cis.to(q.device)\n        if self.freqs_cis.shape[0] != q.shape[-2]:\n            self.freqs_cis = self.compute_cis(end_x=w, end_y=h).to(q.device)\n        if q.shape[-2] != k.shape[-2]:\n            assert self.rope_k_repeat\n\n        num_k_rope = k.size(-2) - num_k_exclude_rope\n        q, k[:, :, :num_k_rope] = apply_rotary_enc(\n            q,\n            k[:, :, :num_k_rope],\n            freqs_cis=self.freqs_cis,\n            repeat_freqs_k=self.rope_k_repeat,\n        )\n\n        dropout_p = self.dropout_p if self.training else 0.0\n        # Attention\n        try:\n            with sdp_kernel_context(dropout_p):\n                out = F.scaled_dot_product_attention(q, k, v, dropout_p=dropout_p)\n        except Exception as e:\n            # Fall back to all kernels if the Flash attention kernel fails\n            warnings.warn(\n                f"Flash Attention kernel failed due to: {e}\\nFalling back to all available "\n                f"kernels for scaled_dot_product_attention (which may have a slower speed).",\n                category=UserWarning,\n                stacklevel=2,\n            )\n            global ALLOW_ALL_KERNELS\n            ALLOW_ALL_KERNELS = True\n            out = F.scaled_dot_product_attention(q, k, v, dropout_p=dropout_p)\n\n        out = self._recombine_heads(out)\n        out = self.out_proj(out)\n\n        return out\n\n\nclass RoPEAttentionv2(Attention):\n    """Attention with rotary position encoding."""\n\n    def __init__(\n        self,\n        *args,\n        rope_theta=10000.0,\n        # whether to repeat q rope to match k length\n        # this is needed for cross-attention to memories\n        q_sizes=(32, 32),  # [w, h] for stride 16 feats at 512 resolution\n        k_sizes=(32, 32),  # [w, h] for stride 16 feats at 512 resolution\n        **kwargs,\n    ):\n        super().__init__(*args, **kwargs)\n\n        self.compute_cis = partial(\n            compute_axial_cis, dim=self.internal_dim // self.num_heads, theta=rope_theta\n        )\n        self.freqs_cis_q = self.compute_cis(end_x=q_sizes[0], end_y=q_sizes[1])\n        self.freqs_cis_k = self.compute_cis(end_x=k_sizes[0], end_y=k_sizes[1])\n\n    def forward(\n        self,\n        q: Tensor,\n        k: Tensor,\n        v: Tensor,\n        num_k_exclude_rope: int = 0,\n        rope_k_repeat: int = -1,\n    ) -> Tensor:\n        # Input projections\n        q = self.q_proj(q)\n        k = self.k_proj(k)\n        v = self.v_proj(v)\n\n        # Separate into heads\n        q = self._separate_heads(q, self.num_heads)\n        k = self._separate_heads(k, self.num_heads)\n        v = self._separate_heads(v, self.num_heads)\n\n        # Apply rotary position encoding\n        self.freqs_cis_q = self.freqs_cis_q.to(q.device)\n        self.freqs_cis_k = self.freqs_cis_k.to(q.device)\n        q = apply_rotary_enc_v2(q, self.freqs_cis_q, repeat_freqs=1)\n        num_k_rope = k.size(-2) - num_k_exclude_rope\n        k[:, :, :num_k_rope] = apply_rotary_enc_v2(\n            k[:, :, :num_k_rope], self.freqs_cis_k, repeat_freqs=rope_k_repeat\n        )\n\n        dropout_p = self.dropout_p if self.training else 0.0\n        # Attention\n        try:\n            with sdp_kernel_context(dropout_p):\n                out = F.scaled_dot_product_attention(q, k, v, dropout_p=dropout_p)\n        except Exception as e:\n            # Fall back to all kernels if the Flash attention kernel fails\n            warnings.warn(\n                f"Flash Attention kernel failed due to: {e}\\nFalling back to all available "\n                f"kernels for scaled_dot_product_attention (which may have a slower speed).",\n                category=UserWarning,\n                stacklevel=2,\n            )\n            global ALLOW_ALL_KERNELS\n            ALLOW_ALL_KERNELS = True\n            out = F.scaled_dot_product_attention(q, k, v, dropout_p=dropout_p)\n\n        out = self._recombine_heads(out)\n        out = self.out_proj(out)\n\n        return out\n', '_shared_test_resources/code/EdgeTAM/sam2/modeling/sam/__init__.py': '# Copyright (c) Meta Platforms, Inc. and affiliates.\n# All rights reserved.\n\n# This source code is licensed under the license found in the\n# LICENSE file in the root directory of this source tree.\n', '_shared_test_resources/code/EdgeTAM/sam2/modeling/sam/prompt_encoder.py': '# Copyright (c) Meta Platforms, Inc. and affiliates.\n# All rights reserved.\n\n# This source code is licensed under the license found in the\n# LICENSE file in the root directory of this source tree.\n\nfrom typing import Optional, Tuple, Type\n\nimport torch\nfrom torch import nn\n\nfrom sam2.modeling.position_encoding import PositionEmbeddingRandom\n\nfrom sam2.modeling.sam2_utils import LayerNorm2d\n\n\nclass PromptEncoder(nn.Module):\n    def __init__(\n        self,\n        embed_dim: int,\n        image_embedding_size: Tuple[int, int],\n        input_image_size: Tuple[int, int],\n        mask_in_chans: int,\n        activation: Type[nn.Module] = nn.GELU,\n    ) -> None:\n        """\n        Encodes prompts for input to SAM\'s mask decoder.\n\n        Arguments:\n          embed_dim (int): The prompts\' embedding dimension\n          image_embedding_size (tuple(int, int)): The spatial size of the\n            image embedding, as (H, W).\n          input_image_size (int): The padded size of the image as input\n            to the image encoder, as (H, W).\n          mask_in_chans (int): The number of hidden channels used for\n            encoding input masks.\n          activation (nn.Module): The activation to use when encoding\n            input masks.\n        """\n        super().__init__()\n        self.embed_dim = embed_dim\n        self.input_image_size = input_image_size\n        self.image_embedding_size = image_embedding_size\n        self.pe_layer = PositionEmbeddingRandom(embed_dim // 2)\n\n        self.num_point_embeddings: int = 4  # pos/neg point + 2 box corners\n        point_embeddings = [\n            nn.Embedding(1, embed_dim) for i in range(self.num_point_embeddings)\n        ]\n        self.point_embeddings = nn.ModuleList(point_embeddings)\n        self.not_a_point_embed = nn.Embedding(1, embed_dim)\n\n        self.mask_input_size = (\n            4 * image_embedding_size[0],\n            4 * image_embedding_size[1],\n        )\n        self.mask_downscaling = nn.Sequential(\n            nn.Conv2d(1, mask_in_chans // 4, kernel_size=2, stride=2),\n            LayerNorm2d(mask_in_chans // 4),\n            activation(),\n            nn.Conv2d(mask_in_chans // 4, mask_in_chans, kernel_size=2, stride=2),\n            LayerNorm2d(mask_in_chans),\n            activation(),\n            nn.Conv2d(mask_in_chans, embed_dim, kernel_size=1),\n        )\n        self.no_mask_embed = nn.Embedding(1, embed_dim)\n\n    def get_dense_pe(self) -> torch.Tensor:\n        """\n        Returns the positional encoding used to encode point prompts,\n        applied to a dense set of points the shape of the image encoding.\n\n        Returns:\n          torch.Tensor: Positional encoding with shape\n            1x(embed_dim)x(embedding_h)x(embedding_w)\n        """\n        return self.pe_layer(self.image_embedding_size).unsqueeze(0)\n\n    def _embed_points(\n        self,\n        points: torch.Tensor,\n        labels: torch.Tensor,\n        pad: bool,\n    ) -> torch.Tensor:\n        """Embeds point prompts."""\n        points = points + 0.5  # Shift to center of pixel\n        if pad:\n            padding_point = torch.zeros((points.shape[0], 1, 2), device=points.device)\n            padding_label = -torch.ones((labels.shape[0], 1), device=labels.device)\n            points = torch.cat([points, padding_point], dim=1)\n            labels = torch.cat([labels, padding_label], dim=1)\n        point_embedding = self.pe_layer.forward_with_coords(\n            points, self.input_image_size\n        )\n        point_embedding[labels == -1] = 0.0\n        point_embedding[labels == -1] += self.not_a_point_embed.weight\n        point_embedding[labels == 0] += self.point_embeddings[0].weight\n        point_embedding[labels == 1] += self.point_embeddings[1].weight\n        point_embedding[labels == 2] += self.point_embeddings[2].weight\n        point_embedding[labels == 3] += self.point_embeddings[3].weight\n        return point_embedding\n\n    def _embed_boxes(self, boxes: torch.Tensor) -> torch.Tensor:\n        """Embeds box prompts."""\n        boxes = boxes + 0.5  # Shift to center of pixel\n        coords = boxes.reshape(-1, 2, 2)\n        corner_embedding = self.pe_layer.forward_with_coords(\n            coords, self.input_image_size\n        )\n        corner_embedding[:, 0, :] += self.point_embeddings[2].weight\n        corner_embedding[:, 1, :] += self.point_embeddings[3].weight\n        return corner_embedding\n\n    def _embed_masks(self, masks: torch.Tensor) -> torch.Tensor:\n        """Embeds mask inputs."""\n        mask_embedding = self.mask_downscaling(masks)\n        return mask_embedding\n\n    def _get_batch_size(\n        self,\n        points: Optional[Tuple[torch.Tensor, torch.Tensor]],\n        boxes: Optional[torch.Tensor],\n        masks: Optional[torch.Tensor],\n    ) -> int:\n        """\n        Gets the batch size of the output given the batch size of the input prompts.\n        """\n        if points is not None:\n            return points[0].shape[0]\n        elif boxes is not None:\n            return boxes.shape[0]\n        elif masks is not None:\n            return masks.shape[0]\n        else:\n            return 1\n\n    def _get_device(self) -> torch.device:\n        return self.point_embeddings[0].weight.device\n\n    def forward(\n        self,\n        points: Optional[Tuple[torch.Tensor, torch.Tensor]],\n        boxes: Optional[torch.Tensor],\n        masks: Optional[torch.Tensor],\n    ) -> Tuple[torch.Tensor, torch.Tensor]:\n        """\n        Embeds different types of prompts, returning both sparse and dense\n        embeddings.\n\n        Arguments:\n          points (tuple(torch.Tensor, torch.Tensor) or none): point coordinates\n            and labels to embed.\n          boxes (torch.Tensor or none): boxes to embed\n          masks (torch.Tensor or none): masks to embed\n\n        Returns:\n          torch.Tensor: sparse embeddings for the points and boxes, with shape\n            BxNx(embed_dim), where N is determined by the number of input points\n            and boxes.\n          torch.Tensor: dense embeddings for the masks, in the shape\n            Bx(embed_dim)x(embed_H)x(embed_W)\n        """\n        bs = self._get_batch_size(points, boxes, masks)\n        sparse_embeddings = torch.empty(\n            (bs, 0, self.embed_dim), device=self._get_device()\n        )\n        if points is not None:\n            coords, labels = points\n            point_embeddings = self._embed_points(coords, labels, pad=(boxes is None))\n            sparse_embeddings = torch.cat([sparse_embeddings, point_embeddings], dim=1)\n        if boxes is not None:\n            box_embeddings = self._embed_boxes(boxes)\n            sparse_embeddings = torch.cat([sparse_embeddings, box_embeddings], dim=1)\n\n        if masks is not None:\n            dense_embeddings = self._embed_masks(masks)\n        else:\n            dense_embeddings = self.no_mask_embed.weight.reshape(1, -1, 1, 1).expand(\n                bs, -1, self.image_embedding_size[0], self.image_embedding_size[1]\n            )\n\n        return sparse_embeddings, dense_embeddings\n', '_shared_test_resources/code/EdgeTAM/sam2/modeling/sam/mask_decoder.py': '# Copyright (c) Meta Platforms, Inc. and affiliates.\n# All rights reserved.\n\n# This source code is licensed under the license found in the\n# LICENSE file in the root directory of this source tree.\n\nfrom typing import List, Optional, Tuple, Type\n\nimport torch\nfrom torch import nn\n\nfrom sam2.modeling.sam2_utils import LayerNorm2d, MLP\n\n\nclass MaskDecoder(nn.Module):\n    def __init__(\n        self,\n        *,\n        transformer_dim: int,\n        transformer: nn.Module,\n        num_multimask_outputs: int = 3,\n        activation: Type[nn.Module] = nn.GELU,\n        iou_head_depth: int = 3,\n        iou_head_hidden_dim: int = 256,\n        use_high_res_features: bool = False,\n        iou_prediction_use_sigmoid=False,\n        dynamic_multimask_via_stability=False,\n        dynamic_multimask_stability_delta=0.05,\n        dynamic_multimask_stability_thresh=0.98,\n        pred_obj_scores: bool = False,\n        pred_obj_scores_mlp: bool = False,\n        use_multimask_token_for_obj_ptr: bool = False,\n    ) -> None:\n        """\n        Predicts masks given an image and prompt embeddings, using a\n        transformer architecture.\n\n        Arguments:\n          transformer_dim (int): the channel dimension of the transformer\n          transformer (nn.Module): the transformer used to predict masks\n          num_multimask_outputs (int): the number of masks to predict\n            when disambiguating masks\n          activation (nn.Module): the type of activation to use when\n            upscaling masks\n          iou_head_depth (int): the depth of the MLP used to predict\n            mask quality\n          iou_head_hidden_dim (int): the hidden dimension of the MLP\n            used to predict mask quality\n        """\n        super().__init__()\n        self.transformer_dim = transformer_dim\n        self.transformer = transformer\n\n        self.num_multimask_outputs = num_multimask_outputs\n\n        self.iou_token = nn.Embedding(1, transformer_dim)\n        self.num_mask_tokens = num_multimask_outputs + 1\n        self.mask_tokens = nn.Embedding(self.num_mask_tokens, transformer_dim)\n\n        self.pred_obj_scores = pred_obj_scores\n        if self.pred_obj_scores:\n            self.obj_score_token = nn.Embedding(1, transformer_dim)\n        self.use_multimask_token_for_obj_ptr = use_multimask_token_for_obj_ptr\n\n        self.output_upscaling = nn.Sequential(\n            nn.ConvTranspose2d(\n                transformer_dim, transformer_dim // 4, kernel_size=2, stride=2\n            ),\n            LayerNorm2d(transformer_dim // 4),\n            activation(),\n            nn.ConvTranspose2d(\n                transformer_dim // 4, transformer_dim // 8, kernel_size=2, stride=2\n            ),\n            activation(),\n        )\n        self.use_high_res_features = use_high_res_features\n        if use_high_res_features:\n            self.conv_s0 = nn.Conv2d(\n                transformer_dim, transformer_dim // 8, kernel_size=1, stride=1\n            )\n            self.conv_s1 = nn.Conv2d(\n                transformer_dim, transformer_dim // 4, kernel_size=1, stride=1\n            )\n\n        self.output_hypernetworks_mlps = nn.ModuleList(\n            [\n                MLP(transformer_dim, transformer_dim, transformer_dim // 8, 3)\n                for i in range(self.num_mask_tokens)\n            ]\n        )\n\n        self.iou_prediction_head = MLP(\n            transformer_dim,\n            iou_head_hidden_dim,\n            self.num_mask_tokens,\n            iou_head_depth,\n            sigmoid_output=iou_prediction_use_sigmoid,\n        )\n        if self.pred_obj_scores:\n            self.pred_obj_score_head = nn.Linear(transformer_dim, 1)\n            if pred_obj_scores_mlp:\n                self.pred_obj_score_head = MLP(transformer_dim, transformer_dim, 1, 3)\n\n        # When outputting a single mask, optionally we can dynamically fall back to the best\n        # multimask output token if the single mask output token gives low stability scores.\n        self.dynamic_multimask_via_stability = dynamic_multimask_via_stability\n        self.dynamic_multimask_stability_delta = dynamic_multimask_stability_delta\n        self.dynamic_multimask_stability_thresh = dynamic_multimask_stability_thresh\n\n    def forward(\n        self,\n        image_embeddings: torch.Tensor,\n        image_pe: torch.Tensor,\n        sparse_prompt_embeddings: torch.Tensor,\n        dense_prompt_embeddings: torch.Tensor,\n        multimask_output: bool,\n        repeat_image: bool,\n        high_res_features: Optional[List[torch.Tensor]] = None,\n    ) -> Tuple[torch.Tensor, torch.Tensor]:\n        """\n        Predict masks given image and prompt embeddings.\n\n        Arguments:\n          image_embeddings (torch.Tensor): the embeddings from the image encoder\n          image_pe (torch.Tensor): positional encoding with the shape of image_embeddings\n          sparse_prompt_embeddings (torch.Tensor): the embeddings of the points and boxes\n          dense_prompt_embeddings (torch.Tensor): the embeddings of the mask inputs\n          multimask_output (bool): Whether to return multiple masks or a single\n            mask.\n\n        Returns:\n          torch.Tensor: batched predicted masks\n          torch.Tensor: batched predictions of mask quality\n          torch.Tensor: batched SAM token for mask output\n        """\n        masks, iou_pred, mask_tokens_out, object_score_logits = self.predict_masks(\n            image_embeddings=image_embeddings,\n            image_pe=image_pe,\n            sparse_prompt_embeddings=sparse_prompt_embeddings,\n            dense_prompt_embeddings=dense_prompt_embeddings,\n            repeat_image=repeat_image,\n            high_res_features=high_res_features,\n        )\n\n        # Select the correct mask or masks for output\n        if multimask_output:\n            masks = masks[:, 1:, :, :]\n            iou_pred = iou_pred[:, 1:]\n        elif self.dynamic_multimask_via_stability and not self.training:\n            masks, iou_pred = self._dynamic_multimask_via_stability(masks, iou_pred)\n        else:\n            masks = masks[:, 0:1, :, :]\n            iou_pred = iou_pred[:, 0:1]\n\n        if multimask_output and self.use_multimask_token_for_obj_ptr:\n            sam_tokens_out = mask_tokens_out[:, 1:]  # [b, 3, c] shape\n        else:\n            # Take the mask output token. Here we *always* use the token for single mask output.\n            # At test time, even if we track after 1-click (and using multimask_output=True),\n            # we still take the single mask token here. The rationale is that we always track\n            # after multiple clicks during training, so the past tokens seen during training\n            # are always the single mask token (and we\'ll let it be the object-memory token).\n            sam_tokens_out = mask_tokens_out[:, 0:1]  # [b, 1, c] shape\n\n        # Prepare output\n        return masks, iou_pred, sam_tokens_out, object_score_logits\n\n    def predict_masks(\n        self,\n        image_embeddings: torch.Tensor,\n        image_pe: torch.Tensor,\n        sparse_prompt_embeddings: torch.Tensor,\n        dense_prompt_embeddings: torch.Tensor,\n        repeat_image: bool,\n        high_res_features: Optional[List[torch.Tensor]] = None,\n    ) -> Tuple[torch.Tensor, torch.Tensor]:\n        """Predicts masks. See \'forward\' for more details."""\n        # Concatenate output tokens\n        s = 0\n        if self.pred_obj_scores:\n            output_tokens = torch.cat(\n                [\n                    self.obj_score_token.weight,\n                    self.iou_token.weight,\n                    self.mask_tokens.weight,\n                ],\n                dim=0,\n            )\n            s = 1\n        else:\n            output_tokens = torch.cat(\n                [self.iou_token.weight, self.mask_tokens.weight], dim=0\n            )\n        output_tokens = output_tokens.unsqueeze(0).expand(\n            sparse_prompt_embeddings.size(0), -1, -1\n        )\n        tokens = torch.cat((output_tokens, sparse_prompt_embeddings), dim=1)\n\n        # Expand per-image data in batch direction to be per-mask\n        if repeat_image:\n            src = torch.repeat_interleave(image_embeddings, tokens.shape[0], dim=0)\n        else:\n            assert image_embeddings.shape[0] == tokens.shape[0]\n            src = image_embeddings\n        src = src + dense_prompt_embeddings\n        assert (\n            image_pe.size(0) == 1\n        ), "image_pe should have size 1 in batch dim (from `get_dense_pe()`)"\n        pos_src = torch.repeat_interleave(image_pe, tokens.shape[0], dim=0)\n        b, c, h, w = src.shape\n\n        # Run the transformer\n        hs, src = self.transformer(src, pos_src, tokens)\n        iou_token_out = hs[:, s, :]\n        mask_tokens_out = hs[:, s + 1 : (s + 1 + self.num_mask_tokens), :]\n\n        # Upscale mask embeddings and predict masks using the mask tokens\n        src = src.transpose(1, 2).view(b, c, h, w)\n        if not self.use_high_res_features:\n            upscaled_embedding = self.output_upscaling(src)\n        else:\n            dc1, ln1, act1, dc2, act2 = self.output_upscaling\n            feat_s0, feat_s1 = high_res_features\n            upscaled_embedding = act1(ln1(dc1(src) + feat_s1))\n            upscaled_embedding = act2(dc2(upscaled_embedding) + feat_s0)\n\n        hyper_in_list: List[torch.Tensor] = []\n        for i in range(self.num_mask_tokens):\n            hyper_in_list.append(\n                self.output_hypernetworks_mlps[i](mask_tokens_out[:, i, :])\n            )\n        hyper_in = torch.stack(hyper_in_list, dim=1)\n        b, c, h, w = upscaled_embedding.shape\n        masks = (hyper_in @ upscaled_embedding.view(b, c, h * w)).view(b, -1, h, w)\n\n        # Generate mask quality predictions\n        iou_pred = self.iou_prediction_head(iou_token_out)\n        if self.pred_obj_scores:\n            assert s == 1\n            object_score_logits = self.pred_obj_score_head(hs[:, 0, :])\n        else:\n            # Obj scores logits - default to 10.0, i.e. assuming the object is present, sigmoid(10)=1\n            object_score_logits = 10.0 * iou_pred.new_ones(iou_pred.shape[0], 1)\n\n        return masks, iou_pred, mask_tokens_out, object_score_logits\n\n    def _get_stability_scores(self, mask_logits):\n        """\n        Compute stability scores of the mask logits based on the IoU between upper and\n        lower thresholds.\n        """\n        mask_logits = mask_logits.flatten(-2)\n        stability_delta = self.dynamic_multimask_stability_delta\n        area_i = torch.sum(mask_logits > stability_delta, dim=-1).float()\n        area_u = torch.sum(mask_logits > -stability_delta, dim=-1).float()\n        stability_scores = torch.where(area_u > 0, area_i / area_u, 1.0)\n        return stability_scores\n\n    def _dynamic_multimask_via_stability(self, all_mask_logits, all_iou_scores):\n        """\n        When outputting a single mask, if the stability score from the current single-mask\n        output (based on output token 0) falls below a threshold, we instead select from\n        multi-mask outputs (based on output token 1~3) the mask with the highest predicted\n        IoU score. This is intended to ensure a valid mask for both clicking and tracking.\n        """\n        # The best mask from multimask output tokens (1~3)\n        multimask_logits = all_mask_logits[:, 1:, :, :]\n        multimask_iou_scores = all_iou_scores[:, 1:]\n        best_scores_inds = torch.argmax(multimask_iou_scores, dim=-1)\n        batch_inds = torch.arange(\n            multimask_iou_scores.size(0), device=all_iou_scores.device\n        )\n        best_multimask_logits = multimask_logits[batch_inds, best_scores_inds]\n        best_multimask_logits = best_multimask_logits.unsqueeze(1)\n        best_multimask_iou_scores = multimask_iou_scores[batch_inds, best_scores_inds]\n        best_multimask_iou_scores = best_multimask_iou_scores.unsqueeze(1)\n\n        # The mask from singlemask output token 0 and its stability score\n        singlemask_logits = all_mask_logits[:, 0:1, :, :]\n        singlemask_iou_scores = all_iou_scores[:, 0:1]\n        stability_scores = self._get_stability_scores(singlemask_logits)\n        is_stable = stability_scores >= self.dynamic_multimask_stability_thresh\n\n        # Dynamically fall back to best multimask output upon low stability scores.\n        mask_logits_out = torch.where(\n            is_stable[..., None, None].expand_as(singlemask_logits),\n            singlemask_logits,\n            best_multimask_logits,\n        )\n        iou_scores_out = torch.where(\n            is_stable.expand_as(singlemask_iou_scores),\n            singlemask_iou_scores,\n            best_multimask_iou_scores,\n        )\n        return mask_logits_out, iou_scores_out\n', '_shared_test_resources/code/EdgeTAM/sam2/modeling/backbones/timm.py': '# Copyright (c) Meta Platforms, Inc. and affiliates.\n# All rights reserved.\n\n# This source code is licensed under the license found in the\n# LICENSE file in the root directory of this source tree.\n\n"""Backbones from the TIMM library."""\n\nfrom typing import List, Tuple\n\nimport torch\n\nfrom timm.models import create_model\nfrom torch import nn\n\n\nclass TimmBackbone(nn.Module):\n    def __init__(\n        self,\n        name: str,\n        features: Tuple[str, ...],\n    ):\n        super().__init__()\n\n        out_indices = tuple(int(f[len("layer") :]) for f in features)\n\n        backbone = create_model(\n            name,\n            # The downloaded EdgeTAM checkpoint supplies all backbone weights.\n            # Avoid a separate, now-dead RepViT release URL during evaluation.\n            pretrained=False,\n            in_chans=3,\n            features_only=True,\n            out_indices=out_indices,\n        )\n\n        num_channels = backbone.feature_info.channels()\n        self.channel_list = num_channels[::-1]\n        self.body = backbone\n\n    def forward(self, x: torch.Tensor) -> List[torch.Tensor]:\n        xs = self.body(x)\n\n        out = []\n        for i, x in enumerate(xs):\n            out.append(x)\n        return out\n', '_shared_test_resources/code/EdgeTAM/sam2/modeling/backbones/utils.py': '# Copyright (c) Meta Platforms, Inc. and affiliates.\n# All rights reserved.\n\n# This source code is licensed under the license found in the\n# LICENSE file in the root directory of this source tree.\n\n"""Some utilities for backbones, in particular for windowing"""\n\nfrom typing import Tuple\n\nimport torch\nimport torch.nn as nn\nimport torch.nn.functional as F\n\n\ndef window_partition(x, window_size):\n    """\n    Partition into non-overlapping windows with padding if needed.\n    Args:\n        x (tensor): input tokens with [B, H, W, C].\n        window_size (int): window size.\n    Returns:\n        windows: windows after partition with [B * num_windows, window_size, window_size, C].\n        (Hp, Wp): padded height and width before partition\n    """\n    B, H, W, C = x.shape\n\n    pad_h = (window_size - H % window_size) % window_size\n    pad_w = (window_size - W % window_size) % window_size\n    if pad_h > 0 or pad_w > 0:\n        x = F.pad(x, (0, 0, 0, pad_w, 0, pad_h))\n    Hp, Wp = H + pad_h, W + pad_w\n\n    x = x.view(B, Hp // window_size, window_size, Wp // window_size, window_size, C)\n    windows = (\n        x.permute(0, 1, 3, 2, 4, 5).contiguous().view(-1, window_size, window_size, C)\n    )\n    return windows, (Hp, Wp)\n\n\ndef window_unpartition(windows, window_size, pad_hw, hw):\n    """\n    Window unpartition into original sequences and removing padding.\n    Args:\n        x (tensor): input tokens with [B * num_windows, window_size, window_size, C].\n        window_size (int): window size.\n        pad_hw (Tuple): padded height and width (Hp, Wp).\n        hw (Tuple): original height and width (H, W) before padding.\n    Returns:\n        x: unpartitioned sequences with [B, H, W, C].\n    """\n    Hp, Wp = pad_hw\n    H, W = hw\n    B = windows.shape[0] // (Hp * Wp // window_size // window_size)\n    x = windows.view(\n        B, Hp // window_size, Wp // window_size, window_size, window_size, -1\n    )\n    x = x.permute(0, 1, 3, 2, 4, 5).contiguous().view(B, Hp, Wp, -1)\n\n    if Hp > H or Wp > W:\n        x = x[:, :H, :W, :].contiguous()\n    return x\n\n\nclass PatchEmbed(nn.Module):\n    """\n    Image to Patch Embedding.\n    """\n\n    def __init__(\n        self,\n        kernel_size: Tuple[int, ...] = (7, 7),\n        stride: Tuple[int, ...] = (4, 4),\n        padding: Tuple[int, ...] = (3, 3),\n        in_chans: int = 3,\n        embed_dim: int = 768,\n    ):\n        """\n        Args:\n            kernel_size (Tuple): kernel size of the projection layer.\n            stride (Tuple): stride of the projection layer.\n            padding (Tuple): padding size of the projection layer.\n            in_chans (int): Number of input image channels.\n            embed_dim (int):  embed_dim (int): Patch embedding dimension.\n        """\n        super().__init__()\n        self.proj = nn.Conv2d(\n            in_chans, embed_dim, kernel_size=kernel_size, stride=stride, padding=padding\n        )\n\n    def forward(self, x: torch.Tensor) -> torch.Tensor:\n        x = self.proj(x)\n        # B C H W -> B H W C\n        x = x.permute(0, 2, 3, 1)\n        return x\n', '_shared_test_resources/code/EdgeTAM/sam2/modeling/backbones/__init__.py': '# Copyright (c) Meta Platforms, Inc. and affiliates.\n# All rights reserved.\n\n# This source code is licensed under the license found in the\n# LICENSE file in the root directory of this source tree.\n', '_shared_test_resources/code/EdgeTAM/sam2/modeling/backbones/hieradet.py': '# Copyright (c) Meta Platforms, Inc. and affiliates.\n# All rights reserved.\n\n# This source code is licensed under the license found in the\n# LICENSE file in the root directory of this source tree.\n\nimport logging\nfrom functools import partial\nfrom typing import List, Tuple, Union\n\nimport torch\nimport torch.nn as nn\nimport torch.nn.functional as F\nfrom iopath.common.file_io import g_pathmgr\n\nfrom sam2.modeling.backbones.utils import (\n    PatchEmbed,\n    window_partition,\n    window_unpartition,\n)\n\nfrom sam2.modeling.sam2_utils import DropPath, MLP\n\n\ndef do_pool(x: torch.Tensor, pool: nn.Module, norm: nn.Module = None) -> torch.Tensor:\n    if pool is None:\n        return x\n    # (B, H, W, C) -> (B, C, H, W)\n    x = x.permute(0, 3, 1, 2)\n    x = pool(x)\n    # (B, C, H\', W\') -> (B, H\', W\', C)\n    x = x.permute(0, 2, 3, 1)\n    if norm:\n        x = norm(x)\n\n    return x\n\n\nclass MultiScaleAttention(nn.Module):\n    def __init__(\n        self,\n        dim: int,\n        dim_out: int,\n        num_heads: int,\n        q_pool: nn.Module = None,\n    ):\n        super().__init__()\n\n        self.dim = dim\n        self.dim_out = dim_out\n        self.num_heads = num_heads\n        self.q_pool = q_pool\n        self.qkv = nn.Linear(dim, dim_out * 3)\n        self.proj = nn.Linear(dim_out, dim_out)\n\n    def forward(self, x: torch.Tensor) -> torch.Tensor:\n        B, H, W, _ = x.shape\n        # qkv with shape (B, H * W, 3, nHead, C)\n        qkv = self.qkv(x).reshape(B, H * W, 3, self.num_heads, -1)\n        # q, k, v with shape (B, H * W, nheads, C)\n        q, k, v = torch.unbind(qkv, 2)\n\n        # Q pooling (for downsample at stage changes)\n        if self.q_pool:\n            q = do_pool(q.reshape(B, H, W, -1), self.q_pool)\n            H, W = q.shape[1:3]  # downsampled shape\n            q = q.reshape(B, H * W, self.num_heads, -1)\n\n        # Torch\'s SDPA expects [B, nheads, H*W, C] so we transpose\n        x = F.scaled_dot_product_attention(\n            q.transpose(1, 2),\n            k.transpose(1, 2),\n            v.transpose(1, 2),\n        )\n        # Transpose back\n        x = x.transpose(1, 2)\n        x = x.reshape(B, H, W, -1)\n\n        x = self.proj(x)\n\n        return x\n\n\nclass MultiScaleBlock(nn.Module):\n    def __init__(\n        self,\n        dim: int,\n        dim_out: int,\n        num_heads: int,\n        mlp_ratio: float = 4.0,\n        drop_path: float = 0.0,\n        norm_layer: Union[nn.Module, str] = "LayerNorm",\n        q_stride: Tuple[int, int] = None,\n        act_layer: nn.Module = nn.GELU,\n        window_size: int = 0,\n    ):\n        super().__init__()\n\n        if isinstance(norm_layer, str):\n            norm_layer = partial(getattr(nn, norm_layer), eps=1e-6)\n\n        self.dim = dim\n        self.dim_out = dim_out\n        self.norm1 = norm_layer(dim)\n\n        self.window_size = window_size\n\n        self.pool, self.q_stride = None, q_stride\n        if self.q_stride:\n            self.pool = nn.MaxPool2d(\n                kernel_size=q_stride, stride=q_stride, ceil_mode=False\n            )\n\n        self.attn = MultiScaleAttention(\n            dim,\n            dim_out,\n            num_heads=num_heads,\n            q_pool=self.pool,\n        )\n        self.drop_path = DropPath(drop_path) if drop_path > 0.0 else nn.Identity()\n\n        self.norm2 = norm_layer(dim_out)\n        self.mlp = MLP(\n            dim_out,\n            int(dim_out * mlp_ratio),\n            dim_out,\n            num_layers=2,\n            activation=act_layer,\n        )\n\n        if dim != dim_out:\n            self.proj = nn.Linear(dim, dim_out)\n\n    def forward(self, x: torch.Tensor) -> torch.Tensor:\n        shortcut = x  # B, H, W, C\n        x = self.norm1(x)\n\n        # Skip connection\n        if self.dim != self.dim_out:\n            shortcut = do_pool(self.proj(x), self.pool)\n\n        # Window partition\n        window_size = self.window_size\n        if window_size > 0:\n            H, W = x.shape[1], x.shape[2]\n            x, pad_hw = window_partition(x, window_size)\n\n        # Window Attention + Q Pooling (if stage change)\n        x = self.attn(x)\n        if self.q_stride:\n            # Shapes have changed due to Q pooling\n            window_size = self.window_size // self.q_stride[0]\n            H, W = shortcut.shape[1:3]\n\n            pad_h = (window_size - H % window_size) % window_size\n            pad_w = (window_size - W % window_size) % window_size\n            pad_hw = (H + pad_h, W + pad_w)\n\n        # Reverse window partition\n        if self.window_size > 0:\n            x = window_unpartition(x, window_size, pad_hw, (H, W))\n\n        x = shortcut + self.drop_path(x)\n        # MLP\n        x = x + self.drop_path(self.mlp(self.norm2(x)))\n        return x\n\n\nclass Hiera(nn.Module):\n    """\n    Reference: https://arxiv.org/abs/2306.00989\n    """\n\n    def __init__(\n        self,\n        embed_dim: int = 96,  # initial embed dim\n        num_heads: int = 1,  # initial number of heads\n        drop_path_rate: float = 0.0,  # stochastic depth\n        q_pool: int = 3,  # number of q_pool stages\n        q_stride: Tuple[int, int] = (2, 2),  # downsample stride bet. stages\n        stages: Tuple[int, ...] = (2, 3, 16, 3),  # blocks per stage\n        dim_mul: float = 2.0,  # dim_mul factor at stage shift\n        head_mul: float = 2.0,  # head_mul factor at stage shift\n        window_pos_embed_bkg_spatial_size: Tuple[int, int] = (14, 14),\n        # window size per stage, when not using global att.\n        window_spec: Tuple[int, ...] = (\n            8,\n            4,\n            14,\n            7,\n        ),\n        # global attn in these blocks\n        global_att_blocks: Tuple[int, ...] = (\n            12,\n            16,\n            20,\n        ),\n        weights_path=None,\n        return_interm_layers=True,  # return feats from every stage\n    ):\n        super().__init__()\n\n        assert len(stages) == len(window_spec)\n        self.window_spec = window_spec\n\n        depth = sum(stages)\n        self.q_stride = q_stride\n        self.stage_ends = [sum(stages[:i]) - 1 for i in range(1, len(stages) + 1)]\n        assert 0 <= q_pool <= len(self.stage_ends[:-1])\n        self.q_pool_blocks = [x + 1 for x in self.stage_ends[:-1]][:q_pool]\n        self.return_interm_layers = return_interm_layers\n\n        self.patch_embed = PatchEmbed(\n            embed_dim=embed_dim,\n        )\n        # Which blocks have global att?\n        self.global_att_blocks = global_att_blocks\n\n        # Windowed positional embedding (https://arxiv.org/abs/2311.05613)\n        self.window_pos_embed_bkg_spatial_size = window_pos_embed_bkg_spatial_size\n        self.pos_embed = nn.Parameter(\n            torch.zeros(1, embed_dim, *self.window_pos_embed_bkg_spatial_size)\n        )\n        self.pos_embed_window = nn.Parameter(\n            torch.zeros(1, embed_dim, self.window_spec[0], self.window_spec[0])\n        )\n\n        dpr = [\n            x.item() for x in torch.linspace(0, drop_path_rate, depth)\n        ]  # stochastic depth decay rule\n\n        cur_stage = 1\n        self.blocks = nn.ModuleList()\n\n        for i in range(depth):\n            dim_out = embed_dim\n            # lags by a block, so first block of\n            # next stage uses an initial window size\n            # of previous stage and final window size of current stage\n            window_size = self.window_spec[cur_stage - 1]\n\n            if self.global_att_blocks is not None:\n                window_size = 0 if i in self.global_att_blocks else window_size\n\n            if i - 1 in self.stage_ends:\n                dim_out = int(embed_dim * dim_mul)\n                num_heads = int(num_heads * head_mul)\n                cur_stage += 1\n\n            block = MultiScaleBlock(\n                dim=embed_dim,\n                dim_out=dim_out,\n                num_heads=num_heads,\n                drop_path=dpr[i],\n                q_stride=self.q_stride if i in self.q_pool_blocks else None,\n                window_size=window_size,\n            )\n\n            embed_dim = dim_out\n            self.blocks.append(block)\n\n        self.channel_list = (\n            [self.blocks[i].dim_out for i in self.stage_ends[::-1]]\n            if return_interm_layers\n            else [self.blocks[-1].dim_out]\n        )\n\n        if weights_path is not None:\n            with g_pathmgr.open(weights_path, "rb") as f:\n                chkpt = torch.load(f, map_location="cpu")\n            logging.info("loading Hiera", self.load_state_dict(chkpt, strict=False))\n\n    def _get_pos_embed(self, hw: Tuple[int, int]) -> torch.Tensor:\n        h, w = hw\n        window_embed = self.pos_embed_window\n        pos_embed = F.interpolate(self.pos_embed, size=(h, w), mode="bicubic")\n        pos_embed = pos_embed + window_embed.tile(\n            [x // y for x, y in zip(pos_embed.shape, window_embed.shape)]\n        )\n        pos_embed = pos_embed.permute(0, 2, 3, 1)\n        return pos_embed\n\n    def forward(self, x: torch.Tensor) -> List[torch.Tensor]:\n        x = self.patch_embed(x)\n        # x: (B, H, W, C)\n\n        # Add pos embed\n        x = x + self._get_pos_embed(x.shape[1:3])\n\n        outputs = []\n        for i, blk in enumerate(self.blocks):\n            x = blk(x)\n            if (i == self.stage_ends[-1]) or (\n                i in self.stage_ends and self.return_interm_layers\n            ):\n                feats = x.permute(0, 3, 1, 2)\n                outputs.append(feats)\n\n        return outputs\n\n    def get_layer_id(self, layer_name):\n        # https://github.com/microsoft/unilm/blob/master/beit/optim_factory.py#L33\n        num_layers = self.get_num_layers()\n\n        if layer_name.find("rel_pos") != -1:\n            return num_layers + 1\n        elif layer_name.find("pos_embed") != -1:\n            return 0\n        elif layer_name.find("patch_embed") != -1:\n            return 0\n        elif layer_name.find("blocks") != -1:\n            return int(layer_name.split("blocks")[1].split(".")[1]) + 1\n        else:\n            return num_layers + 1\n\n    def get_num_layers(self) -> int:\n        return len(self.blocks)\n', '_shared_test_resources/code/EdgeTAM/sam2/modeling/backbones/image_encoder.py': '# Copyright (c) Meta Platforms, Inc. and affiliates.\n# All rights reserved.\n\n# This source code is licensed under the license found in the\n# LICENSE file in the root directory of this source tree.\n\nfrom typing import List, Optional\n\nimport torch\nimport torch.nn as nn\nimport torch.nn.functional as F\n\n\nclass ImageEncoder(nn.Module):\n    def __init__(\n        self,\n        trunk: nn.Module,\n        neck: nn.Module,\n        scalp: int = 0,\n    ):\n        super().__init__()\n        self.trunk = trunk\n        self.neck = neck\n        self.scalp = scalp\n        assert (\n            self.trunk.channel_list == self.neck.backbone_channel_list\n        ), f"Channel dims of trunk and neck do not match. Trunk: {self.trunk.channel_list}, neck: {self.neck.backbone_channel_list}"\n\n    def forward(self, sample: torch.Tensor):\n        # Forward through backbone\n        features, pos = self.neck(self.trunk(sample))\n        if self.scalp > 0:\n            # Discard the lowest resolution features\n            features, pos = features[: -self.scalp], pos[: -self.scalp]\n\n        src = features[-1]\n        output = {\n            "vision_features": src,\n            "vision_pos_enc": pos,\n            "backbone_fpn": features,\n        }\n        return output\n\n\nclass FpnNeck(nn.Module):\n    """\n    A modified variant of Feature Pyramid Network (FPN) neck\n    (we remove output conv and also do bicubic interpolation similar to ViT\n    pos embed interpolation)\n    """\n\n    def __init__(\n        self,\n        position_encoding: nn.Module,\n        d_model: int,\n        backbone_channel_list: List[int],\n        kernel_size: int = 1,\n        stride: int = 1,\n        padding: int = 0,\n        fpn_interp_model: str = "bilinear",\n        fuse_type: str = "sum",\n        fpn_top_down_levels: Optional[List[int]] = None,\n    ):\n        """Initialize the neck\n        :param trunk: the backbone\n        :param position_encoding: the positional encoding to use\n        :param d_model: the dimension of the model\n        :param neck_norm: the normalization to use\n        """\n        super().__init__()\n        self.position_encoding = position_encoding\n        self.convs = nn.ModuleList()\n        self.backbone_channel_list = backbone_channel_list\n        self.d_model = d_model\n        for dim in backbone_channel_list:\n            current = nn.Sequential()\n            current.add_module(\n                "conv",\n                nn.Conv2d(\n                    in_channels=dim,\n                    out_channels=d_model,\n                    kernel_size=kernel_size,\n                    stride=stride,\n                    padding=padding,\n                ),\n            )\n\n            self.convs.append(current)\n        self.fpn_interp_model = fpn_interp_model\n        assert fuse_type in ["sum", "avg"]\n        self.fuse_type = fuse_type\n\n        # levels to have top-down features in its outputs\n        # e.g. if fpn_top_down_levels is [2, 3], then only outputs of level 2 and 3\n        # have top-down propagation, while outputs of level 0 and level 1 have only\n        # lateral features from the same backbone level.\n        if fpn_top_down_levels is None:\n            # default is to have top-down features on all levels\n            fpn_top_down_levels = range(len(self.convs))\n        self.fpn_top_down_levels = list(fpn_top_down_levels)\n\n    def forward(self, xs: List[torch.Tensor]):\n\n        out = [None] * len(self.convs)\n        pos = [None] * len(self.convs)\n        assert len(xs) == len(self.convs)\n        # fpn forward pass\n        # see https://github.com/facebookresearch/detectron2/blob/main/detectron2/modeling/backbone/fpn.py\n        prev_features = None\n        # forward in top-down order (from low to high resolution)\n        n = len(self.convs) - 1\n        for i in range(n, -1, -1):\n            x = xs[i]\n            lateral_features = self.convs[n - i](x)\n            if i in self.fpn_top_down_levels and prev_features is not None:\n                top_down_features = F.interpolate(\n                    prev_features.to(dtype=torch.float32),\n                    scale_factor=2.0,\n                    mode=self.fpn_interp_model,\n                    align_corners=(\n                        None if self.fpn_interp_model == "nearest" else False\n                    ),\n                    antialias=False,\n                )\n                prev_features = lateral_features + top_down_features\n                if self.fuse_type == "avg":\n                    prev_features /= 2\n            else:\n                prev_features = lateral_features\n            x_out = prev_features\n            out[i] = x_out\n            pos[i] = self.position_encoding(x_out).to(x_out.dtype)\n\n        return out, pos\n', '_shared_test_resources/code/EdgeTAM/tools/vos_inference.py': '# Copyright (c) Meta Platforms, Inc. and affiliates.\n# All rights reserved.\n\n# This source code is licensed under the license found in the\n# LICENSE file in the root directory of this source tree.\n\nimport argparse\nimport os\nfrom collections import defaultdict\n\nimport numpy as np\nimport torch\nfrom PIL import Image\nfrom sam2.build_sam import build_sam2_video_predictor\n\n\n# the PNG palette for DAVIS 2017 dataset\nDAVIS_PALETTE = b"\\x00\\x00\\x00\\x80\\x00\\x00\\x00\\x80\\x00\\x80\\x80\\x00\\x00\\x00\\x80\\x80\\x00\\x80\\x00\\x80\\x80\\x80\\x80\\x80@\\x00\\x00\\xc0\\x00\\x00@\\x80\\x00\\xc0\\x80\\x00@\\x00\\x80\\xc0\\x00\\x80@\\x80\\x80\\xc0\\x80\\x80\\x00@\\x00\\x80@\\x00\\x00\\xc0\\x00\\x80\\xc0\\x00\\x00@\\x80\\x80@\\x80\\x00\\xc0\\x80\\x80\\xc0\\x80@@\\x00\\xc0@\\x00@\\xc0\\x00\\xc0\\xc0\\x00@@\\x80\\xc0@\\x80@\\xc0\\x80\\xc0\\xc0\\x80\\x00\\x00@\\x80\\x00@\\x00\\x80@\\x80\\x80@\\x00\\x00\\xc0\\x80\\x00\\xc0\\x00\\x80\\xc0\\x80\\x80\\xc0@\\x00@\\xc0\\x00@@\\x80@\\xc0\\x80@@\\x00\\xc0\\xc0\\x00\\xc0@\\x80\\xc0\\xc0\\x80\\xc0\\x00@@\\x80@@\\x00\\xc0@\\x80\\xc0@\\x00@\\xc0\\x80@\\xc0\\x00\\xc0\\xc0\\x80\\xc0\\xc0@@@\\xc0@@@\\xc0@\\xc0\\xc0@@@\\xc0\\xc0@\\xc0@\\xc0\\xc0\\xc0\\xc0\\xc0 \\x00\\x00\\xa0\\x00\\x00 \\x80\\x00\\xa0\\x80\\x00 \\x00\\x80\\xa0\\x00\\x80 \\x80\\x80\\xa0\\x80\\x80`\\x00\\x00\\xe0\\x00\\x00`\\x80\\x00\\xe0\\x80\\x00`\\x00\\x80\\xe0\\x00\\x80`\\x80\\x80\\xe0\\x80\\x80 @\\x00\\xa0@\\x00 \\xc0\\x00\\xa0\\xc0\\x00 @\\x80\\xa0@\\x80 \\xc0\\x80\\xa0\\xc0\\x80`@\\x00\\xe0@\\x00`\\xc0\\x00\\xe0\\xc0\\x00`@\\x80\\xe0@\\x80`\\xc0\\x80\\xe0\\xc0\\x80 \\x00@\\xa0\\x00@ \\x80@\\xa0\\x80@ \\x00\\xc0\\xa0\\x00\\xc0 \\x80\\xc0\\xa0\\x80\\xc0`\\x00@\\xe0\\x00@`\\x80@\\xe0\\x80@`\\x00\\xc0\\xe0\\x00\\xc0`\\x80\\xc0\\xe0\\x80\\xc0 @@\\xa0@@ \\xc0@\\xa0\\xc0@ @\\xc0\\xa0@\\xc0 \\xc0\\xc0\\xa0\\xc0\\xc0`@@\\xe0@@`\\xc0@\\xe0\\xc0@`@\\xc0\\xe0@\\xc0`\\xc0\\xc0\\xe0\\xc0\\xc0\\x00 \\x00\\x80 \\x00\\x00\\xa0\\x00\\x80\\xa0\\x00\\x00 \\x80\\x80 \\x80\\x00\\xa0\\x80\\x80\\xa0\\x80@ \\x00\\xc0 \\x00@\\xa0\\x00\\xc0\\xa0\\x00@ \\x80\\xc0 \\x80@\\xa0\\x80\\xc0\\xa0\\x80\\x00`\\x00\\x80`\\x00\\x00\\xe0\\x00\\x80\\xe0\\x00\\x00`\\x80\\x80`\\x80\\x00\\xe0\\x80\\x80\\xe0\\x80@`\\x00\\xc0`\\x00@\\xe0\\x00\\xc0\\xe0\\x00@`\\x80\\xc0`\\x80@\\xe0\\x80\\xc0\\xe0\\x80\\x00 @\\x80 @\\x00\\xa0@\\x80\\xa0@\\x00 \\xc0\\x80 \\xc0\\x00\\xa0\\xc0\\x80\\xa0\\xc0@ @\\xc0 @@\\xa0@\\xc0\\xa0@@ \\xc0\\xc0 \\xc0@\\xa0\\xc0\\xc0\\xa0\\xc0\\x00`@\\x80`@\\x00\\xe0@\\x80\\xe0@\\x00`\\xc0\\x80`\\xc0\\x00\\xe0\\xc0\\x80\\xe0\\xc0@`@\\xc0`@@\\xe0@\\xc0\\xe0@@`\\xc0\\xc0`\\xc0@\\xe0\\xc0\\xc0\\xe0\\xc0  \\x00\\xa0 \\x00 \\xa0\\x00\\xa0\\xa0\\x00  \\x80\\xa0 \\x80 \\xa0\\x80\\xa0\\xa0\\x80` \\x00\\xe0 \\x00`\\xa0\\x00\\xe0\\xa0\\x00` \\x80\\xe0 \\x80`\\xa0\\x80\\xe0\\xa0\\x80 `\\x00\\xa0`\\x00 \\xe0\\x00\\xa0\\xe0\\x00 `\\x80\\xa0`\\x80 \\xe0\\x80\\xa0\\xe0\\x80``\\x00\\xe0`\\x00`\\xe0\\x00\\xe0\\xe0\\x00``\\x80\\xe0`\\x80`\\xe0\\x80\\xe0\\xe0\\x80  @\\xa0 @ \\xa0@\\xa0\\xa0@  \\xc0\\xa0 \\xc0 \\xa0\\xc0\\xa0\\xa0\\xc0` @\\xe0 @`\\xa0@\\xe0\\xa0@` \\xc0\\xe0 \\xc0`\\xa0\\xc0\\xe0\\xa0\\xc0 `@\\xa0`@ \\xe0@\\xa0\\xe0@ `\\xc0\\xa0`\\xc0 \\xe0\\xc0\\xa0\\xe0\\xc0``@\\xe0`@`\\xe0@\\xe0\\xe0@``\\xc0\\xe0`\\xc0`\\xe0\\xc0\\xe0\\xe0\\xc0"\n\n\ndef load_ann_png(path):\n    """Load a PNG file as a mask and its palette."""\n    mask = Image.open(path)\n    palette = mask.getpalette()\n    mask = np.array(mask).astype(np.uint8)\n    return mask, palette\n\n\ndef save_ann_png(path, mask, palette):\n    """Save a mask as a PNG file with the given palette."""\n    assert mask.dtype == np.uint8\n    assert mask.ndim == 2\n    output_mask = Image.fromarray(mask)\n    output_mask.putpalette(palette)\n    output_mask.save(path)\n\n\ndef get_per_obj_mask(mask):\n    """Split a mask into per-object masks."""\n    object_ids = np.unique(mask)\n    object_ids = object_ids[object_ids > 0].tolist()\n    per_obj_mask = {object_id: (mask == object_id) for object_id in object_ids}\n    return per_obj_mask\n\n\ndef put_per_obj_mask(per_obj_mask, height, width):\n    """Combine per-object masks into a single mask."""\n    mask = np.zeros((height, width), dtype=np.uint8)\n    object_ids = sorted(per_obj_mask)[::-1]\n    for object_id in object_ids:\n        object_mask = per_obj_mask[object_id]\n        object_mask = object_mask.reshape(height, width)\n        mask[object_mask] = object_id\n    return mask\n\n\ndef load_masks_from_dir(\n    input_mask_dir, video_name, frame_name, per_obj_png_file, allow_missing=False\n):\n    """Load masks from a directory as a dict of per-object masks."""\n    if not per_obj_png_file:\n        input_mask_path = os.path.join(input_mask_dir, video_name, f"{frame_name}.png")\n        if allow_missing and not os.path.exists(input_mask_path):\n            return {}, None\n        input_mask, input_palette = load_ann_png(input_mask_path)\n        per_obj_input_mask = get_per_obj_mask(input_mask)\n    else:\n        per_obj_input_mask = {}\n        input_palette = None\n        # each object is a directory in "{object_id:%03d}" format\n        for object_name in os.listdir(os.path.join(input_mask_dir, video_name)):\n            object_id = int(object_name)\n            input_mask_path = os.path.join(\n                input_mask_dir, video_name, object_name, f"{frame_name}.png"\n            )\n            if allow_missing and not os.path.exists(input_mask_path):\n                continue\n            input_mask, input_palette = load_ann_png(input_mask_path)\n            per_obj_input_mask[object_id] = input_mask > 0\n\n    return per_obj_input_mask, input_palette\n\n\ndef save_masks_to_dir(\n    output_mask_dir,\n    video_name,\n    frame_name,\n    per_obj_output_mask,\n    height,\n    width,\n    per_obj_png_file,\n    output_palette,\n):\n    """Save masks to a directory as PNG files."""\n    os.makedirs(os.path.join(output_mask_dir, video_name), exist_ok=True)\n    if not per_obj_png_file:\n        output_mask = put_per_obj_mask(per_obj_output_mask, height, width)\n        output_mask_path = os.path.join(\n            output_mask_dir, video_name, f"{frame_name}.png"\n        )\n        save_ann_png(output_mask_path, output_mask, output_palette)\n    else:\n        for object_id, object_mask in per_obj_output_mask.items():\n            object_name = f"{object_id:03d}"\n            os.makedirs(\n                os.path.join(output_mask_dir, video_name, object_name),\n                exist_ok=True,\n            )\n            output_mask = object_mask.reshape(height, width).astype(np.uint8)\n            output_mask_path = os.path.join(\n                output_mask_dir, video_name, object_name, f"{frame_name}.png"\n            )\n            save_ann_png(output_mask_path, output_mask, output_palette)\n\n\n@torch.inference_mode()\n@torch.autocast(device_type="cuda", dtype=torch.bfloat16)\ndef vos_inference(\n    predictor,\n    base_video_dir,\n    input_mask_dir,\n    output_mask_dir,\n    video_name,\n    score_thresh=0.0,\n    use_all_masks=False,\n    per_obj_png_file=False,\n):\n    """Run VOS inference on a single video with the given predictor."""\n    # load the video frames and initialize the inference state on this video\n    video_dir = os.path.join(base_video_dir, video_name)\n    frame_names = [\n        os.path.splitext(p)[0]\n        for p in os.listdir(video_dir)\n        if os.path.splitext(p)[-1] in [".jpg", ".jpeg", ".JPG", ".JPEG"]\n    ]\n    frame_names.sort(key=lambda p: int(os.path.splitext(p)[0]))\n    inference_state = predictor.init_state(\n        video_path=video_dir, async_loading_frames=False\n    )\n    height = inference_state["video_height"]\n    width = inference_state["video_width"]\n    input_palette = None\n\n    # fetch mask inputs from input_mask_dir (either only mask for the first frame, or all available masks)\n    if not use_all_masks:\n        # use only the first video\'s ground-truth mask as the input mask\n        input_frame_inds = [0]\n    else:\n        # use all mask files available in the input_mask_dir as the input masks\n        if not per_obj_png_file:\n            input_frame_inds = [\n                idx\n                for idx, name in enumerate(frame_names)\n                if os.path.exists(\n                    os.path.join(input_mask_dir, video_name, f"{name}.png")\n                )\n            ]\n        else:\n            input_frame_inds = [\n                idx\n                for object_name in os.listdir(os.path.join(input_mask_dir, video_name))\n                for idx, name in enumerate(frame_names)\n                if os.path.exists(\n                    os.path.join(input_mask_dir, video_name, object_name, f"{name}.png")\n                )\n            ]\n        # check and make sure we got at least one input frame\n        if len(input_frame_inds) == 0:\n            raise RuntimeError(\n                f"In {video_name=}, got no input masks in {input_mask_dir=}. "\n                "Please make sure the input masks are available in the correct format."\n            )\n        input_frame_inds = sorted(set(input_frame_inds))\n\n    # add those input masks to SAM 2 inference state before propagation\n    object_ids_set = None\n    for input_frame_idx in input_frame_inds:\n        try:\n            per_obj_input_mask, input_palette = load_masks_from_dir(\n                input_mask_dir=input_mask_dir,\n                video_name=video_name,\n                frame_name=frame_names[input_frame_idx],\n                per_obj_png_file=per_obj_png_file,\n            )\n        except FileNotFoundError as e:\n            raise RuntimeError(\n                f"In {video_name=}, failed to load input mask for frame {input_frame_idx=}. "\n                "Please add the `--track_object_appearing_later_in_video` flag "\n                "for VOS datasets that don\'t have all objects to track appearing "\n                "in the first frame (such as LVOS or YouTube-VOS)."\n            ) from e\n        # get the list of object ids to track from the first input frame\n        if object_ids_set is None:\n            object_ids_set = set(per_obj_input_mask)\n        for object_id, object_mask in per_obj_input_mask.items():\n            # check and make sure no new object ids appear only in later frames\n            if object_id not in object_ids_set:\n                raise RuntimeError(\n                    f"In {video_name=}, got a new {object_id=} appearing only in a "\n                    f"later {input_frame_idx=} (but not appearing in the first frame). "\n                    "Please add the `--track_object_appearing_later_in_video` flag "\n                    "for VOS datasets that don\'t have all objects to track appearing "\n                    "in the first frame (such as LVOS or YouTube-VOS)."\n                )\n            predictor.add_new_mask(\n                inference_state=inference_state,\n                frame_idx=input_frame_idx,\n                obj_id=object_id,\n                mask=object_mask,\n            )\n\n    # check and make sure we have at least one object to track\n    if object_ids_set is None or len(object_ids_set) == 0:\n        raise RuntimeError(\n            f"In {video_name=}, got no object ids on {input_frame_inds=}. "\n            "Please add the `--track_object_appearing_later_in_video` flag "\n            "for VOS datasets that don\'t have all objects to track appearing "\n            "in the first frame (such as LVOS or YouTube-VOS)."\n        )\n    # run propagation throughout the video and collect the results in a dict\n    os.makedirs(os.path.join(output_mask_dir, video_name), exist_ok=True)\n    output_palette = input_palette or DAVIS_PALETTE\n    video_segments = {}  # video_segments contains the per-frame segmentation results\n    for out_frame_idx, out_obj_ids, out_mask_logits in predictor.propagate_in_video(\n        inference_state\n    ):\n        per_obj_output_mask = {\n            out_obj_id: (out_mask_logits[i] > score_thresh).cpu().numpy()\n            for i, out_obj_id in enumerate(out_obj_ids)\n        }\n        video_segments[out_frame_idx] = per_obj_output_mask\n\n    # write the output masks as palette PNG files to output_mask_dir\n    for out_frame_idx, per_obj_output_mask in video_segments.items():\n        save_masks_to_dir(\n            output_mask_dir=output_mask_dir,\n            video_name=video_name,\n            frame_name=frame_names[out_frame_idx],\n            per_obj_output_mask=per_obj_output_mask,\n            height=height,\n            width=width,\n            per_obj_png_file=per_obj_png_file,\n            output_palette=output_palette,\n        )\n\n\n@torch.inference_mode()\n@torch.autocast(device_type="cuda", dtype=torch.bfloat16)\ndef vos_separate_inference_per_object(\n    predictor,\n    base_video_dir,\n    input_mask_dir,\n    output_mask_dir,\n    video_name,\n    score_thresh=0.0,\n    use_all_masks=False,\n    per_obj_png_file=False,\n):\n    """\n    Run VOS inference on a single video with the given predictor.\n\n    Unlike `vos_inference`, this function run inference separately for each object\n    in a video, which could be applied to datasets like LVOS or YouTube-VOS that\n    don\'t have all objects to track appearing in the first frame (i.e. some objects\n    might appear only later in the video).\n    """\n    # load the video frames and initialize the inference state on this video\n    video_dir = os.path.join(base_video_dir, video_name)\n    frame_names = [\n        os.path.splitext(p)[0]\n        for p in os.listdir(video_dir)\n        if os.path.splitext(p)[-1] in [".jpg", ".jpeg", ".JPG", ".JPEG"]\n    ]\n    frame_names.sort(key=lambda p: int(os.path.splitext(p)[0]))\n    inference_state = predictor.init_state(\n        video_path=video_dir, async_loading_frames=False\n    )\n    height = inference_state["video_height"]\n    width = inference_state["video_width"]\n    input_palette = None\n\n    # collect all the object ids and their input masks\n    inputs_per_object = defaultdict(dict)\n    for idx, name in enumerate(frame_names):\n        if per_obj_png_file or os.path.exists(\n            os.path.join(input_mask_dir, video_name, f"{name}.png")\n        ):\n            per_obj_input_mask, input_palette = load_masks_from_dir(\n                input_mask_dir=input_mask_dir,\n                video_name=video_name,\n                frame_name=frame_names[idx],\n                per_obj_png_file=per_obj_png_file,\n                allow_missing=True,\n            )\n            for object_id, object_mask in per_obj_input_mask.items():\n                # skip empty masks\n                if not np.any(object_mask):\n                    continue\n                # if `use_all_masks=False`, we only use the first mask for each object\n                if len(inputs_per_object[object_id]) > 0 and not use_all_masks:\n                    continue\n                print(f"adding mask from frame {idx} as input for {object_id=}")\n                inputs_per_object[object_id][idx] = object_mask\n\n    # run inference separately for each object in the video\n    object_ids = sorted(inputs_per_object)\n    output_scores_per_object = defaultdict(dict)\n    for object_id in object_ids:\n        # add those input masks to SAM 2 inference state before propagation\n        input_frame_inds = sorted(inputs_per_object[object_id])\n        predictor.reset_state(inference_state)\n        for input_frame_idx in input_frame_inds:\n            predictor.add_new_mask(\n                inference_state=inference_state,\n                frame_idx=input_frame_idx,\n                obj_id=object_id,\n                mask=inputs_per_object[object_id][input_frame_idx],\n            )\n\n        # run propagation throughout the video and collect the results in a dict\n        for out_frame_idx, _, out_mask_logits in predictor.propagate_in_video(\n            inference_state,\n            start_frame_idx=min(input_frame_inds),\n            reverse=False,\n        ):\n            obj_scores = out_mask_logits.cpu().numpy()\n            output_scores_per_object[object_id][out_frame_idx] = obj_scores\n\n    # post-processing: consolidate the per-object scores into per-frame masks\n    os.makedirs(os.path.join(output_mask_dir, video_name), exist_ok=True)\n    output_palette = input_palette or DAVIS_PALETTE\n    video_segments = {}  # video_segments contains the per-frame segmentation results\n    for frame_idx in range(len(frame_names)):\n        scores = torch.full(\n            size=(len(object_ids), 1, height, width),\n            fill_value=-1024.0,\n            dtype=torch.float32,\n        )\n        for i, object_id in enumerate(object_ids):\n            if frame_idx in output_scores_per_object[object_id]:\n                scores[i] = torch.from_numpy(\n                    output_scores_per_object[object_id][frame_idx]\n                )\n\n        if not per_obj_png_file:\n            scores = predictor._apply_non_overlapping_constraints(scores)\n        per_obj_output_mask = {\n            object_id: (scores[i] > score_thresh).cpu().numpy()\n            for i, object_id in enumerate(object_ids)\n        }\n        video_segments[frame_idx] = per_obj_output_mask\n\n    # write the output masks as palette PNG files to output_mask_dir\n    for frame_idx, per_obj_output_mask in video_segments.items():\n        save_masks_to_dir(\n            output_mask_dir=output_mask_dir,\n            video_name=video_name,\n            frame_name=frame_names[frame_idx],\n            per_obj_output_mask=per_obj_output_mask,\n            height=height,\n            width=width,\n            per_obj_png_file=per_obj_png_file,\n            output_palette=output_palette,\n        )\n\n\ndef main():\n    parser = argparse.ArgumentParser()\n    parser.add_argument(\n        "--sam2_cfg",\n        type=str,\n        default="configs/edgetam.yaml",\n        help="SAM 2 model configuration file",\n    )\n    parser.add_argument(\n        "--sam2_checkpoint",\n        type=str,\n        default="./checkpoints/edgetam.pt",\n        help="path to the SAM 2 model checkpoint",\n    )\n    parser.add_argument(\n        "--base_video_dir",\n        type=str,\n        required=True,\n        help="directory containing videos (as JPEG files) to run VOS prediction on",\n    )\n    parser.add_argument(\n        "--input_mask_dir",\n        type=str,\n        required=True,\n        help="directory containing input masks (as PNG files) of each video",\n    )\n    parser.add_argument(\n        "--video_list_file",\n        type=str,\n        default=None,\n        help="text file containing the list of video names to run VOS prediction on",\n    )\n    parser.add_argument(\n        "--output_mask_dir",\n        type=str,\n        required=True,\n        help="directory to save the output masks (as PNG files)",\n    )\n    parser.add_argument(\n        "--score_thresh",\n        type=float,\n        default=0.0,\n        help="threshold for the output mask logits (default: 0.0)",\n    )\n    parser.add_argument(\n        "--use_all_masks",\n        action="store_true",\n        help="whether to use all available PNG files in input_mask_dir "\n        "(default without this flag: just the first PNG file as input to the SAM 2 model; "\n        "usually we don\'t need this flag, since semi-supervised VOS evaluation usually takes input from the first frame only)",\n    )\n    parser.add_argument(\n        "--per_obj_png_file",\n        action="store_true",\n        help="whether use separate per-object PNG files for input and output masks "\n        "(default without this flag: all object masks are packed into a single PNG file on each frame following DAVIS format; "\n        "note that the SA-V dataset stores each object mask as an individual PNG file and requires this flag)",\n    )\n    parser.add_argument(\n        "--apply_postprocessing",\n        action="store_true",\n        help="whether to apply postprocessing (e.g. hole-filling) to the output masks "\n        "(we don\'t apply such post-processing in the SAM 2 model evaluation)",\n    )\n    parser.add_argument(\n        "--track_object_appearing_later_in_video",\n        action="store_true",\n        help="whether to track objects that appear later in the video (i.e. not on the first frame; "\n        "some VOS datasets like LVOS or YouTube-VOS don\'t have all objects appearing in the first frame)",\n    )\n    args = parser.parse_args()\n\n    # if we use per-object PNG files, they could possibly overlap in inputs and outputs\n    hydra_overrides_extra = [\n        "++model.non_overlap_masks=" + ("false" if args.per_obj_png_file else "true")\n    ]\n    predictor = build_sam2_video_predictor(\n        config_file=args.sam2_cfg,\n        ckpt_path=args.sam2_checkpoint,\n        apply_postprocessing=args.apply_postprocessing,\n        hydra_overrides_extra=hydra_overrides_extra,\n    )\n\n    if args.use_all_masks:\n        print("using all available masks in input_mask_dir as input to the SAM 2 model")\n    else:\n        print(\n            "using only the first frame\'s mask in input_mask_dir as input to the SAM 2 model"\n        )\n    # if a video list file is provided, read the video names from the file\n    # (otherwise, we use all subdirectories in base_video_dir)\n    if args.video_list_file is not None:\n        with open(args.video_list_file, "r") as f:\n            video_names = [v.strip() for v in f.readlines()]\n    else:\n        video_names = [\n            p\n            for p in os.listdir(args.base_video_dir)\n            if os.path.isdir(os.path.join(args.base_video_dir, p))\n        ]\n    print(f"running VOS prediction on {len(video_names)} videos:\\n{video_names}")\n\n    for n_video, video_name in enumerate(video_names):\n        print(f"\\n{n_video + 1}/{len(video_names)} - running on {video_name}")\n        if not args.track_object_appearing_later_in_video:\n            vos_inference(\n                predictor=predictor,\n                base_video_dir=args.base_video_dir,\n                input_mask_dir=args.input_mask_dir,\n                output_mask_dir=args.output_mask_dir,\n                video_name=video_name,\n                score_thresh=args.score_thresh,\n                use_all_masks=args.use_all_masks,\n                per_obj_png_file=args.per_obj_png_file,\n            )\n        else:\n            vos_separate_inference_per_object(\n                predictor=predictor,\n                base_video_dir=args.base_video_dir,\n                input_mask_dir=args.input_mask_dir,\n                output_mask_dir=args.output_mask_dir,\n                video_name=video_name,\n                score_thresh=args.score_thresh,\n                use_all_masks=args.use_all_masks,\n                per_obj_png_file=args.per_obj_png_file,\n            )\n\n    print(\n        f"completed VOS prediction on {len(video_names)} videos -- "\n        f"output masks saved to {args.output_mask_dir}"\n    )\n\n\nif __name__ == "__main__":\n    main()\n', '_shared_test_resources/code/EdgeTAM/checkpoints/download_ckpts.sh': '#!/bin/bash\n\n# Copyright (c) Meta Platforms, Inc. and affiliates.\n# All rights reserved.\n\n# This source code is licensed under the license found in the\n# LICENSE file in the root directory of this source tree.\n\n# Use either wget or curl to download the checkpoints\nif command -v wget &> /dev/null; then\n    CMD="wget"\nelif command -v curl &> /dev/null; then\n    CMD="curl -L -O"\nelse\n    echo "Please install wget or curl to download the checkpoints."\n    exit 1\nfi\n\n# Define the URLs for SAM 2 checkpoints\n# SAM2_BASE_URL="https://dl.fbaipublicfiles.com/segment_anything_2/072824"\n# sam2_hiera_t_url="${SAM2_BASE_URL}/sam2_hiera_tiny.pt"\n# sam2_hiera_s_url="${SAM2_BASE_URL}/sam2_hiera_small.pt"\n# sam2_hiera_b_plus_url="${SAM2_BASE_URL}/sam2_hiera_base_plus.pt"\n# sam2_hiera_l_url="${SAM2_BASE_URL}/sam2_hiera_large.pt"\n\n# Download each of the four checkpoints using wget\n# echo "Downloading sam2_hiera_tiny.pt checkpoint..."\n# $CMD $sam2_hiera_t_url || { echo "Failed to download checkpoint from $sam2_hiera_t_url"; exit 1; }\n\n# echo "Downloading sam2_hiera_small.pt checkpoint..."\n# $CMD $sam2_hiera_s_url || { echo "Failed to download checkpoint from $sam2_hiera_s_url"; exit 1; }\n\n# echo "Downloading sam2_hiera_base_plus.pt checkpoint..."\n# $CMD $sam2_hiera_b_plus_url || { echo "Failed to download checkpoint from $sam2_hiera_b_plus_url"; exit 1; }\n\n# echo "Downloading sam2_hiera_large.pt checkpoint..."\n# $CMD $sam2_hiera_l_url || { echo "Failed to download checkpoint from $sam2_hiera_l_url"; exit 1; }\n\n# Define the URLs for SAM 2.1 checkpoints\nSAM2p1_BASE_URL="https://dl.fbaipublicfiles.com/segment_anything_2/092824"\nsam2p1_hiera_t_url="${SAM2p1_BASE_URL}/sam2.1_hiera_tiny.pt"\nsam2p1_hiera_s_url="${SAM2p1_BASE_URL}/sam2.1_hiera_small.pt"\nsam2p1_hiera_b_plus_url="${SAM2p1_BASE_URL}/sam2.1_hiera_base_plus.pt"\nsam2p1_hiera_l_url="${SAM2p1_BASE_URL}/sam2.1_hiera_large.pt"\n\n# SAM 2.1 checkpoints\necho "Downloading sam2.1_hiera_tiny.pt checkpoint..."\n$CMD $sam2p1_hiera_t_url || { echo "Failed to download checkpoint from $sam2p1_hiera_t_url"; exit 1; }\n\necho "Downloading sam2.1_hiera_small.pt checkpoint..."\n$CMD $sam2p1_hiera_s_url || { echo "Failed to download checkpoint from $sam2p1_hiera_s_url"; exit 1; }\n\necho "Downloading sam2.1_hiera_base_plus.pt checkpoint..."\n$CMD $sam2p1_hiera_b_plus_url || { echo "Failed to download checkpoint from $sam2p1_hiera_b_plus_url"; exit 1; }\n\necho "Downloading sam2.1_hiera_large.pt checkpoint..."\n$CMD $sam2p1_hiera_l_url || { echo "Failed to download checkpoint from $sam2p1_hiera_l_url"; exit 1; }\n\necho "All checkpoints are downloaded successfully."\n', '_shared_test_resources/code/EdgeTAM/coreml/benchmark_coreml.py': '#!/usr/bin/env python3\n\n# Copyright (c) Meta Platforms, Inc. and affiliates.\n# All rights reserved.\n\n# This source code is licensed under the license found in the\n# LICENSE file in the root directory of this source tree.\n\n"""Benchmark EdgeTAM PyTorch vs CoreML performance.\n\nAuthor: Krish Mehta (https://github.com/DjKesu)\n"""\n\nimport os\nimport sys\nimport time\nfrom statistics import mean, stdev\n\nimport coremltools as ct\nimport numpy as np\nimport torch\nfrom hydra import compose, initialize_config_dir\nfrom hydra.core.global_hydra import GlobalHydra\nfrom hydra.utils import instantiate\nfrom omegaconf import OmegaConf\nfrom PIL import Image, ImageDraw\n\nsys.path.append(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))\nfrom sam2.build_sam import _load_checkpoint\nfrom sam2.sam2_image_predictor import SAM2ImagePredictor\n\n\ndef load_pytorch_model():\n    """Load PyTorch EdgeTAM model."""\n    device = torch.device("cpu")\n    GlobalHydra.instance().clear()\n\n    config_path = os.path.abspath("sam2/configs/edgetam.yaml")\n    config_dir = os.path.dirname(config_path)\n    config_name = os.path.splitext(os.path.basename(config_path))[0]\n\n    with initialize_config_dir(config_dir=config_dir, version_base=None):\n        cfg = compose(config_name=config_name)\n        OmegaConf.resolve(cfg)\n        model = instantiate(cfg.model, _recursive_=True)\n        _load_checkpoint(model, "checkpoints/edgetam.pt")\n        model = model.to(device)\n        model.eval()\n\n    return model\n\n\ndef load_coreml_models():\n    """Load CoreML models."""\n    image_encoder = ct.models.MLModel("./coreml_models/edgetam_image_encoder.mlpackage")\n    prompt_encoder = ct.models.MLModel(\n        "./coreml_models/edgetam_prompt_encoder.mlpackage"\n    )\n    mask_decoder = ct.models.MLModel("./coreml_models/edgetam_mask_decoder.mlpackage")\n\n    return image_encoder, prompt_encoder, mask_decoder\n\n\ndef create_test_image():\n    """Create a test image with shapes."""\n    image = Image.new("RGB", (1024, 1024), color="lightblue")\n    draw = ImageDraw.Draw(image)\n    draw.ellipse([200, 200, 400, 400], fill="red", outline="darkred", width=3)\n    draw.rectangle([600, 300, 800, 500], fill="green", outline="darkgreen", width=3)\n    return image\n\n\ndef benchmark_pytorch(model, image, point_x, point_y, num_runs=10):\n    """Benchmark PyTorch model."""\n    predictor = SAM2ImagePredictor(model)\n\n    # Warmup run\n    predictor.set_image(np.array(image))\n    _ = predictor.predict(\n        point_coords=np.array([[point_x, point_y]]),\n        point_labels=np.array([1]),\n        multimask_output=True,\n    )\n\n    # Pre-encode image once (fair comparison with CoreML)\n    predictor.set_image(np.array(image))\n\n    times = []\n    for i in range(num_runs):\n        start_time = time.perf_counter()\n\n        masks, scores, _ = predictor.predict(\n            point_coords=np.array([[point_x, point_y]]),\n            point_labels=np.array([1]),\n            multimask_output=True,\n        )\n\n        end_time = time.perf_counter()\n        times.append((end_time - start_time) * 1000)  # Convert to ms\n\n    best_idx = np.argmax(scores)\n    best_mask = masks[best_idx]\n    best_score = scores[best_idx]\n\n    return times, best_mask, best_score\n\n\ndef benchmark_coreml(models, image, point_x, point_y, pytorch_model, num_runs=10):\n    """Benchmark CoreML models - each model handles its own processing."""\n    image_encoder, prompt_encoder, mask_decoder = models\n\n    # Pre-compute image encoding and positional encoding (done once per image in real usage)\n    encoder_out = image_encoder.predict({"image": image})\n\n    # Get proper positional encoding from pre-loaded PyTorch model\n    with torch.no_grad():\n        dense_pe = pytorch_model.sam_prompt_encoder.get_dense_pe()\n    image_pe = dense_pe.detach().numpy()\n\n    # Warmup run\n    point_coords = np.zeros((1, 4, 2), dtype=np.float32)\n    point_labels = np.full((1, 4), -1, dtype=np.float32)\n    point_coords[0, 0] = [point_x, point_y]\n    point_labels[0, 0] = 1\n\n    _ = prompt_encoder.predict(\n        {\n            "point_coords": point_coords,\n            "point_labels": point_labels,\n            "boxes": np.zeros((1, 4), dtype=np.float32),\n            "mask_input": np.zeros((1, 1, 256, 256), dtype=np.float32),\n        }\n    )\n\n    times = []\n    for i in range(num_runs):\n        start_time = time.perf_counter()\n\n        # Time only the prompt encoding + mask decoding (equivalent to PyTorch predict)\n        point_coords = np.zeros((1, 4, 2), dtype=np.float32)\n        point_labels = np.full((1, 4), -1, dtype=np.float32)\n        point_coords[0, 0] = [point_x, point_y]\n        point_labels[0, 0] = 1\n\n        prompt_out = prompt_encoder.predict(\n            {\n                "point_coords": point_coords,\n                "point_labels": point_labels,\n                "boxes": np.zeros((1, 4), dtype=np.float32),\n                "mask_input": np.zeros((1, 1, 256, 256), dtype=np.float32),\n            }\n        )\n\n        mask_out = mask_decoder.predict(\n            {\n                "image_embeddings": encoder_out["vision_features"],\n                "image_pe": image_pe,\n                "sparse_prompt_embeddings": prompt_out["sparse_embeddings"],\n                "dense_prompt_embeddings": prompt_out["dense_embeddings"],\n                "high_res_feat_0": encoder_out["high_res_feat_0"],\n                "high_res_feat_1": encoder_out["high_res_feat_1"],\n                "multimask_output": np.array([1.0], dtype=np.float32),\n            }\n        )\n\n        end_time = time.perf_counter()\n        times.append((end_time - start_time) * 1000)  # Convert to ms\n\n    # Get best mask from final run\n    masks = mask_out["masks"]\n    iou_scores = mask_out["iou_pred"]\n    best_idx = np.argmax(iou_scores)\n    best_mask = masks[0, best_idx]\n    best_score = iou_scores[0, best_idx]\n\n    # Scale mask to original size\n    from scipy import ndimage\n\n    best_mask = ndimage.zoom(best_mask, (1024 / 256, 1024 / 256), order=1)\n    best_mask = (best_mask > 0.0).astype(np.float32)\n\n    return times, best_mask, best_score\n\n\ndef run_benchmark():\n    """Run comprehensive benchmark."""\n    print("EdgeTAM Performance Benchmark")\n    print("=" * 50)\n\n    # Create test image and point\n    test_image = create_test_image()\n    point_x, point_y = 300, 300\n    num_runs = 5\n\n    print(f"Test setup: {num_runs} runs, point at ({point_x}, {point_y})")\n    print()\n\n    # Run PyTorch benchmark\n    print("=== PYTORCH BENCHMARK ===")\n    pytorch_model = load_pytorch_model()\n    pt_times, pt_mask, pt_score = benchmark_pytorch(\n        pytorch_model, test_image, point_x, point_y, num_runs\n    )\n    pt_mean = mean(pt_times)\n    pt_std = stdev(pt_times) if len(pt_times) > 1 else 0\n    pt_coverage = pt_mask.sum() / (1024 * 1024) * 100\n\n    print(f"PyTorch Results:")\n    print(f"  Average time: {pt_mean:.1f} ± {pt_std:.1f} ms")\n    print(f"  IoU Score: {pt_score:.4f}")\n    print(f"  Coverage: {pt_coverage:.1f}%")\n    print()\n\n    # Run CoreML benchmark\n    print("=== COREML BENCHMARK ===")\n    coreml_models = load_coreml_models()\n    cm_times, cm_mask, cm_score = benchmark_coreml(\n        coreml_models, test_image, point_x, point_y, pytorch_model, num_runs\n    )\n    cm_mean = mean(cm_times)\n    cm_std = stdev(cm_times) if len(cm_times) > 1 else 0\n    cm_coverage = cm_mask.sum() / (1024 * 1024) * 100\n\n    print(f"CoreML Results:")\n    print(f"  Average time: {cm_mean:.1f} ± {cm_std:.1f} ms")\n    print(f"  IoU Score: {cm_score:.4f}")\n    print(f"  Coverage: {cm_coverage:.1f}%")\n    print()\n\n    # Performance comparison\n    speedup = pt_mean / cm_mean if cm_mean > 0 else 0\n    score_diff = abs(pt_score - cm_score)\n    coverage_diff = abs(pt_coverage - cm_coverage)\n\n    print("Performance Comparison:")\n    print("=" * 30)\n    print(f"Speed comparison:")\n    if speedup > 1:\n        print(f"  CoreML is {speedup:.1f}x FASTER than PyTorch")\n    else:\n        print(f"  PyTorch is {1/speedup:.1f}x FASTER than CoreML")\n\n    print(f"Quality comparison:")\n    print(f"  Score difference: {score_diff:.4f}")\n    print(f"  Coverage difference: {coverage_diff:.1f}%")\n\n    print(f"Model size comparison:")\n    print(f"  PyTorch: 54MB")\n    print(f"  CoreML: 21.4MB (60% smaller)")\n\n    # Overall assessment\n    print()\n    print("Overall Assessment:")\n    print("=" * 20)\n    if score_diff < 0.01 and coverage_diff < 1.0:\n        print("Quality: Excellent parity between PyTorch and CoreML")\n    elif score_diff < 0.05 and coverage_diff < 2.0:\n        print("Quality: Good parity between PyTorch and CoreML")\n    else:\n        print("Quality: Some differences detected")\n\n    if speedup > 1.2:\n        print("Performance: CoreML shows significant speed improvement")\n    elif speedup > 0.8:\n        print("Performance: Comparable speed between implementations")\n    else:\n        print("Performance: PyTorch faster than CoreML")\n\n    print("Size: CoreML models are 60% smaller (21.4MB vs 54MB)")\n    print()\n\n    return {\n        "pytorch_time_ms": pt_mean,\n        "coreml_time_ms": cm_mean,\n        "speedup": speedup,\n        "pytorch_score": pt_score,\n        "coreml_score": cm_score,\n        "score_diff": score_diff,\n    }\n\n\nif __name__ == "__main__":\n    results = run_benchmark()\n', '_shared_test_resources/code/EdgeTAM/coreml/inference_example.py': '#!/usr/bin/env python3\n\n# Copyright (c) Meta Platforms, Inc. and affiliates.\n# All rights reserved.\n\n# This source code is licensed under the license found in the\n# LICENSE file in the root directory of this source tree.\n\n"""\nEdgeTAM CoreML Video Tracking Example\n\nDemonstrates how to use EdgeTAM CoreML models for video tracking with persistent masks.\nShows both single-frame segmentation and multi-frame tracking workflows.\n\nAuthor: Krish Mehta (https://github.com/DjKesu)\nEdgeTAM Model: https://github.com/chuangg/EdgeTAM\n"""\n\nimport argparse\nimport os\nimport sys\n\nimport coremltools as ct\nimport cv2\nimport numpy as np\nimport torch\nfrom PIL import Image\n\nsys.path.append(os.path.dirname(os.path.abspath(__file__)))\n\n\nclass EdgeTAMVideoTracker:\n    def __init__(self, model_dir="./coreml_models"):\n        """Initialize EdgeTAM video tracker with CoreML models."""\n        print("Loading EdgeTAM CoreML models...")\n        self.image_encoder = ct.models.MLModel(\n            f"{model_dir}/edgetam_image_encoder.mlpackage"\n        )\n        self.prompt_encoder = ct.models.MLModel(\n            f"{model_dir}/edgetam_prompt_encoder.mlpackage"\n        )\n        self.mask_decoder = ct.models.MLModel(\n            f"{model_dir}/edgetam_mask_decoder.mlpackage"\n        )\n\n        # Get positional encoding from PyTorch model if available\n        try:\n            from hydra import compose, initialize_config_dir\n            from hydra.core.global_hydra import GlobalHydra\n            from hydra.utils import instantiate\n            from omegaconf import OmegaConf\n            from sam2.build_sam import _load_checkpoint\n\n            device = torch.device("cpu")\n            GlobalHydra.instance().clear()\n\n            config_path = os.path.abspath("../sam2/configs/edgetam.yaml")\n            config_dir = os.path.dirname(config_path)\n            config_name = os.path.splitext(os.path.basename(config_path))[0]\n\n            with initialize_config_dir(config_dir=config_dir, version_base=None):\n                cfg = compose(config_name=config_name)\n                OmegaConf.resolve(cfg)\n                model = instantiate(cfg.model, _recursive_=True)\n                _load_checkpoint(model, "../checkpoints/edgetam.pt")\n                model = model.to(device).eval()\n\n                with torch.no_grad():\n                    self.image_pe = (\n                        model.sam_prompt_encoder.get_dense_pe().detach().numpy()\n                    )\n                print("Using proper positional encoding from PyTorch model")\n        except:\n            print("PyTorch model not available, using zeros for positional encoding")\n            self.image_pe = np.zeros((1, 256, 64, 64), dtype=np.float32)\n\n        self.current_embeddings = None\n        self.tracking_points = []\n\n    def encode_frame(self, frame):\n        """Encode a video frame for tracking."""\n        if isinstance(frame, np.ndarray):\n            frame = Image.fromarray(cv2.cvtColor(frame, cv2.COLOR_BGR2RGB))\n\n        frame = frame.resize((1024, 1024), Image.BILINEAR)\n        self.current_embeddings = self.image_encoder.predict({"image": frame})\n        return self.current_embeddings\n\n    def add_point(self, x, y, label=1):\n        """Add a tracking point. Label: 1=positive, 0=negative."""\n        self.tracking_points.append((x, y, label))\n\n    def clear_points(self):\n        """Clear all tracking points."""\n        self.tracking_points = []\n\n    def segment_current_frame(self, multimask=False):\n        """Generate mask for current frame using tracking points."""\n        if self.current_embeddings is None:\n            raise ValueError("No frame encoded. Call encode_frame() first.")\n\n        if not self.tracking_points:\n            raise ValueError("No tracking points. Call add_point() first.")\n\n        # Prepare point prompts\n        max_points = 4\n        point_coords = np.zeros((1, max_points, 2), dtype=np.float32)\n        point_labels = np.full((1, max_points), -1, dtype=np.float32)\n\n        for i, (x, y, label) in enumerate(self.tracking_points[:max_points]):\n            point_coords[0, i] = [x, y]\n            point_labels[0, i] = label\n\n        # Encode prompts\n        prompt_out = self.prompt_encoder.predict(\n            {\n                "point_coords": point_coords,\n                "point_labels": point_labels,\n                "boxes": np.zeros((1, 4), dtype=np.float32),\n                "mask_input": np.zeros((1, 1, 256, 256), dtype=np.float32),\n            }\n        )\n\n        # Generate mask\n        mask_out = self.mask_decoder.predict(\n            {\n                "image_embeddings": self.current_embeddings["vision_features"],\n                "image_pe": self.image_pe,\n                "sparse_prompt_embeddings": prompt_out["sparse_embeddings"],\n                "dense_prompt_embeddings": prompt_out["dense_embeddings"],\n                "high_res_feat_0": self.current_embeddings["high_res_feat_0"],\n                "high_res_feat_1": self.current_embeddings["high_res_feat_1"],\n                "multimask_output": np.array(\n                    [1.0 if multimask else 0.0], dtype=np.float32\n                ),\n            }\n        )\n\n        masks = mask_out["masks"]\n        iou_scores = mask_out["iou_pred"]\n\n        if multimask:\n            best_idx = np.argmax(iou_scores)\n            return masks[0, best_idx], iou_scores[0, best_idx]\n        else:\n            return masks[0, 0], iou_scores[0, 0]\n\n\ndef track_video_example(video_path=None, save_output=False):\n    """Example: Track objects in a video stream."""\n    tracker = EdgeTAMVideoTracker()\n\n    # Initialize video capture (webcam or video file)\n    if video_path:\n        cap = cv2.VideoCapture(video_path)\n        print(f"Processing video: {video_path}")\n    else:\n        cap = cv2.VideoCapture(0)  # Use webcam\n        print("Video tracking started. Click on objects to track them.")\n\n    print("Press \'c\' to clear points, \'q\' to quit")\n\n    # Setup video writer if saving output\n    video_writer = None\n    if save_output:\n        fps = int(cap.get(cv2.CAP_PROP_FPS))\n        width = int(cap.get(cv2.CAP_PROP_FRAME_WIDTH))\n        height = int(cap.get(cv2.CAP_PROP_FRAME_HEIGHT))\n        output_path = "tracked_output.mp4"\n        fourcc = cv2.VideoWriter_fourcc(*"mp4v")\n        video_writer = cv2.VideoWriter(output_path, fourcc, fps, (width, height))\n        print(f"Saving output to: {output_path}")\n\n    def mouse_callback(event, x, y, flags, param):\n        if event == cv2.EVENT_LBUTTONDOWN:\n            # Convert from display coordinates to model coordinates\n            model_x = int(x * 1024 / frame.shape[1])\n            model_y = int(y * 1024 / frame.shape[0])\n            tracker.add_point(model_x, model_y, label=1)\n            print(f"Added tracking point at ({model_x}, {model_y})")\n\n    cv2.namedWindow("EdgeTAM Video Tracking")\n    cv2.setMouseCallback("EdgeTAM Video Tracking", mouse_callback)\n\n    while True:\n        ret, frame = cap.read()\n        if not ret:\n            break\n\n        # Encode frame\n        tracker.encode_frame(frame)\n\n        # Generate mask if we have tracking points\n        if tracker.tracking_points:\n            try:\n                mask, iou = tracker.segment_current_frame(multimask=False)\n\n                # Resize mask to frame size\n                mask_resized = cv2.resize(mask, (frame.shape[1], frame.shape[0]))\n                mask_binary = (mask_resized > 0.0).astype(np.uint8) * 255\n\n                # Create colored overlay\n                overlay = frame.copy()\n                overlay[mask_binary > 0] = [0, 255, 0]  # Green overlay\n                frame = cv2.addWeighted(frame, 0.7, overlay, 0.3, 0)\n\n                # Show IoU score\n                cv2.putText(\n                    frame,\n                    f"IoU: {iou:.3f}",\n                    (10, 30),\n                    cv2.FONT_HERSHEY_SIMPLEX,\n                    1,\n                    (255, 255, 255),\n                    2,\n                )\n\n            except Exception as e:\n                print(f"Tracking error: {e}")\n\n        # Draw tracking points\n        for i, (x, y, label) in enumerate(tracker.tracking_points):\n            display_x = int(x * frame.shape[1] / 1024)\n            display_y = int(y * frame.shape[0] / 1024)\n            color = (0, 255, 0) if label == 1 else (0, 0, 255)\n            cv2.circle(frame, (display_x, display_y), 5, color, -1)\n\n        cv2.imshow("EdgeTAM Video Tracking", frame)\n\n        # Write frame to output video if saving\n        if video_writer is not None:\n            video_writer.write(frame)\n\n        key = cv2.waitKey(1) & 0xFF\n        if key == ord("q"):\n            break\n        elif key == ord("c"):\n            tracker.clear_points()\n            print("Cleared all tracking points")\n\n    cap.release()\n    if video_writer is not None:\n        video_writer.release()\n        print(f"Video saved to: {output_path}")\n    cv2.destroyAllWindows()\n\n\ndef segment_image_example():\n    """Example: Segment a single image with point prompt."""\n    tracker = EdgeTAMVideoTracker()\n\n    # Create test image\n    test_image = Image.new("RGB", (1024, 1024), color="lightblue")\n    from PIL import ImageDraw\n\n    draw = ImageDraw.Draw(test_image)\n    draw.ellipse([200, 200, 400, 400], fill="red")\n    draw.rectangle([600, 300, 800, 500], fill="green")\n\n    # Encode image\n    tracker.encode_frame(test_image)\n\n    # Add point in red circle\n    tracker.add_point(300, 300, label=1)\n\n    # Generate mask\n    mask, iou = tracker.segment_current_frame(multimask=False)\n\n    print(f"Segmentation complete! IoU: {iou:.3f}")\n    print(f"Mask shape: {mask.shape}")\n    print(f"Mask coverage: {(mask > 0.0).sum() / (1024 * 1024) * 100:.1f}%")\n\n    return mask\n\n\ndef demo_with_video(video_path=None):\n    """Demo tracking with example video.\n\n    Args:\n        video_path: Path to video file. If None, defaults to "../examples/04_coffee.mp4"\n    """\n    if video_path is None:\n        video_path = "../examples/04_coffee.mp4"\n\n    print("EdgeTAM CoreML Video Demo")\n    print("========================")\n    print(f"Processing: {video_path}")\n    print("Will automatically track object at center of frame")\n    print("Output will be saved as \'tracked_output.mp4\'")\n    print()\n\n    if not os.path.exists(video_path):\n        print(f"Video not found: {video_path}")\n        examples_dir = (\n            os.path.dirname(video_path)\n            if video_path != "../examples/04_coffee.mp4"\n            else "../examples/"\n        )\n        if os.path.exists(examples_dir):\n            print("Available videos:")\n            for f in os.listdir(examples_dir):\n                if f.endswith((".mp4", ".avi", ".mov")):\n                    print(f"  {os.path.join(examples_dir, f)}")\n        return\n\n    tracker = EdgeTAMVideoTracker()\n    cap = cv2.VideoCapture(video_path)\n\n    # Setup video writer\n    fps = int(cap.get(cv2.CAP_PROP_FPS))\n    width = int(cap.get(cv2.CAP_PROP_FRAME_WIDTH))\n    height = int(cap.get(cv2.CAP_PROP_FRAME_HEIGHT))\n    output_path = "tracked_output.mp4"\n    fourcc = cv2.VideoWriter_fourcc(*"mp4v")\n    video_writer = cv2.VideoWriter(output_path, fourcc, fps, (width, height))\n    print(f"Saving output to: {output_path}")\n\n    frame_count = 0\n    while True:\n        ret, frame = cap.read()\n        if not ret:\n            break\n\n        # Encode frame\n        tracker.encode_frame(frame)\n\n        # Add tracking point on first frame\n        if frame_count == 0:\n            # Add point on the coffee cup (center-right area where cup usually appears)\n            tracker.add_point(690, 600, label=1)  # Coffee cup position\n            print(f"Added tracking point at (690, 600) - coffee cup")\n\n        # Generate mask if we have tracking points\n        if tracker.tracking_points:\n            try:\n                mask, iou = tracker.segment_current_frame(multimask=False)\n                print(f"Frame {frame_count}: IoU {iou:.3f}")\n\n                # Resize mask to frame size\n                mask_resized = cv2.resize(mask, (frame.shape[1], frame.shape[0]))\n                mask_binary = (mask_resized > 0.0).astype(np.uint8) * 255\n\n                # Create colored overlay\n                overlay = frame.copy()\n                overlay[mask_binary > 0] = [0, 255, 0]  # Green overlay\n                frame = cv2.addWeighted(frame, 0.7, overlay, 0.3, 0)\n\n                # Show IoU score\n                cv2.putText(\n                    frame,\n                    f"IoU: {iou:.3f}",\n                    (10, 30),\n                    cv2.FONT_HERSHEY_SIMPLEX,\n                    1,\n                    (255, 255, 255),\n                    2,\n                )\n\n            except Exception as e:\n                print(f"Frame {frame_count} error: {e}")\n\n        # Draw tracking points\n        for i, (x, y, label) in enumerate(tracker.tracking_points):\n            display_x = int(x * frame.shape[1] / 1024)\n            display_y = int(y * frame.shape[0] / 1024)\n            color = (0, 255, 0) if label == 1 else (0, 0, 255)\n            cv2.circle(frame, (display_x, display_y), 5, color, -1)\n\n        # Write frame\n        video_writer.write(frame)\n        frame_count += 1\n\n        # Process only first 100 frames for demo\n        if frame_count >= 100:\n            break\n\n    cap.release()\n    video_writer.release()\n    print(f"Processed {frame_count} frames")\n    print(f"Video saved to: {output_path}")\n\n\nif __name__ == "__main__":\n    parser = argparse.ArgumentParser(\n        description="EdgeTAM CoreML Video Tracking Example"\n    )\n    parser.add_argument(\n        "--video",\n        type=str,\n        default=None,\n        help="Path to video file (default: ../examples/04_coffee.mp4)",\n    )\n    parser.add_argument(\n        "--example",\n        type=str,\n        choices=["segment", "track", "demo"],\n        default="demo",\n        help="Which example to run: segment, track, or demo (default: demo)",\n    )\n\n    args = parser.parse_args()\n\n    print("EdgeTAM CoreML Video Tracking Example")\n    print("=====================================")\n    print()\n    print("Available examples:")\n    print("1. segment_image_example() - Single image segmentation")\n    print("2. track_video_example() - Real-time video tracking")\n    print("3. demo_with_video() - Demo with example video")\n    print()\n\n    # Run demo with video by default\n    try:\n        if args.example == "segment":\n            segment_image_example()\n        elif args.example == "track":\n            track_video_example(video_path=args.video)\n        else:  # demo\n            demo_with_video(video_path=args.video)\n    except FileNotFoundError:\n        print("Error: CoreML models not found!")\n        print("Please run the export script first:")\n        print(\n            "  python coreml/export_to_coreml.py --sam2_cfg sam2/configs/edgetam.yaml --sam2_checkpoint checkpoints/edgetam.pt"\n        )\n', '_shared_test_resources/code/EdgeTAM/coreml/export_to_coreml.py': '#!/usr/bin/env python3\n\n# Copyright (c) Meta Platforms, Inc. and affiliates.\n# All rights reserved.\n\n# This source code is licensed under the license found in the\n# LICENSE file in the root directory of this source tree.\n\n"""Export EdgeTAM to CoreML format.\n\nAuthor: Krish Mehta (https://github.com/DjKesu)\n"""\n\nimport argparse\nimport json\nimport os\nimport sys\nimport warnings\nfrom typing import Tuple\n\nimport coremltools as ct\nimport numpy as np\nimport torch\nfrom hydra import compose, initialize_config_dir\nfrom hydra.core.global_hydra import GlobalHydra\nfrom hydra.utils import instantiate\nfrom omegaconf import OmegaConf\nfrom PIL import Image\n\n# Suppress warnings\nwarnings.filterwarnings(\n    "ignore", message="Torch version .* has not been tested with coremltools"\n)\nwarnings.filterwarnings("ignore", message=".*resources.bin missing.*")\n\nsys.path.append(os.path.dirname(os.path.dirname(os.path.abspath(__file__))))\n\ntry:\n    from sam2.build_sam import _load_checkpoint\nexcept ImportError as e:\n    print(f"Error importing SAM2 modules: {e}")\n    print("Please ensure you have installed EdgeTAM properly.")\n    sys.exit(1)\n\n\nclass EdgeTAMImageEncoder(torch.nn.Module):\n    """EdgeTAM Image Encoder wrapper for CoreML export."""\n\n    def __init__(self, sam_model):\n        super().__init__()\n        self.model = sam_model\n\n    def forward(\n        self, image: torch.Tensor\n    ) -> Tuple[torch.Tensor, torch.Tensor, torch.Tensor]:\n        backbone_out = self.model.forward_image(image)\n        backbone_fpn = backbone_out.get("backbone_fpn", [])\n\n        if len(backbone_fpn) >= 3:\n            vision_features = backbone_fpn[2]\n            high_res_feat_0 = backbone_fpn[0]\n            high_res_feat_1 = backbone_fpn[1]\n\n            # Add no_mem_embed to match PyTorch EdgeTAM behavior\n            if self.model.directly_add_no_mem_embed:\n                B, C, H, W = vision_features.shape\n                vision_features_flat = vision_features.flatten(2).permute(2, 0, 1)\n                vision_features_flat = (\n                    vision_features_flat + self.model.no_mem_embed.squeeze(0)\n                )\n                vision_features = vision_features_flat.permute(1, 2, 0).view(B, C, H, W)\n        else:\n            bs = image.shape[0]\n            vision_features = torch.zeros(bs, 256, 64, 64, device=image.device)\n            high_res_feat_0 = torch.zeros(bs, 32, 256, 256, device=image.device)\n            high_res_feat_1 = torch.zeros(bs, 64, 128, 128, device=image.device)\n\n        return vision_features, high_res_feat_0, high_res_feat_1\n\n\nclass EdgeTAMPromptEncoder(torch.nn.Module):\n    """EdgeTAM Prompt Encoder wrapper for CoreML export."""\n\n    def __init__(self, sam_model):\n        super().__init__()\n        self.model = sam_model\n\n    def forward(\n        self,\n        point_coords: torch.Tensor,\n        point_labels: torch.Tensor,\n        boxes: torch.Tensor,\n        mask_input: torch.Tensor,\n    ) -> Tuple[torch.Tensor, torch.Tensor]:\n\n        sparse_embeddings, dense_embeddings = self.model.sam_prompt_encoder(\n            points=(point_coords, point_labels),\n            boxes=None,\n            masks=None,\n        )\n        return sparse_embeddings, dense_embeddings\n\n\nclass EdgeTAMMaskDecoder(torch.nn.Module):\n    """EdgeTAM Mask Decoder wrapper for CoreML export."""\n\n    def __init__(self, sam_model):\n        super().__init__()\n        self.model = sam_model\n        self.mask_decoder = sam_model.sam_mask_decoder\n\n    def forward(\n        self,\n        image_embeddings: torch.Tensor,\n        image_pe: torch.Tensor,\n        sparse_prompt_embeddings: torch.Tensor,\n        dense_prompt_embeddings: torch.Tensor,\n        high_res_feat_0: torch.Tensor,\n        high_res_feat_1: torch.Tensor,\n        multimask_output: torch.Tensor,\n    ) -> Tuple[torch.Tensor, torch.Tensor]:\n\n        use_multimask = multimask_output[0].item() > 0.5\n        high_res_features = [high_res_feat_0, high_res_feat_1]\n\n        # Use proper position encoding from prompt encoder\n        proper_image_pe = self.model.sam_prompt_encoder.get_dense_pe()\n\n        sam_outputs = self.mask_decoder(\n            image_embeddings=image_embeddings,\n            image_pe=proper_image_pe,\n            sparse_prompt_embeddings=sparse_prompt_embeddings,\n            dense_prompt_embeddings=dense_prompt_embeddings,\n            multimask_output=use_multimask,\n            repeat_image=False,\n            high_res_features=high_res_features,\n        )\n\n        masks = sam_outputs[0]\n        iou_pred = sam_outputs[1]\n\n        if not use_multimask:\n            masks = masks[:, 0:1, :, :]\n            iou_pred = iou_pred[:, 0:1]\n\n        return masks, iou_pred\n\n\ndef export_image_encoder(model, output_path: str):\n    """Export image encoder to CoreML."""\n    print("Exporting Image Encoder...")\n    encoder_wrapper = EdgeTAMImageEncoder(model)\n    encoder_wrapper.eval()\n\n    example_input = torch.randn(1, 3, 1024, 1024)\n\n    with torch.no_grad():\n        traced_model = torch.jit.trace(encoder_wrapper, example_input)\n\n    image_input = ct.ImageType(\n        name="image",\n        shape=(1, 3, 1024, 1024),\n        scale=1 / 255.0,\n        bias=[0, 0, 0],\n        color_layout=ct.colorlayout.RGB,\n    )\n\n    mlmodel = ct.convert(\n        traced_model,\n        inputs=[image_input],\n        outputs=[\n            ct.TensorType(name="vision_features"),\n            ct.TensorType(name="high_res_feat_0"),\n            ct.TensorType(name="high_res_feat_1"),\n        ],\n        minimum_deployment_target=ct.target.iOS16,\n        compute_units=ct.ComputeUnit.ALL,\n        convert_to="mlprogram",\n    )\n\n    mlmodel.author = "EdgeTAM Contributors"\n    mlmodel.short_description = "EdgeTAM Image Encoder"\n    mlmodel.version = "1.0"\n\n    mlmodel.save(output_path)\n    print(f"  Saved to {output_path}")\n\n\ndef export_prompt_encoder(model, output_path: str):\n    """Export prompt encoder to CoreML."""\n    print("Exporting Prompt Encoder...")\n    encoder_wrapper = EdgeTAMPromptEncoder(model)\n    encoder_wrapper.eval()\n\n    point_coords = torch.zeros(1, 4, 2)\n    point_coords[0, 0] = torch.tensor([512.0, 512.0])\n    point_labels = torch.full((1, 4), -1, dtype=torch.float32)\n    point_labels[0, 0] = 1.0\n    boxes = torch.zeros(1, 4)\n    mask_input = torch.zeros(1, 1, 256, 256)\n\n    with torch.no_grad():\n        traced_model = torch.jit.trace(\n            encoder_wrapper, (point_coords, point_labels, boxes, mask_input)\n        )\n\n    mlmodel = ct.convert(\n        traced_model,\n        inputs=[\n            ct.TensorType(name="point_coords", shape=(1, 4, 2)),\n            ct.TensorType(name="point_labels", shape=(1, 4)),\n            ct.TensorType(name="boxes", shape=(1, 4)),\n            ct.TensorType(name="mask_input", shape=(1, 1, 256, 256)),\n        ],\n        outputs=[\n            ct.TensorType(name="sparse_embeddings"),\n            ct.TensorType(name="dense_embeddings"),\n        ],\n        minimum_deployment_target=ct.target.iOS16,\n        compute_units=ct.ComputeUnit.ALL,\n        convert_to="mlprogram",\n    )\n\n    mlmodel.author = "EdgeTAM Contributors"\n    mlmodel.short_description = "EdgeTAM Prompt Encoder"\n    mlmodel.version = "1.0"\n\n    mlmodel.save(output_path)\n    print(f"  Saved to {output_path}")\n\n\ndef export_mask_decoder(model, output_path: str):\n    """Export mask decoder to CoreML."""\n    print("Exporting Mask Decoder...")\n    decoder_wrapper = EdgeTAMMaskDecoder(model)\n    decoder_wrapper.eval()\n\n    image_embeddings = torch.randn(1, 256, 64, 64)\n    image_pe = torch.randn(1, 256, 64, 64)\n    sparse_prompt_embeddings = torch.randn(1, 2, 256)\n    dense_prompt_embeddings = torch.randn(1, 256, 64, 64)\n    high_res_feat_0 = torch.randn(1, 32, 256, 256)\n    high_res_feat_1 = torch.randn(1, 64, 128, 128)\n    multimask_output = torch.tensor([True])\n\n    with torch.no_grad():\n        traced_model = torch.jit.trace(\n            decoder_wrapper,\n            (\n                image_embeddings,\n                image_pe,\n                sparse_prompt_embeddings,\n                dense_prompt_embeddings,\n                high_res_feat_0,\n                high_res_feat_1,\n                multimask_output,\n            ),\n        )\n\n    mlmodel = ct.convert(\n        traced_model,\n        inputs=[\n            ct.TensorType(name="image_embeddings", shape=(1, 256, 64, 64)),\n            ct.TensorType(name="image_pe", shape=(1, 256, 64, 64)),\n            ct.TensorType(\n                name="sparse_prompt_embeddings", shape=(1, ct.RangeDim(1, 10), 256)\n            ),\n            ct.TensorType(name="dense_prompt_embeddings", shape=(1, 256, 64, 64)),\n            ct.TensorType(name="high_res_feat_0", shape=(1, 32, 256, 256)),\n            ct.TensorType(name="high_res_feat_1", shape=(1, 64, 128, 128)),\n            ct.TensorType(name="multimask_output", shape=(1,)),\n        ],\n        outputs=[ct.TensorType(name="masks"), ct.TensorType(name="iou_pred")],\n        minimum_deployment_target=ct.target.iOS16,\n        compute_units=ct.ComputeUnit.ALL,\n        convert_to="mlprogram",\n    )\n\n    mlmodel.author = "EdgeTAM Contributors"\n    mlmodel.short_description = "EdgeTAM Mask Decoder"\n    mlmodel.version = "1.0"\n\n    mlmodel.save(output_path)\n    print(f"  Saved to {output_path}")\n\n\ndef main():\n    parser = argparse.ArgumentParser(description="Export EdgeTAM to CoreML")\n    parser.add_argument("--sam2_cfg", required=True, help="Path to EdgeTAM config file")\n    parser.add_argument(\n        "--sam2_checkpoint", required=True, help="Path to EdgeTAM checkpoint"\n    )\n    parser.add_argument(\n        "--output_dir", default="./coreml_models", help="Output directory"\n    )\n\n    args = parser.parse_args()\n\n    os.makedirs(args.output_dir, exist_ok=True)\n\n    print("Loading EdgeTAM model...")\n    try:\n        device = torch.device("cpu")\n        GlobalHydra.instance().clear()\n\n        config_path = os.path.abspath(args.sam2_cfg)\n        config_dir = os.path.dirname(config_path)\n        config_name = os.path.splitext(os.path.basename(config_path))[0]\n\n        with initialize_config_dir(config_dir=config_dir, version_base=None):\n            cfg = compose(config_name=config_name)\n            OmegaConf.resolve(cfg)\n\n            model = instantiate(cfg.model, _recursive_=True)\n\n            if args.sam2_checkpoint:\n                _load_checkpoint(model, args.sam2_checkpoint)\n\n            model = model.to(device)\n            model.eval()\n\n    except Exception as e:\n        print(f"Failed to load EdgeTAM model: {e}")\n        sys.exit(1)\n\n    print(f"\\nExporting to {args.output_dir}...")\n\n    try:\n        export_image_encoder(\n            model, os.path.join(args.output_dir, "edgetam_image_encoder.mlpackage")\n        )\n\n        export_prompt_encoder(\n            model, os.path.join(args.output_dir, "edgetam_prompt_encoder.mlpackage")\n        )\n\n        export_mask_decoder(\n            model, os.path.join(args.output_dir, "edgetam_mask_decoder.mlpackage")\n        )\n\n        # Create simple metadata\n        metadata = {\n            "model_name": "EdgeTAM",\n            "version": "1.0",\n            "components": {\n                "image_encoder": "edgetam_image_encoder.mlpackage",\n                "prompt_encoder": "edgetam_prompt_encoder.mlpackage",\n                "mask_decoder": "edgetam_mask_decoder.mlpackage",\n            },\n        }\n\n        with open(os.path.join(args.output_dir, "model_info.json"), "w") as f:\n            json.dump(metadata, f, indent=2)\n\n        print(f"\\nExport completed successfully!")\n        print(f"Models saved to: {args.output_dir}")\n\n    except Exception as e:\n        print(f"Export failed: {e}")\n        sys.exit(1)\n\n\nif __name__ == "__main__":\n    main()\n'}
NODE_SOURCE = "// Native Transformers.js inference only. Python evaluate.py loads original GT.\nimport fs from 'node:fs';\nimport path from 'node:path';\nimport readline from 'node:readline';\nimport {AutoProcessor, RawImage, SamModel, Sam3TrackerModel, Tensor} from '@huggingface/transformers';\n\nconst [modelDir, datasetRoot, manifest, output, backend, device, batchArg] = process.argv.slice(2);\nlet safeBatch = Number(batchArg);\nif (!Number.isInteger(safeBatch) || safeBatch < 1) throw new Error('Invalid batch size');\nconst completed = new Set();\nif (fs.existsSync(output)) {\n  for await (const line of readline.createInterface({input: fs.createReadStream(output), crlfDelay: Infinity})) {\n    if (line.trim()) completed.add(JSON.parse(line).sample_id);\n  }\n}\nconsole.log(`Resume: ${completed.size} completed instances; device=${device}; batch=${safeBatch}`);\nconst processor = await AutoProcessor.from_pretrained(modelDir, {local_files_only:true});\nconst Class = backend === 'sam3_onnx' ? Sam3TrackerModel : SamModel;\nconst model = await Class.from_pretrained(modelDir, {local_files_only:true, device, dtype:'fp32'});\n// Native ORT run resolves after host outputs are ready, including CUDA work.\n// Wrap graph execution only, outside processor calls and mask decoding.\nlet forwardSeconds = 0;\nfor (const session of Object.values(model.sessions)) {\n  const originalRun = session.run.bind(session);\n  session.run = async (...args) => {\n    const begin = process.hrtime.bigint();\n    const result = await originalRun(...args);\n    forwardSeconds += Number(process.hrtime.bigint() - begin) / 1e9;\n    return result;\n  };\n}\nconst handle = fs.openSync(output, 'a');\nlet processed = 0, seen = completed.size;\nconst started = Date.now();\nconst dispose = values => {for (const v of values) v?.dispose?.();};\nfunction encode(values, offset, height, width) {\n  const counts = [];\n  let previous = false, count = 0;\n  // COCO RLE is column-major; postprocessed ONNX tensors are row-major.\n  for (let x=0; x<width; x++) for (let y=0; y<height; y++) {\n    const bit = values[offset+y*width+x] > 0;\n    if (bit===previous) count++;\n    else {counts.push(count);count=1;previous=bit;}\n  }\n  counts.push(count);\n  return {size:[height,width],counts};\n}\nasync function inferGroup(group) {\n  const pending = group.filter(x => !completed.has(x.sample_id));\n  if (!pending.length) return;\n  const image = await RawImage.read(path.join(datasetRoot,group[0].image));\n  const inputs = await processor(image);\n  forwardSeconds = 0;\n  const embeddings = await model.get_image_embeddings(inputs);\n  let encoderSeconds = forwardSeconds;\n  inputs.pixel_values.dispose?.();\n  for (let begin=0; begin<pending.length;) {\n    const batch = pending.slice(begin,begin+safeBatch);\n    const points = processor.reshape_input_points([batch.map(x=>[[...x.point]])],inputs.original_sizes,inputs.reshaped_input_sizes);\n    const labels = processor.image_processor.add_input_labels([batch.map(()=>[1])],points);\n    let out;\n    forwardSeconds = 0;\n    try {out = await model({...embeddings,input_points:points,input_labels:labels});}\n    catch(error) {\n      dispose([points,labels]);\n      if (batch.length>1 && /Failed to allocate memory|out of memory|CUDA.*memory/i.test(String(error?.stack??error))) {\n        safeBatch=Math.max(1,Math.floor(batch.length/2));\n        console.warn(`Retrying same instances with prompt batch ${safeBatch}`);\n        continue;\n      }\n      throw error;\n    }\n    const elapsedForward = encoderSeconds + forwardSeconds;\n    const scores=out.iou_scores.data, candidates=out.iou_scores.dims.at(-1);\n    const h=out.pred_masks.dims.at(-2),w=out.pred_masks.dims.at(-1),area=h*w;\n    const selected = new Float32Array(batch.length*area);\n    const bestCandidates = new Int32Array(batch.length);\n    for (let i=0;i<batch.length;i++) {\n      let best=0;\n      for(let k=1;k<candidates;k++) if(scores[i*candidates+k]>scores[i*candidates+best]) best=k;\n      bestCandidates[i]=best;\n      selected.set(out.pred_masks.data.subarray((i*candidates+best)*area,(i*candidates+best+1)*area),i*area);\n    }\n    // Preserve each previously tested backend's postprocessing tensor shape.\n    const tracker = backend === 'sam3_onnx';\n    const low = tracker ? null : new Tensor('float32',selected,[1,batch.length,1,h,w]);\n    const full = (await processor.post_process_masks(tracker ? out.pred_masks : low,inputs.original_sizes,inputs.reshaped_input_sizes,{binarize:tracker}))[0];\n    const height=full.dims.at(-2),width=full.dims.at(-1);\n    for(let i=0;i<batch.length;i++) {\n      const offset = (tracker ? i*candidates+bestCandidates[i] : i)*height*width;\n      const record={sample_id:batch[i].sample_id,original:batch[i].original,\n                    prediction:encode(full.data,offset,height,width),forward_latency_s:elapsedForward/batch.length};\n      fs.writeSync(handle,JSON.stringify(record)+'\\n');\n      completed.add(record.sample_id);processed++;seen++;\n    }\n    fs.fsyncSync(handle);\n    const rate=processed/((Date.now()-started)/1000);\n    process.stdout.write(`\\r${seen} instances; ${rate.toFixed(2)} instances/s`);\n    dispose([points,labels,out.pred_masks,out.iou_scores,out.object_score_logits,low,full]);\n    encoderSeconds=0;\n    begin+=batch.length;\n  }\n  dispose(Object.values(embeddings));\n}\ntry {\n  let group=[];\n  for await(const line of readline.createInterface({input:fs.createReadStream(manifest),crlfDelay:Infinity})) {\n    if(!line.trim()) continue;\n    const item=JSON.parse(line);\n    if(group.length && group[0].image!==item.image) {await inferGroup(group);group=[];}\n    group.push(item);\n  }\n  if(group.length) await inferGroup(group);\n} finally {fs.fsyncSync(handle);fs.closeSync(handle);}\nconsole.log(`\\nCompleted ${seen} instances; predictions saved for Python mIoU evaluation.`);\n// Avoid a known ORT CUDA-provider destructor failure after synced output.\nprocess.exit(0);\n"
import uuid
_paths_spec = importlib.util.spec_from_file_location('_mask_model_paths', Path(__file__).with_name('paths.py'))
PATHS = importlib.util.module_from_spec(_paths_spec)
